UPDATE public.maternity_guidelines SET title_ka = COALESCE(title_ka, 'ვის შეუძლია მიმართოს?'), content_ka = COALESCE(content_ka, 'დეკრეტული დახმარების მისაღებად უნდა აკმაყოფილებდეთ შემდეგ პირობებს:

• უნდა იყოთ დასაქმებული ქალი (შრომითი ხელშეკრულების საფუძველზე)
