UPDATE public.maternity_guidelines SET title_ka = COALESCE(title_ka, 'განაცხადის წარდგენის პროცესი'), content_ka = COALESCE(content_ka, 'დეკრეტული ანაზღაურების მისაღებად გაიარეთ შემდეგი ეტაპები:

