-- ── mommy_daily_messages → ka (1460 sətir) ──
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საღამოს საათებში ბავშვის უმიზეზოდ ტირილი, ფეხების მუცელთან მიტანა და გაწითლება შესაძლოა აირებისგან გამოწვეული მუცლის ტკივილის (კოლიკის) დაწყებაზე მიუთითებდეს; ეს იმით არის განპირობებული, რომ მისი საჭმლის მომნელებელი სისტემა ჯერ სრულად არ ჩამოყალიბებულა. ნუ შეშინდებით — ეს ტკივილი ბავშვის ჯანმრთელობის პრობლემაზე არ მიუთითებს, მას უბრალოდ მცირედი დახმარება სჭირდება; მუცლის საათის ისრის მიმართულებით ნაზად დამასაჟება ან ფეხებით „ველოსიპედის“ მოძრაობების გაკეთება შვებას მოჰგვრის. ბავშვის მუცლით თქვენს მკლავზე დაწვენა და ასე ტარება („ვეფხვის პოზა“) ასევე შეამსუბუქებს მუცლის ტკივილს. მოთმინება გამოიჩინეთ — შეიძლება მოგეჩვენოთ, რომ ეს „დაუსრულებელი ღამეებია“, მაგრამ 3-4 თვის შემდეგ კოლიკა მთლიანად გაივლის.') WHERE id = 'bcbaede0-1b13-4f10-af2e-89c520ee8eac';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, თქვენი ბავშვი უკვე ზუსტად 2 კვირისაა! ამ პერიოდში ექიმები ბავშვებს, როგორც წესი, D ვიტამინის წვეთებს უნიშნავენ, რადგან დედის რძე, მიუხედავად იმისა, რომ იდეალური საკვებია, ჩვეულებრივ საკმარისი რაოდენობით D ვიტამინს არ შეიცავს და არც მზის სხივებია ყოველთვის საკმარისი. ძვლების სწორად განვითარებისა და რაქიტის პრევენციისთვის არ დაგავიწყდეთ ვიტამინის ექიმის მიერ დანიშნული დოზით მიცემა. ამასთანავე, ახლა პირველი სამედიცინო შემოწმებისთვის კარგი დროა; შეგიძლიათ პედიატრთან ვიზიტი დაგეგმოთ, რათა ბავშვის წონის მატება შეამოწმოთ და მის განვითარებასთან დაკავშირებული კითხვები დაუსვათ. თქვენ შესანიშნავად უმკლავდებით — პირველი რთული ეტაპი უკვე გადალახეთ!') WHERE id = '6f0bc18f-ecc7-4ad9-915b-db7cdf9694f7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დღეს ყურადღება ცოტათი ისევ თქვენს სხეულზე გადავიტანოთ; მშობიარობის შემდგომმა გამონადენმა (ლოქიამ) ფერი უნდა შეიცვალოს და უფრო ღია, მოყვითალო ან თეთრი გახდეს. თუ სისხლდენა მოულოდნელად გაძლიერდება ან გამონადენს უსიამოვნო სუნი ექნება, შესაძლოა სხეული გატყობინებდეთ, რომ „ზედმეტად იღლებით“ ან „ინფექციაა“; ამიტომ მძიმე ნივთების აწევას აუცილებლად მოერიდეთ. განსაკუთრებული ყურადღება მიაქციეთ პირად ჰიგიენას — ხშირი შხაპი მნიშვნელოვანია როგორც ფიზიკური სისუფთავისთვის, ისე განწყობის გასაუმჯობესებლად. გახსოვდეთ, სრულ გამოჯანმრთელებას კიდევ რამდენიმე კვირა დასჭირდება, ამიტომ, თუნდაც ჯერ ისევ ვერ გრძნობდეთ თავს სრულიად მხნედ, მიეცით თქვენს სხეულს დრო და მზრუნველობა.') WHERE id = '924b5e58-de0f-4e99-ae9e-3a1b97775596';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უსაფრთხო ძილის წესების დაცვა ბავშვის სიცოცხლისთვის უაღრესად მნიშვნელოვანია; ბავშვი ყოველთვის ზურგზე, მყარ ლეიბზე უნდა დააძინოთ. რბილი ბალიშები, სქელი საბნები ან საწოლში მოთავსებული სათამაშოები, რომლებსაც უფროსი თაობა ხშირად გვირჩევს, ბავშვისთვის დახრჩობის საფრთხეს ქმნის, ამიტომ მისი საწოლი მაქსიმალურად სადა და ცარიელი დატოვეთ. სპეციალური ორთოპედიული ბალიშები, რომლებსაც „თავის სწორად ჩამოყალიბებისთვის“ იყენებენ, უმეტესად საჭირო არ არის, რადგან ბავშვს თავის თავისუფლად მოძრაობა უნდა შეეძლოს. აკონტროლეთ ოთახის ტემპერატურა (20-22 გრადუსი იდეალურია) და ბავშვს ზედმეტად თბილად ნუ ჩააცვამთ, რადგან გადახურებაც ძილთან დაკავშირებულ რისკს წარმოადგენს.') WHERE id = '00815f0c-e81b-4156-a3e1-eda10e9b02f3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ალბათ გსმენიათ, რამდენად მნიშვნელოვანია ღვიძილობისას ბავშვის მუცელზე დაწვენა (tummy time), თუმცა შეიძლება თქვენს ბავშვს ეს საერთოდ არ მოეწონოს და მაშინვე ატირდეს. ეს ნორმალურია, მაგრამ ნუ დანებდებით; დღეში რამდენჯერმე, თითო ჯერზე სულ რაღაც 1-2 წუთით ცდა ძალიან მნიშვნელოვანია მისი კისრის, მხრებისა და მკლავების კუნთების გასაძლიერებლად. ეს ასევე თავის უკანა ნაწილის გაბრტყელების (პლაგიოცეფალიის) თავიდან აცილების ყველაზე ბუნებრივი გზაა. პროცესი უფრო სახალისო რომ გახადოთ, შეგიძლიათ მის წინ სარკე ან შავ-თეთრი ბარათები დადოთ, ან თავადაც მის გვერდით იატაკზე დაწვეთ და თვალით კონტაქტი დაამყაროთ.') WHERE id = '442f3095-2fe9-4071-b81b-22bb923583fd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გამოთქმა „ორმოც დღემდე ბავშვი გარეთ არ უნდა გაიყვანოთ“ უბრალოდ მოძველებული მითია; თუ ამინდი ხელს გიწყობთ და ბავშვი ჯანმრთელია, სუფთა ჰაერი ორივეს ძალიან გარგებთ. სახლში ჩაკეტილი ჰაერი, მტვერი და ბაქტერიები შეიძლება გარეთ არსებულ სუფთა ჰაერზე მეტად საზიანო იყოს; უბრალოდ მოერიდეთ ხალხმრავალ სავაჭრო ცენტრებსა და დახურულ სივრცეებს. ბავშვს თქვენზე მხოლოდ ერთი ფენით მეტი ტანსაცმელი ჩააცვით — მისი ზედმეტად შეფუთვა ოფლიანობასა და ავად გახდომას შეუწყობს ხელს. ხანმოკლე გასეირნება განწყობას აგიმაღლებთ, ბავშვს კი უფრო ღრმად დაძინებაში დაეხმარება.') WHERE id = '0f0e26dc-de3c-4b42-ba38-4351bd00e821';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, უკვე ერთი კვირაა, რაც დედა ხართ და სირთულეების მიუხედავად, ეს დღეები წარმატებით გადალახეთ! სარკეში ჩახედვისას შეიძლება დაინახოთ, რომ მუცელი ჯერ ბოლომდე არ დაგიპატარავდათ და თმაც არეული გაქვთ, მაგრამ თქვენ სასწაულს ზრდით და ასეთიც ძალიან ლამაზი ხართ. დღეიდან, როცა ბავშვს ღვიძავს, შეგიძლიათ მეთვალყურეობის ქვეშ მცირე ხნით (1-2 წუთით) მუცელზე დააწვინოთ (tummy time). ეს პატარა ვარჯიში მის კისრისა და ზურგის კუნთებს გააძლიერებს, აირებისგან გამოწვეული ჭვალის შემსუბუქებაში დაეხმარება და მომავალ ფიზიკურ განვითარებას საფუძველს შეუქმნის.') WHERE id = '33d098f8-b80c-478c-bb61-a7d57cd72e57';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შეიძლება ბავშვის კანს ან თვალის თეთრ გარსს ოდნავ მოყვითალო შეფერილობა შეამჩნიოთ; ეს ფიზიოლოგიური სიყვითლეა და უმეტეს შემთხვევაში ხშირი ძუძუთი კვების შედეგად ორგანიზმიდან გამოიდევნება. თუმცა, თუ სიყვითლე ფეხებისკენ ვრცელდება და ბავშვი ძალიან მოდუნებულია, აუცილებლად მიმართეთ ექიმს. ამასთანავე, ოთახის განიავების ნუ შეგეშინდებათ; მოსაზრება, რომ "ჯერ ორმოცი დღე არ გასულა და სუფთა ჰაერზე გაყვანა არ შეიძლება", მხოლოდ მითია — სუფთა ჰაერი როგორც თქვენი, ისე ბავშვის ტვინისთვის მნიშვნელოვანია. გააღეთ ფანჯარა და გაანიავეთ ოთახი, ან თუ შესაძლებლობა გაქვთ, ბავშვს ამინდის შესაბამისად ჩააცვით და მცირე ხნით სუფთა ჰაერზე გაიყვანეთ (თუ ექიმმა ნება დაგრთოთ).') WHERE id = '55de4073-ef7d-4cff-84f4-bf2b8f830118';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ჩვენს ბებიებს შეიძლება მოსწონდეთ ბავშვის მჭიდროდ შეხვევა, რათა ის "სწორი გაიზარდოს", თუმცა თანამედროვე მედიცინამ დაამტკიცა, რომ ბავშვის მენჯ-ბარძაყის სახსრის ჯანსაღი განვითარებისთვის ფეხები თავისუფლად უნდა მოძრაობდეს. თუ ბავშვი საკუთარი ხელ-ფეხის მოძრაობაზე კრთება და იღვიძებს, შეგიძლიათ მხოლოდ ხელები მსუბუქად შეუხვიოთ (ნაწილობრივი შეხვევა), მაგრამ აუცილებლად უზრუნველყავით, რომ ფეხები "ბაყაყის" პოზაში თავისუფლად ჰქონდეს. ბავშვის მჭიდროდ შეხვევამ და უმოძრაოდ გაჩერებამ შეიძლება მის სისხლის მიმოქცევასა და კუნთების განვითარებაზე უარყოფითად იმოქმედოს. მიეცით თავისუფლად მოძრაობის საშუალება, რათა ხელებითა და ფეხებით სამყარო შეიცნოს.') WHERE id = '94a133da-1fcc-4ffe-a24b-b9755a414c0b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე 10 დღეა, მთელი თქვენი ყურადღება და ფიქრი ბავშვისკენაა მიმართული, მაგრამ დღეს ეცადეთ, სულ მცირე 15-20 წუთი მხოლოდ საკუთარ თავს დაუთმოთ. მიიღეთ თბილი შხაპი, მოუსმინეთ საყვარელ მუსიკას, მოუარეთ კანს ან უბრალოდ ფანჯრიდან გაიხედეთ და ოცნებებს მიეცით. ნელ-ნელა შეეცადეთ, მენჯის ფსკერის კუნთები შეიგრძნოთ (კეგელის ვარჯიშების ყველაზე მსუბუქი ფორმა), რათა აღდგენის პროცესი დაჩქარდეს, თუმცა ინტენსიური ვარჯიშისთვის ჯერ ძალიან ადრეა. მოუსმინეთ საკუთარ სხეულს, პატივი ეცით მას და გახსოვდეთ, რომ თქვენ თქვენი შვილის უდიდესი საყრდენი ხართ — თქვენი ჯანმრთელობა და სულიერი სიმტკიცე მისთვის ყველაზე დიდი საჩუქარია.') WHERE id = '4ba69869-3aaa-471c-bba8-3e9678c5f231';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შესაძლოა, ბავშვის ჭიპლარის ნარჩენი უკვე გაშრა და მოძვრა, ან მალე მოძვრება; ეს სრულიად ბუნებრივი პროცესია და ჭიპის ადგილას მცირე სისხლიანი ლაქის დანახვამ არ შეგაშინოთ. ჭიპლარის ნარჩენის მოძრობის შემდეგ მნიშვნელოვანია, ეს უბანი კვლავ მშრალი და სუფთა შეინარჩუნოთ, რადგან ნოტიო გარემო ბაქტერიების გამრავლებისთვის ხელსაყრელია. ზოგჯერ დედები ღელავენ, რომ ჭიპი "გამობერილი" რჩება, თუმცა მუცლის კუნთების გამაგრებასთან ერთად ის ხშირად თავისით სწორდება; ამიტომ მოერიდეთ ისეთ ძველ მეთოდებს, როგორიცაა ჭიპზე მონეტის დამაგრება ან მისი მჭიდროდ გადაჭერა. თუ ჭიპის გარშემო სიწითლეს, უსიამოვნო სუნს ან ჩირქს შეამჩნევთ, დაუყოვნებლივ აცნობეთ ექიმს, სხვა შემთხვევაში კი უბრალოდ მიეცით ბუნებრივ პროცესს თავისით მიმდინარეობის საშუალება.') WHERE id = '4412d0c9-03dd-43c8-bb46-87b4fecadda2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ დღეებში შეიძლება შეამჩნიოთ, რომ ბავშვს თითქოს ვერაფრით აძღობთ — მუდმივად, ზოგჯერ ყოველ საათშიც კი სურს ძუძუს წოვა; მედიცინაში ამას "ზრდის ნახტომს" (growth spurt) უწოდებენ. დედები ხშირად ამ მდგომარეობას ასე განმარტავენ: "რძე შემიმცირდა, ბავშვი მშიერი დარჩა", ღელავენ და ხელოვნურ კვებაზე გადასვლას ჩქარობენ, თუმცა სინამდვილეში ამ გზით ბავშვი თქვენს სხეულს აძლევს სიგნალს — "მეტი რძე გამოიმუშავე", რათა მისი გაზრდილი მოთხოვნილება დაკმაყოფილდეს. მოთმინება იქონიეთ, ეს დროებითი მდგომარეობაა და ჩვეულებრივ ერთი-ორი დღე გრძელდება; უბრალოდ მიჰყევით ბავშვის მოთხოვნას და ხშირად მიიკარით მკერდზე. ამ პერიოდში ბევრი წყლის დალევა და დასვენება ძალას შეგმატებთ; გახსოვდეთ, რომ რძის რაოდენობა ბავშვის მოთხოვნილების შესაბამისად ბუნებრივად გაიზრდება.') WHERE id = '8aab5133-1153-4e9f-bfa1-1ddc76290148';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება, ძვირფასო დედა! დღეს თქვენი ცხოვრების სრულიად ახალი და, შესაძლოა, ყველაზე ამაღელვებელი ფურცელი იშლება. ახლა თქვენთვის ყველაზე მნიშვნელოვანია დაისვენოთ და ბავშვთან პირველი ფიზიკური კონტაქტი დაამყაროთ; საოჯახო საქმეები, სატელეფონო ზარები და სტუმრები მოიცდის. უნდა იცოდეთ, რომ პირველ დღეებში გამოყოფილი სქელი, მოყვითალო რძე (ხსენი), მართალია, მცირე რაოდენობითაა, მაგრამ საოცარი შემადგენლობა აქვს და ბავშვისთვის პირველი ვაქცინის როლს ასრულებს. ნუ შეგეშინდებათ, რომ რძე ცოტა გაქვთ, რადგან ბავშვის კუჭი ჯერ მხოლოდ ალუბლის ზომისაა და ეს წვეთები მისთვის სრულიად საკმარისია. ნუ ეცდებით, თავი გმირად წარმოაჩინოთ — ტკივილი და დაღლილობა სრულიად ბუნებრივია. უბრალოდ წამოწექით, შეიგრძენით ბავშვის სურნელი და სითბო და დატკბით ამ წუთებით, რადგან სწორედ ახლა ეყრება საფუძველი თქვენს კავშირს.') WHERE id = 'ced035b3-8303-4f5d-95fd-7e29e2539509';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენმა სხეულმა 9 თვის განმავლობაში საოცარი სამუშაო შეასრულა, ახლა კი შინაგანი ორგანოები ნელ-ნელა იწყებს ჩვეულ მდგომარეობაში დაბრუნებას. განსაკუთრებით ძუძუთი კვების დროს შეიძლება მუცლის ქვედა ნაწილში სპაზმური ტკივილი იგრძნოთ. ნუ შეშფოთდებით — ეს საშვილოსნოს შეკუმშვისა და უწინდელ ზომაზე დაბრუნების დადებითი ნიშანია. ნუ აჰყვებით საზოგადოებაში გავრცელებულ მცდარ მოსაზრებებს, როგორიცაა: „რძე ცოტა მაქვს, ბავშვი ვერ ძღება და ამიტომ ტირის“. ბავშვს შესაძლოა ძუძუ ხშირად არა მხოლოდ შიმშილის გამო სურდეს, არამედ იმისთვისაც, რომ თქვენი სურნელი შეიგრძნოს, გულისცემა გაიგონოს და თავი უსაფრთხოდ იგრძნოს. მიეცით მას ეს სიმშვიდე და დაცულობის განცდა — აიყვანეთ ხელში და ხშირად აწოვეთ ძუძუ. გახსოვდეთ, რომ რძის რაოდენობა ბავშვის წოვასთან ერთად მოიმატებს.') WHERE id = 'f5dc2c0a-cfb4-4205-ad61-5a643545c576';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ დღეებში შესაძლოა სარძევე ჯირკვლები რძით აგევსოთ, რამაც მკერდში სიმძიმისა და სიმხურვალის შეგრძნება შეიძლება გამოიწვიოს. ამავდროულად, ორგანიზმში ჰორმონების დონის მკვეთრი ცვლილების გამო შესაძლოა უმიზეზოდ მოწყენილი, ატირებული ან გაღიზიანებული იყოთ; მედიცინაში ამას „Baby blues“ ეწოდება. ეს გრძნობები არ ნიშნავს, რომ „ცუდი დედა“ ხართ ან სათანადო უნარები არ გაქვთ — ეს უბრალოდ ფიზიოლოგიური და დროებითი პროცესია. ნუ შეიკავებთ ცრემლებს; თუ ტირილი გინდათ, იტირეთ და ემოციებს გასაქანი მიეცით. ნუ მოგერიდებათ ამის შესახებ ახლობლებთან საუბარი. თქვენ მარტო არ ხართ — ამ გარდამავალ პერიოდს თქვენ მსგავსად ათასობით დედა გადის. ღრმად ჩაისუნთქეთ და უბრალოდ მიეცით დროს საშუალება, თავისი გააკეთოს.') WHERE id = '04d25f7c-e375-4514-ac39-dc2728da56e3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ენერგიის აღსადგენად კვებას განსაკუთრებული ყურადღება უნდა მიაქციოთ, თუმცა გვერდზე გადადეთ მოძველებული აკრძალვები, როგორიცაა: „გაცივდები“, „ხილი არ ჭამო“ ან „წყალი არ დალიო“. მრავალფეროვანი, ვიტამინებით მდიდარი კვება და საკმარისი სითხის მიღება მნიშვნელოვანია არა იმდენად რძის ხარისხისთვის, რამდენადაც თქვენი ფიზიკური ძალების აღდგენისა და ფსიქოლოგიური მხნეობის შესანარჩუნებლად. რაც შეეხება ბავშვის ჭიპლარს, მისი სპირტით დამუშავება ან შეხვევა საჭირო არ არის. უბრალოდ ყურადღება მიაქციეთ, რომ ის მშრალი და სუფთა დარჩეს. საფენის ჩაცმისას ჭიპის მიდამო ღია დატოვეთ, რათა ჰაერი მოხვდეს — ჰაერთან კონტაქტი შეხორცების დასაჩქარებლად საუკეთესო საშუალებაა.') WHERE id = '5cdec801-b16c-449e-bf65-9a37a9e133f1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება იმ დღეებში, როცა ღამე და დღე ადგილებს ცვლის და უძილობა თავს იჩენს, ძლიერო დედა! გარშემომყოფებმა შეიძლება გითხრან, „ბავშვი ხელში აყვანას არ მიაჩვიო“, მაგრამ იცოდეთ, რომ პირველ თვეებში ბავშვის „განებივრება“ შეუძლებელია. მას თქვენ სჭირდებით, ხოლო ხელში ტარება და კანით კანთან კონტაქტი როგორც მისი ტვინის განვითარებისთვის, ისე თქვენი რძის რაოდენობის გასაზრდელად ერთ-ერთი ყველაზე ეფექტური გზაა. საოჯახო საქმეები არსად გაიქცევა და არც უშავს, თუ ჭურჭელი დაურეცხავი დარჩება — თქვენი ძილი და დასვენება ყველაფერზე მნიშვნელოვანია. როგორც კი ბავშვი დაიძინებს, თქვენც ეცადეთ, თვალები დახუჭოთ და დაისვენოთ; თუნდაც 15-წუთიანი ძილი ენერგიას შეგმატებთ.') WHERE id = '726dd7ee-a857-41fc-aad0-622f7b5ddf29';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'არ ხართ ვალდებული, ყველაფერი მარტო გააკეთოთ და „სუპერდედის“ სახე შექმნათ; დახმარების თხოვნა სისუსტე კი არა, პირიქით, სიძლიერის ნიშანია. მეუღლეს, დედას ან სხვა ახლობელს კონკრეტულ საქმეებში დახმარება სთხოვეთ — მაგალითად, საჭმელი მოგიტანონ ან ბავშვს მიხედონ, სანამ შხაპს იღებთ. საკუთარ თავზე ზრუნვა, მოწესრიგება და ერთი ფინჯანი ცხელი ჩაის დალევა ეგოიზმი არ არის — ეს აუცილებელია, რათა დედის მოვალეობები უკეთ შეასრულოთ. გახსოვდეთ: ბედნიერი და დასვენებული დედა ბედნიერ ბავშვს ნიშნავს, ამიტომ ნუ მოგერიდებათ თქვენი ტვირთის სხვებისთვის გაზიარება.') WHERE id = '1ddced84-3654-418b-9996-21c50802a72f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მეორე თვეში! თქვენ და თქვენი ბავშვი უკვე უკეთ იცნობთ ერთმანეთს და თქვენს ცხოვრებაში გარკვეული „რიტმი“ იწყებს ჩამოყალიბებას. ყურადღება მიაქციეთ: „რეჟიმს“ კი არა, „რიტმს“ ვამბობთ, რადგან ბავშვი ჯერ საათის მიხედვით ცხოვრებისთვის მზად არ არის, თუმცა ძილის, კვებისა და სიფხიზლის თანმიმდევრობა თანდათან ყალიბდება. ამ პერიოდში ნუ ეცდებით მკაცრი განრიგის შედგენას — უბრალოდ დააკვირდით ბავშვის ძილის ნიშნებს (მთქნარება, თვალების სრესა) და შეეცადეთ, ზედმეტად დაღლამდე დააძინოთ. თუ ჯერ კიდევ ყველაფერი ქაოსად გეჩვენებათ, არ ინერვიულოთ — ამ ქაოსშიც კი დიდი წესრიგია და თქვენ შესანიშნავად ართმევთ თავს.') WHERE id = '014f9c15-8f59-4b13-b689-2c5db7a165c4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როდესაც ბავშვს მუცელზე აწვენთ (tummy time), შეიძლება უკვე შეამჩნიოთ, რომ ის რამდენიმე წამით მაინც ცდილობს თავის აწევას — ეს მისი კისრის კუნთების გაძლიერების პირველი ნიშანია. ამ ვარჯიშების გასახალისებლად წინ დაუდეთ ფერადი სათამაშო ან უბრალოდ მის პირისპირ დაწექით და ესაუბრეთ. თუ ჯერ თავს ვერ სწევს, ნუ შეშფოთდებით — ყველა ბავშვი განსხვავებული ტემპით ვითარდება. უბრალოდ მოთმინებით განაგრძეთ: ეს პატარა მცდელობები მომავალში მისი ხოხვისა და სიარულის საფუძველია.') WHERE id = 'edef290e-ee82-45c6-adef-de36a35e9688';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ალბათ აქამდე შეგიმჩნევიათ, როგორ იღიმის ბავშვს ძილში — ხალხში ამბობენ, „ანგელოზებს ეთამაშებაო“ (სინამდვილეში ეს რეფლექსია), თუმცა უკვე ახლოვდება „სოციალური ღიმილის“ პერიოდი. ბავშვმა შეიძლება შემოგხედოთ და თქვენს ხმას ან სახის გამომეტყველებას გააზრებული ღიმილით უპასუხოს. ეს უბრალოდ მიმიკა კი არა, მისი პირველი გზაა, გითხრათ: „გცნობ და მიყვარხარ“. საუბრისას თვალებში შეხედეთ და გაუღიმეთ — ისიც შეეცდება, პასუხი გაგცეთ. ასეთი ორმხრივი ურთიერთობა მისი ემოციური ინტელექტის განვითარების ერთ-ერთი ყველაზე ძლიერი სტიმულია.') WHERE id = '33d46eab-d81b-465a-acf9-3431f678ba0a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ზოგჯერ ოთახში შედიხართ და ფიქრობთ: „აქ რატომ მოვედი?“ ან ყველაზე მარტივი სიტყვებიც კი ვერ გახსენდებათ? ამას ხუმრობით „დედის ტვინს“ (Mom brain) უწოდებენ და ეს სრულიად რეალური, ფიზიოლოგიური მდგომარეობაა. უძილობა და ჰორმონული ცვლილებები ტვინის ყურადღების ცენტრს ცვლის — თითქოს ტვინი მთელ რესურსს ბავშვისკენ მიმართავს და სხვა „უმნიშვნელო“ საკითხებს შლის. ნუ იფიქრებთ, რომ „დასულელდით“ — ეს დროებითი დაბინდულობაა. მნიშვნელოვანი საქმეების ბლოკნოტში ან ტელეფონში ჩაწერა ამ პერიოდის უფრო მარტივად გადალახვაში დაგეხმარებათ; თქვენი გონება მალე ძველებურ სიმახვილეს დაიბრუნებს.') WHERE id = 'd8c08c2a-72db-44c1-9834-75d63110369c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მხედველობა ვითარდება და მან შეიძლება უკვე დაიწყოს მოძრავი საგნებისთვის თვალის გაყოლება (tracking). დაიჭირეთ თითი ან ფერადი სათამაშო მისი სახიდან 20-30 sm-ის დაშორებით და ნელა ამოძრავეთ მარჯვნივ-მარცხნივ — ის შეეცდება, მზერით გააყოლოს თვალი. ეს მარტივი თამაში თვალის კუნთებსა და ტვინსა და თვალებს შორის კოორდინაციას ავითარებს. თუ ბავშვი მაშინვე არ რეაგირებს, შესაძლოა დაღლილი იყოს; ნუ დააძალებთ და სხვა დროს კვლავ სცადეთ.') WHERE id = '8bc192a0-eebe-4dd4-8ce3-ca56d11958b8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მართალია, თქვენს ბავშვს ჯერ ლაპარაკი არ შეუძლია, მაგრამ ის შესანიშნავი მსმენელია. დღის განმავლობაში ყველაფრის გახმოვანება, რასაც აკეთებთ („ახლა საფენს ვიცვლით“, „შეხედე, ეს ფანჯარაა“), მისი მეტყველების შემდგომი განვითარებისთვის უმნიშვნელოვანესია. კვლევები აჩვენებს, რომ ბავშვებს, რომლებსაც მშობლები ხშირად ესაუბრებიან, მომავალში უფრო მდიდარი ლექსიკური მარაგი აქვთ. დაუსვით კითხვები და ცოტა ხნით შეჩერდით, თითქოს მის პასუხს ელოდებით (მაგალითად: „რძე დალიე? ყოჩაღ!“). ასეთი „დიალოგი“ მას ურთიერთობის წესებს ასწავლის და თქვენ შორის კავშირს აძლიერებს.') WHERE id = '99451123-a037-4f29-a96e-5e981ce03fe5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ფრჩხილები შეიძლება ქაღალდივით თხელი, მაგრამ სამართებელივით ბასრი იყოს და უნებლიე მოძრაობებისას მან სახე დაიკაწროს. ფრჩხილების დაჭრა შეიძლება ძალიან სტრესულად გეჩვენებოდეთ; ყველაზე მარტივი გზაა, ბავშვს ღრმა ძილის დროს სპეციალური საბავშვო მაკრატლით ფრთხილად დააჭრათ ფრჩხილები. ზოგი დედა ხელთათმანების გამოყენებას ამჯობინებს, თუმცა ბავშვი სამყაროს ხელებით შეხებისას შეისწავლის, ხელების დაფარვამ კი შეიძლება მისი განვითარება შეაფერხოს და თვითდამშვიდების უნარს ხელი შეუშალოს. ნუ შეგეშინდებათ — თუ შემთხვევით კანი ოდნავ გაიჭრა, საკმარისია სუფთა ბამბა მიაჭიროთ; ჭრილობა მალე შეხორცდება. გამბედაობა მოიკრიბეთ!') WHERE id = '3eb8e784-2dc2-4db5-bcf8-7391a821ce01';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მშობიარობის შემდგომ ამ პერიოდში შეიძლება ზოგჯერ სამყაროსგან მოწყვეტილად იგრძნოთ თავი, თითქოს მხოლოდ ძუძუთი კვებისა და საფენების გამოცვლისთვის შექმნილი „რობოტი“ იყოთ. მაგრამ გახსოვდეთ, რომ თქვენ მხოლოდ დედა არ ხართ — მეგობარი, მეუღლე და საკუთარი ინტერესების მქონე პიროვნებაც ხართ. დღეს, როცა ბავშვს დაეძინება, დაურეკეთ მეგობარს, სოციალურ მედიაში რაიმე საინტერესო წაიკითხეთ ან უბრალოდ ფანჯრიდან გაიხედეთ და თქვით: „მე აქ ვარ და ყველაფერი კარგადაა“. თქვენი ფსიქიკური ჯანმრთელობა არანაკლებ მნიშვნელოვანია, ვიდრე ფიზიკური; თუ თავს იზოლირებულად გრძნობთ, გაუზიარეთ ეს განცდები ახლობლებს — საუბარი ტვირთს შეგიმსუბუქებთ.') WHERE id = 'e0cd0853-270f-4ca4-a662-76294120406b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნუ შეგაშინებთ, თუ ამ დღეებში ბავშვი ისე იქცევა, თითქოს რძით ვერასდროს ნაყრდება, მუდმივად ითხოვს ძუძუს და ძილიც დაერღვა; დიდი ალბათობით, ეს „მე-3 კვირის ზრდის ნახტომია“ (growth spurt). ამ პერიოდში ბავშვის ორგანიზმი სწრაფად იზრდება და ამიტომ მეტი ენერგია სჭირდება, თქვენი სხეული კი ამ მოთხოვნასთან შესაგუებლად მეტი რძის გამომუშავებას ცდილობს. ამ ეტაპზე დედების ყველაზე დიდი შეცდომაა, როდესაც ფიქრობენ, რომ „რძე შეუწყდათ“ და ხელოვნურ კვებაზე გადადიან; სინამდვილეში ეს დროებითი კრიზისია და ერთადერთი გამოსავალია, ბავშვი იმდენჯერ აწოვოთ, რამდენჯერაც მოითხოვს, საათისთვის შეხედვის გარეშე. მოითმინეთ — ეს დაძაბული პერიოდი, ჩვეულებრივ, 24-48 საათში გაივლის და რძის რაოდენობაც კვლავ დარეგულირდება.') WHERE id = '2fdd98da-1e6c-412b-96b1-b850d42327b4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის გლუვ, აბრეშუმივით სახეზე შეიძლება მოულოდნელად პატარა წითელი გამონაყარი ან მუწუკები შენიშნოთ; მაშინვე ნუ დაიწყებთ საკუთარი თავის დადანაშაულებას ფიქრით: „რა შევჭამე ისეთი, რომ ბავშვს ეს დაემართა?“ ამას „ახალშობილთა აკნე“ ეწოდება და ორსულობის დროს ბავშვისთვის გადაცემული თქვენი ჰორმონების მისი ორგანიზმიდან გამოდევნის პროცესს უკავშირდება. ეს გამონაყარი ალერგია არ არის, ამიტომ მისი მოჭერა, სპირტით დამუშავება ან სხვადასხვა კრემის წასმა კატეგორიულად დაუშვებელია — ამან შეიძლება მხოლოდ კანი დააზიანოს. საკმარისია, ბავშვს სახე ყოველდღე თბილი, ანადუღარი წყლით გაუწმინდოთ; გამონაყარი რამდენიმე კვირაში თავისით გაქრება.') WHERE id = 'c3f99f3b-1467-413f-94c0-72c3e11f5099';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საღამოს დაწყებულმა და საათობით გაგრძელებულმა ცნობილმა ტირილის შეტევებმა (კოლიკამ) ამ პერიოდში შესაძლოა პიკს მიაღწიოს; ბავშვის დასამშვიდებლად სცადეთ „თეთრი ხმაურის“ (white noise) გამოყენება. დედის საშვილოსნოში ბავშვი მუდმივად ისმენდა სისხლის მიმოქცევისა და ორგანოების ხმებს, ამიტომ ფენის, მტვერსასრუტის ხმა ან ტელეფონში ჩართული „თეთრი ხმაურის“ აპლიკაციები მისთვის ნაცნობია და უსაფრთხოების განცდას უქმნის. ბავშვის მჭიდროდ ჩახუტებამ, რიტმულად რწევამ და ამ ხმების მოსმენინებამ შეიძლება მისი ნერვული სისტემა დაამშვიდოს. გახსოვდეთ, ეს ტირილი თქვენი ბრალი არ არის — ის უბრალოდ ბავშვის ჯერ კიდევ არასრულად განვითარებული საჭმლის მომნელებელი სისტემის რეაქციაა.') WHERE id = '401736ab-8891-41f0-a7a6-17ce6782e7e4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მხედველობა უკვე იწყებს განვითარებას, თუმცა ის ჯერ კიდევ ვერ არჩევს ფერებს სრულად და სამყაროს უმეტესად ბუნდოვანი ჩრდილების სახით ხედავს. მისი ყურადღების მისაპყრობად და ტვინის განვითარების ხელშესაწყობად შეგიძლიათ გამოიყენოთ შავ-თეთრი ბარათები ან მკვეთრი კონტრასტის მქონე სათამაშოები; ისინი ბავშვის სახიდან დაახლოებით 20-30 სმ-ის დაშორებით უნდა დაიჭიროთ. დაინახავთ, როგორ მიაპყრობს ბავშვი მზერას ამ ბარათებს და ყურადღებით დააკვირდება. ეს მარტივი თამაში ავარჯიშებს როგორც მის თვალის კუნთებს, ისე ხელს უწყობს ტვინის უჯრედებს (ნეირონებს) შორის ახალი კავშირების წარმოქმნას.') WHERE id = '6acb903b-f503-4e0a-bf5a-5cedae1d83e4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ჩვენს საზოგადოებაში ფართოდ გავრცელებულმა საკვებთან დაკავშირებულმა აკრძალვებმა, როგორიცაა „პომიდორს ნუ შეჭამ, ბავშვს დასწვავს“ ან „ოსპს ნუ შეჭამ, ბავშვს მუცელი გაებერება“, დაგღალათ, უნდა იცოდეთ, რომ თანამედროვე მედიცინა ამ მოსაზრებებს არ ადასტურებს. თქვენ მიერ მიღებულ საკვებში არსებული აირები პირდაპირ დედის რძეში არ გადადის; რძე სისხლისგან წარმოიქმნება და არა კუჭში არსებული აირებისგან. თუ კონკრეტული საკვების მიღების შემდეგ ბავშვს მართლაც არ აღენიშნება დისკომფორტი (ასეთი რამ ძალიან იშვიათად, ძროხის რძის ცილის მიმართ ალერგიის დროს ხდება), თავს უსარგებლო დიეტით ნუ შეზღუდავთ. ვიტამინებითა და ცილებით მდიდარი, მრავალფეროვანი კვება როგორც რძის ხარისხისთვის, ისე თქვენი ფსიქოლოგიური ჯანმრთელობისთვის შიმშილზე ბევრად სასარგებლოა.') WHERE id = '0f643a6c-2b94-498e-845b-b4547838a7e6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მუდმივად ხელში ტარებამ შეიძლება ზურგი აგატკიოთ, ამიტომ სწორად შერჩეული სლინგი ან ერგონომიული ზურგჩანთა (და არა კენგურუ!) შესაძლოა თქვენი საუკეთესო დამხმარე გახდეს. ყურადღებას ნუ მიაქცევთ ფრაზებს: „ბავშვი მიეჩვევა“ ან „ხერხემალი გაეღუნება“; პირიქით, ერგონომიული სატარებელი, რომელშიც ბავშვის ფეხები ასო „M“-ის ფორმაშია (ბაყაყის პოზაში), ძალიან სასარგებლოა მისი მენჯ-ბარძაყის სახსრების განვითარებისთვის. ეს პოზა ბავშვს დედის მუცელში არსებულ სიმყუდროვეს ახსენებს და ამშვიდებს, თქვენ კი ორივე ხელი თავისუფალი გრჩებათ და შეგიძლიათ სახლის საქმეები გააკეთოთ ან უბრალოდ მშვიდად დალიოთ ჩაი. სიახლოვის განცდა ორივეს სეროტონინით (ბედნიერების ჰორმონით) აგავსებთ.') WHERE id = 'a2fbf383-d8f0-4347-a3ef-d35f626ab799';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ გაწუხებთ, რომ სახლში მოსულ სტუმრებს ბავშვის კოცნა და ხელიდან ხელში გადაყვანა სურთ, „არას“ თქმასა და საზღვრების დაწესებას ნუ მოერიდებით. ბავშვის იმუნური სისტემა ჯერ კიდევ ძალიან სუსტია და ჰერპესის ვირუსი, რომელიც ზრდასრულებისთვის ჩვეულებრივი ინფექციაა, ბავშვის სიცოცხლეს შეიძლება საფრთხეს უქმნიდეს. სრული უფლება გაქვთ, სტუმრებს თავაზიანად სთხოვოთ, დაიბანონ ხელები, ავადმყოფობის შემთხვევაში არ მოვიდნენ და ბავშვს სახესა და ხელებზე არ აკოცონ. თუ ამის გამო ვინმე განაწყენდება, ეს მათი პრობლემაა; თქვენი მთავარი მოვალეობა ბავშვის დაცვაა და არა სხვების გულის არტკენა.') WHERE id = '7b5d5e0e-5e56-4eb3-b899-1d95dce7cd83';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, საოცარო დედა! დღეს თქვენი ბავშვი ზუსტად 1 თვის გახდა! გაიხსენეთ, რამდენი სირთულე გადალახეთ ამ ერთი თვის განმავლობაში, რამდენი ღამე გაათენეთ და მაინც როგორი ძლიერი დარჩით — იამაყეთ საკუთარი თავით. ახლა ასევე ბავშვის ყოველთვიური სამედიცინო შემოწმების დროა (წონისა და სიმაღლის გაზომვა); მის მიერ მომატებული თითოეული გრამი თქვენი შრომის შედეგია. დღეს გადაუღეთ ბავშვს 1 თვის სამახსოვრო ფოტო, ჩაინიშნეთ თარიღი და ეს პატარა იუბილე, თუნდაც მხოლოდ ერთი ნაჭერი ტორტით, აუცილებლად აღნიშნეთ. დრო ძალიან სწრაფად გადის და ამ მომენტების აღბეჭდვა მომავალში ერთ-ერთი ყველაზე ძვირფასი მოგონება იქნება.') WHERE id = '520fba19-0b3a-4361-9ce1-dac3a718ebb0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ბავშვის დაბანისას გეშინიათ, რომ ყურში წყალი ჩაუვა, ნუ შეშფოთდებით; ყურის აპკი შიგნითა ყურს წყლისგან იცავს და ყურში წყლის მოხვედრა, ჩვეულებრივ, სერიოზულ პრობლემას არ იწვევს (თუ აპკი დაზიანებული არ არის). ბანაობა ბავშვისთვის მხოლოდ სისუფთავეს კი არა, გართობასა და მოდუნებასაც ნიშნავს; თუ წყალი უყვარს, ყოველ საღამოს ერთსა და იმავე დროს, დაძინებამდე მისი დაბანა ძილის შესანიშნავ რიტუალად შეიძლება იქცეს. თბილი წყალი კუნთებს ადუნებს, დამამშვიდებლად მოქმედებს და ბავშვს აძლევს სიგნალს: „უკვე ღამეა, ძილის დროა“. დაბანის შემდეგ თბილ პირსახოცში გაახვიეთ და მსუბუქად გაუკეთეთ მასაჟი — ეს ჩაძინებას გაუადვილებს.') WHERE id = 'd1cd229a-65ce-4753-a5dc-ce53e13d2100';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მშობიარობის შემდგომი პირველი თვის შემდეგ სევდიანი და ემოციურად მგრძნობიარე პერიოდი, რომელსაც „Baby blues“ ეწოდება, ჩვეულებრივ, უკვე დასრულებული უნდა იყოს; თუ კვლავ მუდმივად სევდას, უიმედობას, დაღლილობას ან ბავშვის მიმართ გულგრილობას გრძნობთ, ყურადღება მიაქციეთ. ეს შეიძლება მშობიარობის შემდგომი დეპრესია (მშდ) იყოს. ეს არავითარ შემთხვევაში არ არის თქვენი ბრალი, ახირება ან სისუსტე — მიზეზი ჰორმონული და ქიმიური დისბალანსია. ნუ გააკრიტიკებთ საკუთარ თავს სიტყვებით: „დედა ვარ და უნდა გავუძლო“; თუ შინაგანი სიცარიელის განცდა არ ქრება, აუცილებლად გაესაუბრეთ ექიმს ან ფსიქოლოგს. თქვენი ფსიქიკური ჯანმრთელობა ბავშვის ფიზიკურ ჯანმრთელობაზე არანაკლებ, შესაძლოა უფრო მეტადაც კი, მნიშვნელოვანია.') WHERE id = '792d4a29-1f99-4846-89d2-54738a980f78';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '6-8 კვირა (ანუ ახლანდელი პერიოდი) შეიძლება ბავშვის ტირილის პიკი იყოს. ზოგჯერ მან შეიძლება უმიზეზოდ იტიროს, მაშინაც კი, როცა დანაყრებულია და საფენიც სუფთა აქვს. ეს მისი ნერვული სისტემის გარშემო არსებული ხმებით, სინათლითა და სხვა სტიმულებით გადატვირთვის შედეგია. თავს ნუ დაიდანაშაულებთ — ეს თქვენს "ცუდ დედობასთან" კავშირში არ არის, არამედ განვითარების ბუნებრივი ნაწილია. უბრალოდ მის გვერდით იყავით, ჩაეხუტეთ და უთხარით: "ესეც გაივლის". მართლაც, რამდენიმე კვირაში ასეთი ტირილი მკვეთრად შემცირდება.') WHERE id = 'c94543e8-f599-4ccd-918b-88ff573157bb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენმა ბავშვმა უკვე დაიწყო "აღუს" თქმა ან ყელიდან ბგერების გამოცემა? ეს მეტყველების განვითარების პირველი ეტაპია! როცა ის ხმას გამოსცემს, თქვენც იმავე ბგერით უპასუხეთ, თითქოს "საუბრობთ". კვლევები აჩვენებს, რომ როცა მშობელი ბავშვის ბგერებს იმეორებს, ამით გადასცემს გზავნილს: "მე შენი მესმის და გიგებ". ეს მარტივი თამაში ბავშვს თავდაჯერებას მატებს და მომავალში მეტყველების უფრო ადრე დაწყებას უწყობს ხელს.') WHERE id = '045f5830-2fde-4a82-b369-03b2e1dcea23';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სარკეში ჩახედვისას შეიძლება კვლავ დაინახოთ ორსულობის შემდეგ დარჩენილი ზედმეტი წონა ან მოშვებული მუცელი და გული დაგწყდეთ. გახსოვდეთ, მუცელი 9 თვის განმავლობაში იზრდებოდა და სრულად აღდგენასაც სულ მცირე ამდენივე დრო სჭირდება. მკაცრმა დიეტებმა (განსაკუთრებით მეძუძურ დედებში) შეიძლება რძის შემცირება და თმის ცვენა გამოიწვიოს. ახლა წონის დაკლებაზე კი არა, ჯანსაღ კვებაზე იფიქრეთ. ბევრი წყალი, ბოსტნეული და ცილა თქვენი საუკეთესო მეგობრებია. ნუ შეიძულებთ საკუთარ სხეულს — მან მსოფლიოში ყველაზე მშვენიერი საჩუქარი გაჩუქათ.') WHERE id = '772a8327-4bbe-46b7-9c90-09e5deaa584b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'იმისთვის, რომ "მუცელზე წოლის დრო" (tummy time) უფრო სახალისო გახადოთ, სცადეთ თამაში "თვითმფრინავი". დაწექით ზურგზე, მოხარეთ მუხლები, ბავშვი წვივებზე მუცლით დააწვინეთ და ნელა აქანავეთ (რა თქმა უნდა, ხელებით დაიჭირეთ). ასე ბავშვი სამყაროს განსხვავებული კუთხით დაინახავს, თქვენთან თვალით კონტაქტს დაამყარებს და ვესტიბულურ აპარატსაც (წონასწორობის შეგრძნებას) განივითარებს. ბავშვებს იატაკზე მარტო ყოფნას დედის სხეულზე ვარჯიში ურჩევნიათ.') WHERE id = 'f63c5890-33d1-4cec-a07d-853961a0ca97';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მიუხედავად იმისა, რომ ღამის ძილი ჯერ სრულად არ დარეგულირებულა, დღის ძილი (nap) შეიძლება შემოკლდეს. თუ თქვენს ბავშვს დღისით სულ რაღაც 20-30 წუთი სძინავს და შემდეგ იღვიძებს, ნუ ჩათვლით, რომ "დაიძინა და მორჩა". ზოგჯერ ბავშვები ძილის ციკლებს შორის (ყოველ 40-45 წუთში) იღვიძებენ, თუმცა სინამდვილეში ჯერ კარგად არ გამოუძინიათ. გაღვიძებისთანავე ნუ აანთებთ შუქს და ნუ დაიწყებთ თამაშს; მის გვერდით დაწექით, ნაზად დაამშვიდეთ ან ძუძუთი კვებით ეცადეთ, ძილი გაუხანგრძლივოთ.') WHERE id = '2c5835b8-b6ba-41d1-b215-505864265cfb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დროა, ექიმს გაესაუბროთ მოახლოებული 2 თვის ასაკში ჩასატარებელი აცრების (ვაქცინაციის) შესახებ. აზერბაიჯანის აცრების ეროვნული კალენდრის მიხედვით, ამ პერიოდში გათვალისწინებულია ყივანახველის, დიფტერიის, ტეტანუსის, B ჰეპატიტისა და სხვათა საწინააღმდეგო (Hexaxim ან მსგავსი), ასევე როტავირუსისა და პნევმოკოკის საწინააღმდეგო ვაქცინები. ნუ დაუჯერებთ გარშემო გავრცელებულ, მეცნიერულ საფუძველს მოკლებულ შემაშინებელ ჭორებს, როგორიცაა "ვაქცინა საზიანოა" ან "ბავშვი ვერ ალაპარაკდება". ვაქცინა ყველაზე ძლიერი ფარია, რომელიც ბავშვს მომავალში სასიკვდილო დაავადებებისგან იცავს. კითხვები "მეზობელ დეიდას" კი არა, თქვენს პედიატრს დაუსვით.') WHERE id = '28360eb0-4c71-4798-a428-29239685c45f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მასაჟი საოცარი საშუალებაა როგორც აირებისგან გამოწვეული კოლიკის შესამსუბუქებლად, ისე მის დასამშვიდებლად. ხელებზე ცოტაოდენი ბუნებრივი საბავშვო ზეთი წაისვით, დარწმუნდით, რომ ოთახში თბილა და ბავშვს ფეხებიდან ზემოთ, ნაზი მოძრაობებით გაუკეთეთ მასაჟი. შეხებისას გამოყოფილი ჰორმონი ოქსიტოცინი თქვენც დაგამშვიდებთ და ბავშვსაც. ამ რიტუალის ყოველ საღამოს, ბანაობის შემდეგ გამეორება მას ღამით უფრო მშვიდად დაძინებაში დაეხმარება.') WHERE id = '030269db-0cd6-4191-b990-5149723f7ac1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'რადგან მთელი ყურადღება ბავშვზეა გადატანილი, შეიძლება მოგეჩვენოთ, რომ მეუღლესთან თქვენი ურთიერთობა უკანა პლანზე გადავიდა — და ეს სრულიად ნორმალურია. თუმცა ეცადეთ, „მშობლობისას“ არ დაგავიწყდეთ, რომ „წყვილიც“ ხართ; როცა ბავშვს სძინავს, ერთად ჩაის დალევამ, ჩახუტებამ ან სულაც 10 წუთით იმაზე საუბარმა, თუ როგორ ჩაიარა დღემ, შეიძლება თქვენ შორის გაჩენილი სიგრილე გააქროს. მამასაც მიეცით ბავშვთან კავშირის ჩამოყალიბების შესაძლებლობა (მაგალითად, ბავშვისთვის ბოყინის ამოშვებაში დახმარება ან მისი დაბანა შეიძლება მამამ ითავოს). იმის განცდა, რომ ერთი გუნდი ხართ, ამ რთულ დღეებში ორივეს ძალას მოგცემთ.') WHERE id = '7b078d0d-8755-48b3-a240-4b2c014cdd7f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მიუხედავად იმისა, რომ ბავშვი ჯერ არ დაცოცავს, უნებლიე მოძრაობებით შეიძლება გადაბრუნება სცადოს, რაც უსაფრთხოების საკითხს განსაკუთრებით მნიშვნელოვანს ხდის. ოქროს წესი: ბავშვი არასოდეს დატოვოთ მარტო შემაღლებულ ზედაპირზე (დივანზე, საწოლზე, გამოსაცვლელ მაგიდაზე), თუნდაც მხოლოდ ერთი წამით. ნუ დამშვიდდებით იმ აზრით, რომ „ჯერ არ მოძრაობს“ — პირველი გადაბრუნება, როგორც წესი, ყველაზე მოულოდნელ მომენტში ხდება. მისი მარტო დატოვება მხოლოდ იატაკზე დაფენილ ხალიჩაზე ან სპეციალურ სათამაშო ხალიჩაზე შეგიძლიათ (რა თქმა უნდა, თქვენი მეთვალყურეობის ქვეშ). უსაფრთხოების ჩვევების ახლავე გამომუშავება მომავალში უბედური შემთხვევების თავიდან აცილებაში დაგეხმარებათ.') WHERE id = '0720bc24-8ac8-43a4-b347-e7e20231713d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'და აი, დადგა ხალხში განსაკუთრებული მნიშვნელობის მქონე დღე — „ბავშვს ორმოცი დღე შეუსრულდა“! გილოცავთ! ძველი ტრადიციების მიხედვით, ამ დღეს ტარდება განბანვის განსაკუთრებული რიტუალი („ორმოცის წყალი“) და დედა-შვილს უკვე თავისუფლად შეუძლია საზოგადოებაში გასვლა. სამედიცინო თვალსაზრისით კი ეს 6-კვირიანი აღდგენის პერიოდის დასრულებას ნიშნავს (ლოქიის შეწყვეტა, საშვილოსნოს შეკუმშვა). აღნიშნეთ ეს დღე, როგორც დღესასწაული — გამოეწყვეთ, გალამაზდით და, იქნებ, ბავშვთან ერთად პირველ ხანგრძლივ „ოფიციალურ“ გასეირნებაზეც გახვიდეთ. „ორმოცი“ მხოლოდ რიცხვი არ არის — ის თქვენი „ახალბედა დედის“ სტატუსიდან „გამოცდილი დედის“ სტატუსზე გადასვლის სიმბოლოა. თქვენ ეს შეძელით!') WHERE id = '1ce90c4b-f9a4-402a-a99b-4457322248d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ორმოცი დღის შესრულება“ ჩვენს საზოგადოებაში ერთგვარ ფინიშის ხაზად აღიქმება, თუმცა სინამდვილეში ეს მხოლოდ მარათონის დასაწყისია. ნუ დაემორჩილებით ზეწოლას, თითქოს „უკვე ყველაფერს უნდა ვუმკლავდებოდე“ ან „ჩემი სახლი იდეალურად სუფთა უნდა იყოს“. აღდგენის პროცესი ჯერ კიდევ გრძელდება; განსაკუთრებით თუ ძუძუთი კვებავთ, ჰორმონების (პროლაქტინის) გავლენით შეიძლება სახსრების მოდუნება ან წელის ტკივილი იგრძნოთ. ამ „ახალი თავისუფლების“ პერიოდში ერთბაშად ნუ გადაიტვირთებით — ცხოვრების ძველ ტემპს ნელ-ნელა, ნაბიჯ-ნაბიჯ დაუბრუნდით.') WHERE id = '0928cbd6-fa37-455a-a682-9515f253a752';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე უკეთ იწყებს ფერების გარჩევას; წითელი და ნარინჯისფერი შეიძლება პირველი მკვეთრი ფერები იყოს, რომლებიც მის ყურადღებას მიიპყრობს. საწოლის თავზე ჩამოკიდებული მბრუნავი სათამაშოს (მობილის) არა მხოლოდ მუსიკა, არამედ მოძრაობაც უკვე აინტერესებს. თუ ჯერ არ შეგიძენიათ, მარტივი გეომეტრიული ფიგურებისგან შემდგარი, ნელა მოძრავი მობილი ბავშვს ყურადღების კონცენტრაციის უნარის განვითარებაში დაეხმარება. თუმცა გაითვალისწინეთ: დაძინებისას ეს სათამაშოები მოაშორეთ, რათა ძილი არ დაუფრთხეს.') WHERE id = 'c21766cd-a78b-4676-9247-d0b2e0b3de2f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მშობიარობის შემდგომი სქესობრივი ცხოვრების თემა ხშირად ტაბუდადებულად ითვლება, თუმცა მნიშვნელოვანია, ამის შესახებ ინფორმირებული იყოთ. ექიმის ნებართვის შემდეგ (ჩვეულებრივ, 6 კვირის შემდეგ) სქესობრივი კავშირის დამყარება შესაძლებელია, თუმცა სურვილის არქონა (ლიბიდოს დაქვეითება) ან სიმშრალის შეგრძნება სრულიად ნორმალურია. ეს ძუძუთი კვებასთან დაკავშირებული ჰორმონებისა და დაღლილობის გავლენაა. ამის შესახებ პარტნიორს გულწრფელად ესაუბრეთ, ერთმანეთს დრო მიეცით და ნუ იჩქარებთ. სიახლოვე მხოლოდ სქესობრივ აქტს არ გულისხმობს — ამ პერიოდში უბრალოდ ჩახუტება და შეხებაც ძალიან მნიშვნელოვანია.') WHERE id = 'a59bf56c-999f-4547-b139-eaa70223118e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახლა ბავშვი საკუთარ ხელებს აღმოაჩენს; შესაძლოა, ისინი პირში ჩაიდოს ან თითები წოვოს. ეს არ ნიშნავს, რომ ის აუცილებლად "მშიერია" (თუმცა შეიძლება შიმშილის ნიშანიც იყოს) — ეს მისი თვითდამშვიდების მექანიზმი და სამყაროს შეცნობის საშუალებაა. ნუ ეცდებით, ხელები პირიდან გამოაღებინოთ ან ხელთათმანები ჩააცვათ. მიეცით საშუალება, საკუთარი სხეული აღმოაჩინოს. უბრალოდ დარწმუნდით, რომ ხელები სუფთა აქვს, ფრჩხილები კი — დაჭრილი.') WHERE id = '15366f98-572a-4b0c-8fda-af7cf85e56b4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე 2 თვის ასაკში ჩასატარებელი ვაქცინების დროა (თუ ჯერ არ ჩაგიტარებიათ). აზერბაიჯანში მოქმედი ვაქცინაციის კალენდრის მიხედვით, ამ პერიოდში ბავშვს ჩვეულებრივ უკეთებენ 5-კომპონენტიან ან 6-კომპონენტიან კომბინირებულ ვაქცინას (ყივანახველა, დიფტერია, ტეტანუსი და სხვ.) და პნევმოკოკურ ვაქცინას. ვაქცინაციის შემდეგ ბავშვს შეიძლება ტემპერატურამ ოდნავ აუწიოს ან მოუსვენრად იყოს; ეს საშიში არ არის — პირიქით, მიუთითებს, რომ იმუნიტეტი "ამოქმედდა" და ორგანიზმი თავდაცვას იწყებს. ექიმის რჩევით, სახლში აუცილებლად იქონიეთ ჩვილებისთვის განკუთვნილი პარაცეტამოლის შემცველი სანთელი ან სიროფი, თუმცა ნუ იჩქარებთ წამლის მიცემას, სანამ ტემპერატურა 38 გრადუსს არ გადააჭარბებს.') WHERE id = '947283f7-9c09-4c76-a0bb-7ff92f24aad4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს ნერწყვდენა დაეწყო და ხელებს ღეჭავს? ბებიებმა შეიძლება მაშინვე თქვან, რომ "კბილი ამოსდის", თუმცა 2 თვე, როგორც წესი, კბილების ამოსვლისთვის ადრეა (თუმცა გამონაკლისებიც არსებობს). ამ პერიოდში სანერწყვე ჯირკვლები აქტიურად იწყებს მუშაობას, მაგრამ ბავშვს ნერწყვის სრულად გადაყლაპვა ჯერ არ უსწავლია, ამიტომ ის პირიდან გადმოსდის. ამავდროულად, ნერწყვში არსებული ფერმენტები მის საჭმლის მომნელებელ სისტემას მომავალში მყარი საკვების მისაღებად ამზადებს. უბრალოდ ხშირად გამოუცვალეთ წინსაფარი, რათა კისერი ნესტიანი არ დარჩეს და გამონაყარი ან გამოყელვა არ გაუჩნდეს.') WHERE id = '99be53c6-0b63-4846-ac0b-fd476ca9e54e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ შხაპის მიღებისას თმა ბღუჯებად გცვივათ, ნუ შეგეშინდებათ — არ გამელოტდებით! ამას "მშობიარობის შემდგომი თმის ცვენა" ეწოდება და სრულიად ჰორმონალური პროცესია. ორსულობის დროს მომატებული ესტროგენი თმის ცვენას აფერხებდა, ახლა კი ამ ჰორმონის დონე იკლებს და თმა, რომელიც თავის დროზე არ ჩამოცვივდა, ერთდროულად იწყებს ცვენას. ეს დროებითია და დაახლოებით 6-12 თვის განმავლობაში მდგომარეობა გამოსწორდება. ძვირადღირებულ შამპუნებზე ფულის დახარჯვის ნაცვლად, ყურადღება მიაქციეთ კვებასა და რკინის დონეს — დროთა განმავლობაში ყველაფერი მოწესრიგდება.') WHERE id = 'f657e712-ddb7-463c-a1f6-51d68e963ec9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე იწყებს დღისა და ღამის ერთმანეთისგან გარჩევას, ამიტომ ახლა შესანიშნავი დროა "ძილის რიტუალის" შესაქმნელად. ეს მკაცრი რეჟიმი კი არა, უბრალოდ მოქმედებების თანმიმდევრობაა: თბილი აბაზანა -> პიჟამის ჩაცმა -> მკრთალი განათება -> იავნანა ან თეთრი ხმაური -> ძილი. ყოველდღე ერთი და იმავე თანმიმდევრობის გამეორება ბავშვის ტვინს უგზავნის სიგნალს: "უკვე ძილის დროა". შეიძლება ამ ჩვევამ დღესვე არ გამოიღოს შედეგი, მაგრამ რამდენიმე კვირაში ის თქვენი ნამდვილი მხსნელი გახდება.') WHERE id = '2614d60b-6450-43ee-a569-f20e3ea56045';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მხედველობის სამყარო სულ უფრო ფერადი ხდება; ახლა ის არა მხოლოდ წითელ და ნარინჯისფერ, არამედ მწვანე და ყვითელ ფერებსაც არჩევს. მისი განვითარების ხელშესაწყობად გაასეირნეთ სახლის სხვადასხვა ოთახში და სარკეში საკუთარი ანარეკლი აჩვენეთ (ბავშვებს ძალიან მოსწონთ თავიანთი ანარეკლის ყურება, თუმცა ჯერ ვერ ხვდებიან, რომ მასში საკუთარ თავს ხედავენ). ესაუბრეთ: „მოდი, ვნახოთ, აქ ვინ არის?“ ასეთი სოციალური თამაშები მის ტვინში ნეირონული კავშირების სწრაფ განვითარებას უწყობს ხელს.') WHERE id = '34645ca6-b752-434e-a340-59af7488ff61';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ზოგჯერ დედები ბავშვს ძუძუთი კვებავენ, მაგრამ წონაში არ იკლებენ — პირიქით, იმატებენ. ეს შესაძლოა უძილობისა და სტრესის გამო მომატებულ ჰორმონ კორტიზოლს უკავშირდებოდეს; ორგანიზმი თავს „საფრთხეში“ გრძნობს და ცხიმის მარაგს აგროვებს. რძის მოსამატებლად ტკბილი ჩაის, ჰალვისა და ცომეულის მიღება მითია; რძის გამომუშავებას ხელს უწყობს საკმარისი სითხის მიღება და ბავშვის ხშირი ძუძუთი კვება. შაქრის შემცირება და მეტი ბოსტნეულის მიღება ენერგიასაც შეგმატებთ და წონის თანდათან ნორმალიზებაშიც დაგეხმარებათ.') WHERE id = '70fa5f2d-ef18-4d50-b156-41acde57d635';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როდესაც ბავშვს მუცელზე აწვენთ (tummy time), უკვე ცდილობს არა მხოლოდ თავის, არამედ მკერდის იატაკიდან აწევასაც? ეს მისი „მინი-ვარჯიშია“! მისი ხელებისა და ზურგის კუნთები ძლიერდება. თუ ჯერ ვერ ახერხებს, დაეხმარეთ: პატარა პირსახოცი რულონივით დაახვიეთ და იღლიების ქვეშ ამოუდეთ — ის საყრდენად გამოადგება. წინ საყვარელი სათამაშო დაუდეთ, რათა მისწვდომას შეეცადოს. ეს მოძრაობები მომავალში ხოხვისა და ჯდომისთვის მნიშვნელოვანია.') WHERE id = '8cfe7b98-ab62-49f4-b9ea-ef363b224769';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ პერიოდში ბავშვებს „არასაკვები წოვის“ რეფლექსი ძლიერად აქვთ გამოხატული; ანუ მას არ შია, უბრალოდ დასამშვიდებლად რაიმეს წოვა სურს. თუ თითებს წოვს და თქვენ საწოვარას მიცემა გსურთ, ეცადეთ, „ორთოდონტიული“ ფორმის საწოვარა შეარჩიოთ. საწოვარა ცუდი ჩვევა არ არის და ჩვილთა უეცარი სიკვდილის სინდრომის (SIDS) რისკის შემცირების დამხმარე საშუალებად მიიჩნევა. თუმცა ყოველი ტირილის დროს საწოვარას „გასაჩუმებლად“ ნუ გამოიყენებთ — ჯერ ეცადეთ, გაარკვიოთ, რა აწუხებს.') WHERE id = '4ec5ed37-79da-4c46-9571-b8e74147be8d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შეამჩნიეთ, რომ ბავშვის თავის ერთი მხარე გაბრტყელებულია? ამას „პოზიციური პლაგიოცეფალია“ ეწოდება და ბავშვის მუდმივად ერთსა და იმავე მხარეს წოლის გამო ვითარდება. თავის ქალის ძვლები ჯერ კიდევ რბილია და მდგომარეობის გამოსწორება ადვილად შეიძლება. მარტივი გამოსავალი: საწოლში ჩაწვენისას ყოველ ღამე შეუცვალეთ თავის მიმართულება (ერთ დღეს მარჯვნივ, მეორე დღეს მარცხნივ). ხოლო როცა ღვიძავს, რაც შეიძლება ხშირად დააწვინეთ მუცელზე, რათა კეფაზე ზეწოლა შემცირდეს.') WHERE id = '248e6415-444f-4d09-8609-b540277d00d1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! დღეს თქვენი ბავშვი 2 თვის გახდა! „ახალშობილობის“ (newborn) პერიოდი უკვე ოფიციალურად უკან მოიტოვეთ და ახლა ის „ჩვილად“ (infant) ითვლება. შეადარეთ პირველ დღეებში მყოფი ის პატარა, უმწეო არსება დღევანდელ ბავშვს, რომელიც გიღიმით და სხვადასხვა ხმას გამოსცემს. რთული დღეები ჯერ კიდევ იქნება — წინ არის კბილების ამოჭრა, ძილის რეგრესია და სხვა გამოწვევები, მაგრამ თქვენ უკვე გამოცდილი დედა ხართ და ნებისმიერ სირთულეს გაუმკლავდებით. გულში ჩაიკარით საკუთარი თავი — შესანიშნავად ართმევთ თავს!') WHERE id = 'd3b345c6-e91a-402d-9918-ceed5b8d37b4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბალიში ან ტანსაცმელი ხშირად უსველდება? მე-3 თვეში ნერწყვის გამოყოფის მატება სრულიად ნორმალურია. ეს აუცილებლად კბილების ამოჭრას არ ნიშნავს (თუმცა ღრძილები შეიძლება ექავებოდეს). ეს მიუთითებს, რომ საჭმლის მომნელებელი სისტემა ვითარდება და პირის ღრუში არსებული ბაქტერიების წინააღმდეგ ბუნებრივი დაცვა ყალიბდება. უბრალოდ კისერზე ნერწყვის შესაწოვი წინსაფარი გამოიყენეთ და პირის ირგვლივ კანი მშრალად შეინარჩუნეთ, რათა გამონაყარი არ გაუჩნდეს.') WHERE id = '65b4b1d4-9f03-4890-8a26-60e163757dc4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კითხვა — „საჭიროა თუ არა წყლის მიცემა?“ — ამ თვეებში ბევრ დედას აფიქრებს. განსაკუთრებით ბებიებმა შეიძლება თქვან: „ცოდოა, სწყურია“. თუმცა ჯანმო გვირჩევს, პირველი 6 თვის განმავლობაში ბავშვს დედის რძის ან ხელოვნური საკვების გარდა არაფერი (წყალიც კი) არ მივცეთ. დედის რძის 88% წყალია და ის ბავშვის სითხის საჭიროებას სრულად აკმაყოფილებს. მისი კუჭი ჯერ ძალიან პატარაა; წყლით შევსებამ შეიძლება რძის მიღება შეამციროს და ზრდა-განვითარებას შეუშალოს ხელი.') WHERE id = 'daa57941-307c-46d4-ad44-8c2b7828cf2e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ყოველდღიურ ცხოვრებას „პაუზის“ ღილაკი დაუმატეთ. როცა ბავშვს სძინავს, მაშინვე სახლის დალაგებას ნუ შეუდგებით. თქვენს „ბატარეასაც“ სჭირდება დამუხტვა. 20-წუთიანი ძილი, წიგნის კითხვა ან უბრალოდ ჭერისთვის უმიზნოდ ყურება თქვენი უფლებაა. არ ხართ ვალდებული, „იდეალური დიასახლისი“ იყოთ, მაგრამ მნიშვნელოვანია, „ჯანმრთელი დედა“ იყოთ. მტვერი მოიცდის, თქვენი ფსიქოლოგიური ჯანმრთელობა კი — არა.') WHERE id = '8ae3c3ee-3ed1-4cce-8f50-41530ca784cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ თვიდან შეგიძლიათ დაიწყოთ ციკლის — „კვება - აქტივობა - ძილი“ — ჩამოყალიბება. ანუ: ბავშვი იღვიძებს -> რძეს ჭამს -> თამაშობს -> იძინებს. დედები ხშირად ბავშვს ძუძუთი კვებისას აძინებენ (ეს არ არის არასწორი, თუმცა შეიძლება ჩვევად ჩამოუყალიბდეს). თუ თანმიმდევრობას „ჭამა-თამაში-ძილი“ დაიცავთ, ბავშვი კვებას ნაკლებად დაუკავშირებს ძილს და მომავალში დამოუკიდებლად ჩაძინება გაუადვილდება. რა თქმა უნდა, ეს მკაცრი წესი არ არის — უბრალოდ მეთოდია, რომლის გამოცდაც ღირს.') WHERE id = '2c9372ab-3791-4b09-9ac2-4545b2a50eba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ხელები უკვე „თავისით“ აღარ მოძრაობს — ის შეგნებულად ცდილობს საგნებისკენ ხელის გაწვდენასა და მათ დაჭერას. თუ ადრე, როცა თითს ხელისგულში უდებდით, რეფლექსურად გიჭერდათ, ახლა სათამაშოს ხედავს და მისკენ ხელს იწვდის. განვითარების ეს ეტაპი შესანიშნავია, თუმცა ყურადღებით იყავით: როცა ხელში გიჭირავთ, შეიძლება თმის, ყელსაბამის ან სათვალის მოქაჩვა მოინდომოს. ასევე, ცხელი ჩაის ფინჯნები მისგან შორს შეინახეთ, რადგან უეცარი მოძრაობით შეიძლება ჩაი საკუთარ თავზე გადაიღვაროს. უსაფრთხო მანძილის დაცვა უკვე აუცილებელია.') WHERE id = '851b7601-c8f0-43b8-a2e5-3708104c42ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ღამით უძილობა ჯერ კიდევ გრძელდება, შეგიძლიათ „ძილში კვების“ (Dream Feed) მეთოდი სცადოთ. ამ დროს ბავშვს სრულად გაღვიძების გარეშე, ნახევრად მძინარეს აჭმევთ (მაგალითად, თქვენს დაძინებამდე, 23:00 საათზე) და შემდეგ ისევ თავის საწოლში აწვენთ. ზოგჯერ ეს მეთოდი ბავშვს შუაღამისას გაღვიძებისგან იცავს და თქვენც შედარებით ხანგრძლივი, უწყვეტი ძილის საშუალებას გაძლევთ. თუ მეთოდი არ ამართლებს და ბავშვი იღვიძებს და ტირის, ნუ დააძალებთ; ყველა ბავშვის ბიორიტმი განსხვავებულია.') WHERE id = '1a681284-0141-4b15-bc3b-3b5a269a1b94';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-3 თვეში! ბავშვის განვითარების „მეოთხე ტრიმესტრად“ წოდებული პირველი 3-თვიანი ადაპტაციის პერიოდი დასასრულს უახლოვდება. თქვენი ბავშვი უკვე აღარ არის არსება, რომელსაც მხოლოდ ჭამა და ძილი სურს — ის გარემოს აღიქვამს, ხმებზე რეაგირებს და სოციალურ ინდივიდად ყალიბდება. ამ თვიდან მისი სიფხიზლის პერიოდები გახანგრძლივდება, ძილი კი (იმედია!) ცოტათი უფრო მოწესრიგებული გახდება. ამ ახალ ეტაპზე მას თქვენთან უფრო მეტი „საუბარი“ მოუნდება, ამიტომ მოემზადეთ, რომ ხშირად ელაპარაკოთ და უმღეროთ.') WHERE id = '8828f855-f7c6-48a8-aae1-636ec24ccff1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი ხელებს სახის წინ იჭერს და გაოცებული უყურებს? ეს ნიშნავს, რომ მან თავისი პირველი „სათამაშო“ აღმოაჩინა! ამას „თვალისა და ხელის კოორდინაცია“ ეწოდება. ბავშვი ხვდება, რომ ხელები მას ეკუთვნის და მათი მართვა შეუძლია. ხელს ნუ შეუშლით ამ პროცესს და ხელებს ნუ დაუმალავთ. პირიქით, შეგიძლიათ მაჯებზე ფერადი ან ხმის გამომცემი (ზარიანი) სამაჯურები გაუკეთოთ და ეს აღმოჩენა კიდევ უფრო საინტერესო გახადოთ. ეს მისი ტვინის განვითარებისთვის შესანიშნავი ვარჯიშია.') WHERE id = 'c44f54e6-bd35-4121-9f0f-f6748ef02647';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მიუხედავად იმისა, რომ ძილის საკითხი ჯერ კიდევ მტკივნეულია, კარგი ამბავიც გვაქვს: ბავშვის ტვინმა უკვე დაიწყო „მელატონინის“ (ძილის ჰორმონის) გამომუშავება და ცირკადული რიტმი (ბიოლოგიური საათი) ყალიბდება. ახლა ნაკლებად სავარაუდოა, რომ მას დღე და ღამე აერიოს. მის დასახმარებლად დილით ოთახი მზის შუქით გაავსეთ, საღამოს კი განათება ადრიანად ჩააქრეთ და მშვიდი გარემო შექმენით. ბუნებრივი განათების ასეთი რეჟიმი მის ტვინს გადასცემს სიგნალებს: „ახლა გაღვიძების დროა“ და „ახლა ძილის დროა“.') WHERE id = 'f3bdc990-29cc-452b-b018-a1508cec7d80';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კისრის კუნთები უკვე მნიშვნელოვნად გაუძლიერდა და მუცელზე წოლისას ბავშვს შეუძლია თავი 45-90 გრადუსით ასწიოს და გარშემო მიმოიხედოს. ზოგჯერ შეიძლება „თვითმფრინავივით“ ხელ-ფეხიც ჰაერში ასწიოს და ირწეოდეს. ეს მის ზურგის კუნთებს მომავალში ხოხვისა და ჯდომის ეტაპებისთვის ამზადებს. თუ თავს ჯერ კიდევ ბოლომდე ვერ იჭერს, ნუ ინერვიულებთ — ყველა ბავშვს განვითარების საკუთარი ტემპი აქვს; უბრალოდ ყოველდღიურ რეჟიმში მუცელზე წოლისთვის განკუთვნილი დრო (tummy time) აუცილებლად შეინარჩუნეთ.') WHERE id = '72ecbac3-10ef-45d2-898d-f50326e4aca5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის თავზე, განსაკუთრებით ყიფლიბანდის მიდამოში, მოყვითალო, ცხიმიანი ქერქები (ქერტლი) შენიშნეთ? ხალხში მას „რძის ქერქს“, მედიცინაში კი „სებორეულ დერმატიტს“ უწოდებენ. ნუ შეგეშინდებათ — ეს არასათანადო ჰიგიენის შედეგი არ არის და არც გადამდებია. ის დედისგან გადაცემული ჰორმონების ზემოქმედებით ცხიმოვანი ჯირკვლების ჭარბი აქტივობის გამო ჩნდება. ნუ ეცდებით ქერქების აძრობას — დაბანამდე უბრალოდ წაუსვით ზეითუნის ან ნუშის ზეთი და დაარბილეთ, შემდეგ კი რბილი ჯაგრისით ფრთხილად დავარცხნეთ და დაბანეთ. დროთა განმავლობაში თავისით გაივლის.') WHERE id = 'ebf4f9a7-c423-4f9b-a35f-e6aea203cbf5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ღიმილი უკვე რეფლექსური კი არა, სრულიად გააზრებულია! როცა უღიმით, უღიტინებთ ან „ჭიტას“ (დამალობანას) ეთამაშებით, შეიძლება ხმამაღლა სიცილი დაიწყოს. ეს ხმა მსოფლიოში ყველაზე ლამაზი მუსიკაა, ასე არ არის? მას იუმორის გრძნობა უყალიბდება. უცნაური ხმების გამოცემა და სხვადასხვა სასაცილო გამომეტყველების მიღება ძალიან გაახალისებს. სიცილი ასევე ხელს უწყობს მისი ფილტვების განვითარებას და ამცირებს სტრესის ჰორმონების დონეს.') WHERE id = '1fddfb5f-0320-4827-b223-17100c2c0495';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როდესაც ბავშვს მუცელზე აწვენთ (tummy time), შეიძლება შეამჩნიოთ, რომ ის გვერდზე გადაბრუნებას ცდილობს. ზოგიერთმა მოქნილმა ბავშვმა ამ პერიოდში შეიძლება მუცლიდან ზურგზე გადაბრუნებაც მოახერხოს (შემთხვევით, თავის სიმძიმის გამო). ეს დიდი სიხარულია, თუმცა ამავდროულად გამაფრთხილებელი ნიშანიცაა: ამიერიდან ბავშვი გამოსაცვლელ მაგიდაზე, დივანზე ან სხვა შემაღლებულ ადგილას ერთი წამითაც კი არ უნდა დატოვოთ უყურადღებოდ. ამ თვიდან დაცემის რისკი მკვეთრად იზრდება, ამიტომ ყველაზე უსაფრთხო ადგილი იატაკია (ხალიჩა ან სათამაშო ხალიჩა).') WHERE id = '51999bec-e90a-4151-af89-e280275c886e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მიერ გამოცემული ხმები უკვე მხოლოდ ტირილით აღარ შემოიფარგლება — მას შეუძლია ხმოვნები ("ა", "ო", "უ") გაახანგრძლივოს ან ღუღუნის მსგავსი ხმები გამოსცეს. ასე ის ხმის იოგებს ავარჯიშებს. თუ თქვენ სამზარეულოში საქმიანობთ და ბავშვი ოთახიდან ხმებს გამოსცემს, აუცილებლად უპასუხეთ ხმით ("დიახ, მესმის შენი, მოვდივარ"). ასეთი "შორიდან ურთიერთობა" მას უსაფრთხოების განცდას უქმნის: "დედას რომ ვერ ვხედავდე, მისი ხმა მესმის, ესე იგი მარტო არ ვარ". ეს განშორების შფოთვის (separation anxiety) შემცირებას უწყობს ხელს.') WHERE id = '4b396ede-815b-4edd-bee5-1ab95bd630c3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის წონის მატებასთან ერთად შეიძლება ზურგისა და ხელების ტკივილი გაგიჩნდეთ (განსაკუთრებით, ე.წ. "დედის მაჯის" სინდრომი). როდესაც ბავშვს ხელში იყვანთ ან ძუძუთი კვებავთ, ყურადღება მიაქციეთ თქვენს პოზას: მხრები ყურებისკენ არ ასწიოთ, გამართულად იჯექით და აუცილებლად გამოიყენეთ ზურგის დამჭერი ბალიშები. ბავშვის იატაკიდან აყვანისას წელი კი არ მოხაროთ, არამედ მუხლები მოკეცეთ. თქვენი ხერხემალი კიდევ მრავალი წელი დაგჭირდებათ, ამიტომ მასზე ზრუნვა ახლავე დაიწყეთ.') WHERE id = 'dc8afbc6-14c7-4301-94dd-c5e5a4b2292b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გარშემო მყოფებისგან შეიძლება მოისმინოთ ზეწოლა, მაგალითად: "ბავშვი უკვე 3 თვისაა, ბულიონის გემო გაასინჯე" ან "ცოტა პურის გული მიეცი, მიეჩვიოს". მტკიცედ იდექით თქვენს გადაწყვეტილებაზე და თქვით "არა". ჯანმრთელობის მსოფლიო ორგანიზაცია (ჯანმო) ცალსახად აცხადებს: პირველი 6 თვის განმავლობაში — მხოლოდ დედის რძე (ან ხელოვნური ნარევი). ბავშვის კუჭ-ნაწლავის სისტემა ჯერ არ არის მზად სახამებლისა და სხვა საკვების მოსანელებლად; დამატებითი კვების ნაადრევად დაწყებამ შეიძლება ალერგია, შებერილობა და მომავალში სიმსუქნე გამოიწვიოს. ნუ იჩქარებთ — საკვების მისაღებად მას მთელი ცხოვრება ექნება.') WHERE id = '0739a3ba-203e-453e-b9ac-6bd4bfdbcdf4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ პერიოდის ყველაზე საინტერესო სათამაშო სარკეა! ბავშვის წინ უსაფრთხო (მსხვრევადი არა) სარკე მოათავსეთ. ის სარკეში დანახულ "სხვა ბავშვს" გაუღიმებს, შეეცდება შეეხოს და გაოცდება. ჯერ ვერ ხვდება, რომ ეს თავადაა (ამას დაახლოებით 18 თვის ასაკში აცნობიერებს), თუმცა სახის გამომეტყველებებსა და მოძრაობებზე დაკვირვება მისი სოციალური განვითარებისთვის შესანიშნავია. ეს თამაში ასევე კარგი ხერხია მუცელზე წოლის დროის გასახანგრძლივებლად.') WHERE id = 'd5f46289-84de-4aa8-8cc6-e208423016ca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გარესამყაროსადმი ბავშვის ინტერესის ზრდასთან ერთად ძუძუთი კვება შეიძლება გართულდეს. მას სურს, ყველა ხმასა და მოძრაობაზე თავი მიაბრუნოს და გაიხედოს, რის გამოც ძუძუს უშვებს. ამას "ცნობისმოყვარე ბავშვის სინდრომს" უწოდებენ. ნუ გაღიზიანდებით — უბრალოდ ძუძუთი კვებისთვის უფრო მშვიდი, ჩაბნელებული და ნაკლებად საინტერესო ოთახი შეარჩიეთ. მოიხსენით მკვეთრი ყელსაბამი და სხვა თვალშისაცემი ნივთები. შეამჩნევთ, რომ ღამით ან ძილიან მდგომარეობაში ბავშვი უკეთ წოვს — ეს ნორმალურია.') WHERE id = '9cc144a8-c429-4c7c-b711-108cf929ab92';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მიერ საკუთარი ხელების აღმოჩენა ზოგჯერ იმით სრულდება, რომ ის ფრჩხილებით სახეს იკაწრავს. თუ ფრჩხილების დაჭრის გეშინიათ, ეს ძილის დროს გააკეთეთ ან დაბანის შემდეგ, როცა ფრჩხილები ოდნავ დარბილდება. ხელთათმანების ჩაცმა აღარ არის რეკომენდებული, რადგან ბავშვი სამყაროს ხელებით შეხებისა და მათი პირთან მიტანის გზით შეიცნობს. პატარა ნაკაწრი მალე შეხორცდება, ხელებით შეგრძნების შეზღუდვამ კი შეიძლება მისი განვითარება შეაფერხოს.') WHERE id = '4516cd0b-d8f9-4d0b-92cb-3f43fabc6642';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, პირველი 3-თვიანი ადაპტაციის პერიოდი, რომელსაც „მეოთხე ტრიმესტრს“ უწოდებენ, თითქმის დასრულდა! თქვენი ბავშვი უკვე სრულად შეეგუა „გარე სამყაროს“. როცა ღვიძავს, მხოლოდ საწოლში ნუ დატოვებთ — მოატარეთ სახლში, ერთად გაიხედეთ ფანჯრიდან და სხვადასხვა ოთახში შეიყვანეთ. ის უკვე დამკვირვებელია. რაც უფრო მეტ ვიზუალურ და ხმოვან კონტაქტს დაამყარებთ მასთან ამ პერიოდში, მით უფრო გაძლიერდება მის ტვინში ნეირონული კავშირები. თქვენ მისი პირველი და საუკეთესო მასწავლებელი ხართ.') WHERE id = 'ef4c7b42-edd4-4ffb-87e6-5505b04254f6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამჩნევთ, რომ ბავშვს ღამით უკვე უფრო დიდხანს სძინავს (მაგალითად, 4-5 საათი უწყვეტად)? ეს იმაზე მიუთითებს, რომ მისი კუჭი გაიზარდა და მას შეუძლია მთელი ღამის განმავლობაში დანაყრებული დარჩეს. თუმცა სიხარულს ნუ იჩქარებთ — ეს შეიძლება „თაფლობის თვის“ პერიოდი იყოს. ზოგ ბავშვს დაახლოებით 3-4 თვის ასაკში „ძილის რეგრესია“ (sleep regression) ეწყება. თუ ძილი აერევა, ნუ შეშფოთდებით — ეს ნიშნავს, რომ მისი ტვინის განვითარება ახალ ეტაპზე გადადის. უბრალოდ ერთგულად დაიცავით თქვენ მიერ შექმნილი ძილის რიტუალი — სტაბილურობა მისთვის ყველაზე მნიშვნელოვანია.') WHERE id = '7478fbcd-b780-4677-b9cd-7d27602a29cc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახლა ბავშვს ხელები მუშტად აღარ აქვს შეკრული და უმეტესად გახსნილი აქვს. ეს მიუთითებს, რომ მისი კუნთების მომატებული ტონუსი (ჰიპერტონუსი) შემცირდა და ნორმას დაუბრუნდა. მას უკვე შეუძლია ხელების ერთმანეთთან მიტანა და თითებით თამაში. შეხების შეგრძნების განვითარებაში შეგიძლიათ დაეხმაროთ, თუ სხვადასხვა ფაქტურის მქონე ქსოვილებს ან სათამაშოებს მისცემთ — რბილს, ხორკლიანს ან შრიალას. ტვინის განვითარება თითის წვერებიდან იწყება: რაც უფრო მეტ განსხვავებულ ზედაპირს შეეხება, მით მეტ ინფორმაციას დაამუშავებს მისი ტვინი.') WHERE id = 'd9c1219d-f2eb-4189-a9f5-e0d58b033ef7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ისეთი შედარებები, როგორიცაა: „მეზობლის ბავშვი უკვე ტრიალდება, ჩემი კი რატომ არ მოძრაობს?“, დედების ყველაზე დიდი მტერია. გახსოვდეთ, ყველა ბავშვი უნიკალური ინდივიდია, განვითარების გრაფიკი კი მათემატიკური ფორმულა არ არის — ის მხოლოდ სავარაუდო დროის შუალედია. ერთი ბავშვი 3 თვის ასაკში გადაბრუნდება, მეორე კი 5 თვისას; ეს არ ნიშნავს, რომ მეორე „ჩამორჩება“. შედარება სტრესს გიქმნით, ბავშვი კი თქვენს დაძაბულობას გრძნობს. პატივი ეცით მისი განვითარების ინდივიდუალურ ტემპს და უბრალოდ აღნიშნეთ მისი პატარა გამარჯვებები (მაგალითად, ის, რომ თავს უფრო სწორად იჭერს).') WHERE id = '3aa7065c-48aa-4e3c-a0fe-877781389808';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შეამოწმეთ თქვენი სხეული: მუცლის შუაში, ჭიპის ხაზის გასწვრივ, სიცარიელეს ან ჩაღრმავებას გრძნობთ? ეს შეიძლება „დიასტაზი“ (მუცლის კუნთების დაშორება) იყოს. თუ ორსულობის დროს გაფართოებული კუნთები ჯერ არ შეერთებულა, „პრესის“ კლასიკური ვარჯიშების (წამოჯდომების) შესრულება კატეგორიულად აკრძალულია — ამან შეიძლება მდგომარეობა კიდევ უფრო გააუარესოს. თავდაპირველად მარტივი სუნთქვითი ვარჯიშებით ან ვაკუუმით (ექიმის ნებართვით) ღრმა კუნთები უნდა გაიმაგროთ. ვარჯიშის დაწყებამდე მნიშვნელოვანია, შეამოწმოთ, გაქვთ თუ არა დიასტაზი.') WHERE id = '2926fb2b-5ad3-4daf-b451-2b21927c114c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვთან ერთად „წიგნის კითხვა“ არასდროს არის ნაადრევი! მიუხედავად იმისა, რომ მას სიტყვები ჯერ არ ესმის, თქვენი ხმის ტონის, ინტონაციისა და რიტმის მოსმენა მოსწონს. შეარჩიეთ წიგნები სქელი ფურცლებით, ბევრი სურათითა და მცირე ტექსტით. აჩვენეთ სურათები და უთხარით: „შეხედე, ეს კატაა, კნავის“. ეს ჩვევა ხელს უწყობს მისი მეტყველების განვითარებას და მომავალში წიგნებისადმი ინტერესს უღვივებს. გარდა ამისა, თქვენს კალთაში წიგნის კითხვა შეიძლება ძილის წინ დამამშვიდებელ რიტუალად იქცეს.') WHERE id = '7f0b6be9-2911-4a47-a448-53c0a1e9d9fe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მუცელზე წოლისას (tummy time) ბავშვს უკვე უნდა შეეძლოს ხელების წინ გაწევა და მკერდის იატაკიდან საგრძნობლად აწევა. ეს „კობრას პოზა“ მიანიშნებს, რომ მისი ზურგისა და კისრის კუნთები ძლიერდება. თუ მას ჯერ კიდევ არ მოსწონს მუცელზე წოლა და ტირის, გულს ნუ გაიტეხთ. განაგრძეთ ყოველდღიურად 5-10-წუთიანი მოკლე სესიები. ალტერნატივის სახით, დაწექით და ბავშვი თქვენს მკერდზე მოათავსეთ — თქვენი სახის დასანახად თავის აწევის მეტი სურვილი ექნება.') WHERE id = 'd283274d-2a11-4684-91a8-ce7b016b2812';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეძუძურ დედებს შორის ძალიან გავრცელებულია მოსაზრებები, როგორიცაა „ბოტოქსი არ შეიძლება“ და „თმის შეღებვა არ შეიძლება“. თუმცა თანამედროვე კვლევები აჩვენებს, რომ თმის საღებავი და ადგილობრივი ესთეტიკური პროცედურების უმეტესობა დედის რძეში არ გადადის და ბავშვისთვის უსაფრთხოა (რა თქმა უნდა, უამიაკო საღებავებისა და სანდო სპეციალისტების შერჩევის შემთხვევაში). საკუთარ თავზე ზრუნვისა და ლამაზად გამოჩენის სურვილი დედობრივ მოვალეობებს არ ეწინააღმდეგება. ბედნიერ და თავდაჯერებულ დედას შეუძლია შვილს მეტი სიყვარული მისცეს.') WHERE id = '989b1bed-bb91-418f-ba9c-66f04eee3377';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ღიმილი ღუტუნის საპასუხოდ უკვე შეიძლება ხმამაღალ სიცილად გადაიქცეს. ნაზად მოუღუტუნეთ იღლიებში, კისერზე ან ტერფებზე და დააკვირდით მის რეაქციას. ეს მარტივი თამაში ეხმარება ბავშვს საკუთარი სხეულის შეცნობასა და მგრძნობელობის განვითარებაში. სიცილი ზრდის მისი ფილტვების ტევადობას და აუმჯობესებს სისხლის მიმოქცევას. სახლში დაძაბულობის შესამცირებლად საუკეთესო წამალი ბავშვის კისკისია.') WHERE id = '9800dfd4-1a12-46cd-be37-2d51f66e1ad7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის დღის ძილი შემცირდა, მაგრამ უფრო ხშირად იძინებს? 3 თვის ბავშვებს, ჩვეულებრივ, დღის განმავლობაში 3-4-ჯერ სძინავთ (ჯამში 4-5 საათი). თუ დაძინება არ სურს და გადაღლილობისგან ტირის, ნუ მოგერიდებათ მისი ხელში აყვანით, რწევით ან ეტლით გასეირნებით დაძინება. შიშით, რომ „მიეჩვევა“, ბავშვის უძილოდ დატოვება უფრო საზიანოა. გამოუძინებელი ბავშვის ორგანიზმი გამოყოფს სტრესის ჰორმონს (კორტიზოლს), რაც მის განვითარებაზე უარყოფითად მოქმედებს. მთავარი მიზანია, რომ დაიძინოს; როგორ დაიძინებს, ჯერჯერობით მეორეხარისხოვანია.') WHERE id = '1a9dccd0-8134-416f-bb91-5bdf13fc777c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! დღეს თქვენი ბავშვი 3 თვის გახდა! ეს მნიშვნელოვანი ეტაპია. „მეოთხე ტრიმესტრი“ უკვე სრულად დასრულდა. თქვენი ბავშვი თავს სწორად იჭერს, ხელებს ერთმანეთს აერთებს, გიღიმით და შესაძლოა, გვერდზე გადაბრუნებასაც ცდილობს. ის უკვე პატარა პიროვნებაა. დღეს მისი განვითარების შესაფასებლად შეგიძლიათ პედიატრთან ვიზიტი დაგეგმოთ. მაგრამ, რაც მთავარია, საკუთარ თავსაც მიულოცეთ. უკვე 90 დღეა, შესვენების გარეშე, დღე და ღამე შრომობთ — თქვენ გმირი ხართ. არ დაგავიწყდეთ, დღეს საკუთარ თავს პატარა საჩუქარი გაუკეთოთ!') WHERE id = 'c4888a4d-c53f-4c06-9f8b-73bef82c950b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს ხელში მოხვედრილი ყველაფერი პირში მიაქვს? ეს „ორალური პერიოდის“ გააქტიურებაა. ის სამყაროს პირით, „გემოს გასინჯვით“ შეიცნობს. ეს აუცილებლად კბილების ამოჭრას არ ნიშნავს (თუმცა შესაძლოა ღრძილების ქავილიც ჰქონდეს). მიეცით სხვადასხვა ტექსტურის კბილების ამოსაჭრელი სათამაშოები. თუმცა ყველაზე მნიშვნელოვანი უსაფრთხოებაა: იატაკსა და მაგიდაზე ნუ დატოვებთ პატარა ნივთებს (ღილებს, მონეტებს, მძივებს). ამ თვეებში დახრჩობის რისკი იზრდება, რადგან ბავშვის ხელების მოქნილობა უმჯობესდება. სახლი „ბავშვის თვალით“ შეამოწმეთ.') WHERE id = '3d44726d-b011-4c60-a3ce-d4d40cf54d8f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამჩნევთ, რომ საღამოს საათებში ბავშვი რძეზე უარს ამბობს, ძუძუს ებრძვის ან ტირილით წოვს? ამას „ძუძუზე ცრუ უარს“ უწოდებენ. ამის მიზეზი რძის ნაკლებობა კი არა, ბავშვის დაღლილობა ან ზედმეტი სტიმულაციაა. მის დასამშვიდებლად ჩართეთ „თეთრი ხმაური“ (white noise), დააბნელეთ ოთახი ან სიარულისას აწოვეთ ძუძუ. თუ კვლავ უარს იტყვის, ნუ დააძალებთ — შეისვენეთ 15-20 წუთით, დაამშვიდეთ და ხელახლა სცადეთ.') WHERE id = '01937078-adcb-4cc4-9337-fd91b288734f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ბავშვის დღის ძილი შემცირდა (30-45 წუთამდე), ეს ნორმალურია. მე-4 თვეში ძილის ციკლები იცვლება და ბავშვს ერთი ციკლიდან მეორეზე გადასვლისას (მსუბუქად გამოღვიძების დროს) კვლავ ჩაძინება უჭირს. დასახმარებლად, გაღვიძებისთანავე ნუ აანთებთ შუქს; მის გვერდით დაწექით, ჩუმად დაამშვიდეთ ან ხელი მკერდზე დაადეთ და მსუბუქად დააწექით. „ძილის გახანგრძლივების“ ეს ტექნიკა (resettling) დროთა განმავლობაში დაეხმარება, ძილის ციკლები ერთმანეთთან დააკავშიროს.') WHERE id = '42ae96e6-578f-4958-b69b-9e931b862da2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! თქვენ და თქვენმა ბავშვმა ერთად უკვე 100 დღე გაიარეთ! ზოგიერთ აზიურ კულტურაში ამ დღეს განსაკუთრებულად აღნიშნავენ, რადგან მიიჩნევა, რომ ბავშვმა ყველაზე მგრძნობიარე პერიოდი გადალახა. უკან გაიხედეთ: ის პატარა, უმწეო ბავშვი ახლა უკვე პიროვნებაა, რომელიც გიღიმით, გცნობთ და ხელებით თამაშობს. თქვენც შეიცვალეთ, გაიზარდეთ და გაძლიერდით. დღეს ფინჯანი ყავა დაისხით, გალერეაში პირველი დღის ფოტოები დაათვალიერეთ და თქვით: „მე ეს შევძელი!“ თქვენ შესანიშნავი ხართ!') WHERE id = '000749db-379b-4eae-a0cc-18c3f43ee041';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვმა ღამით ხშირად გაღვიძება დაიწყო? კეთილი იყოს თქვენი მობრძანება „მე-4 თვის ძილის რეგრესში“! სინამდვილეში, ეს რეგრესი კი არა, ბავშვის ტვინის განვითარების უზარმაზარი ნახტომია. მისი ძილის ციკლები იცვლება და, ზრდასრულების მსგავსად, „ზედაპირული“ და „ღრმა“ ძილის ფაზებად იყოფა. ერთი ფაზიდან მეორეზე გადასვლისას (ყოველ 45-60 წუთში) ბავშვი ოდნავ იღვიძებს და ტირის, რადგან დამოუკიდებლად კვლავ ჩაძინება ჯერ არ შეუძლია. ეს დროებითი პერიოდია (შესაძლოა 2-6 კვირა გაგრძელდეს). მოთმინება გამოიჩინეთ, ძველი ჩვევები (რწევა, ძუძუთი კვება) უეცრად არ შეცვალოთ — უბრალოდ აგრძნობინეთ, რომ მის გვერდით ხართ.') WHERE id = '70ef5cd6-e529-4523-a7e3-dac3c50ee881';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როდესაც ბავშვს მუცელზე აწვენთ (tummy time), ამჩნევთ, რომ უკვე მხოლოდ თავს კი არა, მკერდსაც სწევს იატაკიდან და ხელების წინ გაწევით „ცურვას“ ცდილობს? ეს მისი ზურგის კუნთების გაძლიერებაზე მიუთითებს. ზოგიერთ ბავშვს ამ პერიოდში შეუძლია მუცლიდან ზურგზე გადაბრუნება (შემთხვევით, თავის სიმძიმის გამო). ეს დიდი სიხარულია, თუმცა ამავდროულად საფრთხის სიგნალიც: დივანსა თუ საწოლზე მისი მარტო დატოვება ამიერიდან კატეგორიულად დაუშვებელია! ამ თვიდან დაცემის რისკი მკვეთრად იზრდება.') WHERE id = '71d4a5bb-ec66-43a8-8e47-cf600b05a37e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გაწუხებთ, რომ ძუძუთი კვების დროს ბავშვს ყურადღება ეფანტება? ის ერთ-ორ ყლუპს სვამს, შემდეგ თავს აბრუნებს და ოთახში ხმას ან სინათლეს აკვირდება. ამას „ცნობისმოყვარე ბავშვის სინდრომს“ უწოდებენ. მას გარემოს შესწავლა სურს, ჭამა კი მისთვის „მოსაწყენად“ გამოიყურება. გამოსავალი: კვების დროს ოთახში მაქსიმალურად მშვიდი გარემო და სუსტი განათება შექმენით და ყურადღების გამფანტავი ნივთები (ტელეფონი, ტელევიზორი, კაშკაშა სათამაშოები) მოაშორეთ. შეამჩნევთ, რომ ღამით ან ძილიან მდგომარეობაში ბავშვი ძუძუს უკეთ წოვს.') WHERE id = 'bce582cc-6b95-467c-98a1-35d2509fd4d5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს ისევ მოსდის ნერწყვი და ყველაფერს, რასაც ხელში მოიგდებს (სათამაშოს, საბანს, თქვენს თითს), ენერგიულად ღეჭავს? ეს ღრძილების ქავილია. მიუხედავად იმისა, რომ კბილი ჯერ არ ჩანს, ის ღრძილის ქვეშ მოძრაობს და ბავშვს დისკომფორტს უქმნის. შეგიძლიათ მისცეთ გაგრილებული (არა გაყინული!) კბილების ამოსაჭრელი სათამაშო ან სუფთა, ნოტიო ქსოვილი, რათა ღრძილები დაიმასაჟოს. ეს ტკივილსაც ამცირებს და ბავშვსაც ამშვიდებს.') WHERE id = 'c2f4aabf-8bc7-487e-b896-7f21d18143b1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი ტირის, როდესაც ოთახიდან გადიხართ, მაგრამ დაბრუნებისთანავე მშვიდდება? გილოცავთ, ეს აჩვენებს, რომ მისი მეხსიერება ვითარდება და უკვე გამოგარჩევთ სხვა ადამიანებისგან! ის იწყებს „ობიექტის მუდმივობის“ გაგებას (როდესაც რაღაც თვალს მიეფარება, არ ქრება — უბრალოდ ადგილს იცვლის), თუმცა ამაში ჯერ ბოლომდე დარწმუნებული არ არის. ამ შიშის დაძლევაში შეგიძლიათ „ჭიტას“ თამაშით დაეხმაროთ. სახე ხელებით დაიფარეთ და შემდეგ გამოაჩინეთ — ეს მარტივი თამაში ბავშვს გადასცემს გზავნილს: „დედა რომც წავიდეს, უკან ბრუნდება“.') WHERE id = '807256c5-09ac-42f8-a6ba-9c88ea7f39a0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნუ იფიქრებთ: „ჩემი რძე ცხიმიანი აღარ არის“ ან „ჩემი რძე წყალივითაა“. დედის რძის შემადგენლობა ბავშვის საჭიროებების შესაბამისად მუდმივად იცვლება. პირველ თვეებში არსებული სქელი, მოყვითალო რძე ახლა შეიძლება უფრო წყლიანი ჩანდეს, თუმცა ეს მის დაბალ ხარისხს არ ნიშნავს. ამ თვეში რძეში წყლის შემცველობა იმატებს, რათა ბავშვის მოთხოვნილება სითხეზე დაკმაყოფილდეს (ამიტომ დამატებით წყალი საჭირო არ არის). ბუნებამ ყველაფერი იდეალურად დაარეგულირა — ენდეთ საკუთარ სხეულს.') WHERE id = 'd807fc3e-ee9d-408b-880a-d8041fef08ed';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მიერ გამოცემული ხმები („ა-გუ“, „ბა-ბა“, „ყი-ყი“) უბრალოდ ხმაური არ არის — ეს მეტყველების განვითარების ვარჯიშია. როდესაც ის ხმებს გამოსცემს, თქვენც იგივე ხმით ან მარტივი სიტყვებით უპასუხეთ („ჰო, მართლა? ნამდვილად?“). კვლევები აჩვენებს, რომ ბავშვებს, რომლებიც მშობლებთან „მონაცვლეობით საუბრობენ“ (turn-taking), მომავალში უფრო მაღალი IQ და უკეთესი ენობრივი უნარები აქვთ. ესაუბრეთ მას, როგორც ზრდასრულ ადამიანს — მიუხედავად იმისა, რომ ჯერ თქვენი სიტყვები არ ესმის, ინტონაციასა და კომუნიკაციის წესებს სწავლობს.') WHERE id = '8c9eeb48-f7d1-4cb1-abda-c8b5acd82625';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ხელში ტარებისგან ზურგი და მკლავები გტკივათ? ამან შეიძლება „დედის მაჯა“ (დე კერვენის ტენოსინოვიტი) ან ხერხემლის პრობლემები გამოიწვიოს. ბავშვის აწევისას წელში კი ნუ მოიხრებით, არამედ მუხლები მოხარეთ (როგორც ჩაჯდომისას). ძუძუთი კვების დროს იდაყვის ქვეშ აუცილებლად მოათავსეთ ბალიში, რათა ბავშვის სიმძიმე მკლავს არ დააწვეს. ასევე, ერგონომიული ზურგჩანთის ან სლინგის გამოყენება დატვირთვას თანაბრად გადაანაწილებს და მეტ კომფორტს შეგიქმნით. გაუფრთხილდით საკუთარ ჯანმრთელობას — თქვენს ბავშვს ჯანმრთელი სჭირდებით.') WHERE id = '43116043-105f-43ce-b935-0d355f71fac9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-4 თვეში! „მეოთხე ტრიმესტრი“ უკვე სრულად უკან დარჩა. თქვენი ბავშვი აღარ არის მხოლოდ „ფუთა“, რომელსაც სძინავს და ჭამს — ის უკვე პატარა ადამიანია, რომელიც გარემოს აღიქვამს. ამ თვიდან მისი ძილის ციკლები ზრდასრულებისას ემსგავსება (ჩნდება ზედაპირული და ღრმა ძილის ფაზები). ამ ცვლილებამ ზოგჯერ შეიძლება ძილის დარღვევა გამოიწვიოს, მაგრამ ნუ შეშინდებით; ეს უკუსვლა კი არა, სინამდვილეში განვითარების ნიშანია. მისი ტვინი იზრდება და უბრალოდ ახალ სისტემასთან შეგუებას ცდილობს.') WHERE id = 'eb18b9d2-6fac-4a33-989e-ff8e3c156809';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როცა ბავშვს ხელში აიყვანთ, ამჩნევთ, რომ სხეული უფრო სწორად უჭირავს და თავს თავისუფლად აკონტროლებს? ეს ხერხემლის გამაგრებაზე მიუთითებს. უკვე შეგიძლიათ სცადოთ ერგონომიული ზურგჩანთის პოზიციები, რომლებშიც ბავშვი „სახით გარეთ“ (face out) იქნება მოთავსებული (რა თქმა უნდა, იმ პირობით, რომ მისი ფეხები „M“-ის ფორმაში იქნება). მას სამყაროს თვალიერება მოსწონს, თუმცა ფრთხილად იყავით: ზედმეტმა ვიზუალურმა ინფორმაციამ შეიძლება სწრაფად დაღალოს. თუ მოუსვენარი გახდება, დაუყოვნებლივ შემოაბრუნეთ თქვენკენ და დაამშვიდეთ.') WHERE id = '0ffeb288-283a-4150-a4f7-cffdb0482b4c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ჩემი ბავშვი ჯერ არ ბრუნდება, ხომ არ გვაგვიანდება?“ — თუ ეს კითხვა მოსვენებას არ გაძლევთ, ღრმად ჩაისუნთქეთ. ბავშვები გადაბრუნებას 4-6 თვის ასაკში იწყებენ. ზოგი ბავშვი ჯერ მუცლიდან ზურგზე ბრუნდება, ზოგი კი — პირიქით. თუ თქვენი ბავშვი გვერდზე გადაბრუნებას ცდილობს, ეს შესანიშნავი დასაწყისია. დასახმარებლად მისი საყვარელი სათამაშო გვერდით, ხელმიუწვდომელ მანძილზე დაუდეთ. სათამაშოს მისაწვდომად მას სხეულის შემობრუნება მოუწევს. ეს საუკეთესო ვარჯიშია.') WHERE id = '7165cb2d-519b-4d93-9e14-3abc5973a1c2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თმა ისევ გცვივათ? მე-4 თვე, როგორც წესი, „მშობიარობის შემდგომი თმის ცვენის“ პიკური პერიოდია. სააბაზანოში დაგროვილმა თმამ შეიძლება აგატიროთ, მაგრამ დარწმუნებული იყავით, რომ არ მელოტდებით. უბრალოდ, თმა, რომლის ცვენაც ორსულობის დროს „შეჩერებული“ იყო, ახლა ცვივა. ძვირადღირებული ვიტამინები ან შამპუნები ამ პროცესს ვერ შეაჩერებს — ამას უბრალოდ დრო სჭირდება. ეცადეთ, თმა ძალიან მჭიდროდ არ შეიკრათ და ხშირად არ გაიშროთ ცხელი ჰაერით (ფენით). ახალი თმის („baby hair“) ამოსვლა დაახლოებით მე-6 თვის შემდეგ დაიწყება.') WHERE id = 'd0ba1bd8-2d07-4566-8111-997ecbf838c6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ პერიოდში ბავშვის ღიმილი უკვე ხმამაღალ სიცილად იქცევა! მის გასაცინებლად გამოსცით „უცნაური“ ხმები, ტუჩებით სასაცილო ბგერები გააკეთეთ ან მუცელზე კოცნისას შეუბერეთ. სიცილი აძლიერებს დიაფრაგმას (სუნთქვის კუნთს) და ორგანიზმს უხვად ამარაგებს ჟანგბადით. თუ სიცილის ნაცვლად შეშინდება და ატირდება (ხმამაღალი ხმის გამო), ესე იგი მისი ნერვული სისტემა ჯერ კიდევ ძალიან მგრძნობიარეა. უფრო მშვიდ თამაშებზე გადადით. ყველა ბავშვს განსხვავებული იუმორის გრძნობა აქვს.') WHERE id = '7f993160-1b52-4958-82c0-d5f0cf373852';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიქრობთ ბებიების საყვარელი რეკომენდაციის — „ხოდუნოკის“ (ჭოჭინას) შეძენაზე? ნუ იჩქარებთ! თანამედროვე ორთოპედები და პედიატრები ჭოჭინას გამოყენებას კატეგორიულად არ გირჩევენ. ამ მოწყობილობამ შეიძლება გამოიწვიოს ბავშვის ფეხის წვერებზე სიარული, ხერხემლის ნაადრევად დატვირთვა და გაზარმაცება (რადგან წონასწორობის შენარჩუნებას ვერ სწავლობს). განვითარებისთვის საუკეთესო ადგილი იატაკია (ხალიჩა, დასაფენი). მიეცით საშუალება, თავად სცადოს ხოხვა და მოძრაობა — ეს ბუნებრივი პროცესი კუნთებს უფრო სწორად ავითარებს.') WHERE id = '58105ea4-3801-47f9-97cc-2478fe93cb03';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს ფერადი, ხმოვანი და მანათობელი სათამაშოების მიმართ ინტერესი ეზრდება. თუმცა ყურადღება მიაქციეთ: არსებობს ზღვარი, რომელსაც „ჭარბი სტიმულაცია“ (overstimulation) ეწოდება. თუ ბავშვი უეცრად ტირილს იწყებს, თავს გვერდზე აბრუნებს ან თვალებს ხუჭავს, ამით გეუბნებათ: „საკმარისია! ჩემი ტვინი დაიღალა!“ ასეთ შემთხვევაში ყველა სათამაშო აალაგეთ, ხმაური შეწყვიტეთ და მშვიდად ჩაიხუტეთ. ზოგჯერ საუკეთესო სათამაშო უბრალოდ სიჩუმე და დედის ჩახუტებაა.') WHERE id = 'b4ee2099-bc1d-4919-b3ee-ba22dc951100';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სარკეში ჩახედვისას კვლავ გაწუხებთ ორსულობის შემდეგ დარჩენილი სტრიები? გახსოვდეთ, რომ ეს კვალი თქვენი დედობის ნიშანია. დროთა განმავლობაში ისინი ოქროსფერიდან ვერცხლისფერში გადავა და თანდათან გაფერმკრთალდება. მართალია, მათი სრულად გაქრობა რთულია, მაგრამ კანის დატენიანებამ და მასაჟმა შესაძლოა მათი იერი გააუმჯობესოს. თუმცა ყველაზე მნიშვნელოვანი ის არის, რომ ამ სხეულმა ადამიანი შექმნა და გაზარდა. საკუთარ თავს მკაცრად ნუ მოექცევით — ასეთიც ძალიან ლამაზი ხართ.') WHERE id = 'c1675203-e86f-4f0e-b277-4834368fee01';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როდესაც ბავშვს ზურგზე აწვენთ, ცდილობს ფეხები მაღლა ასწიოს, ხელით დაიჭიროს და პირთანაც კი მიიტანოს? ეს უბრალოდ სახალისო თამაში კი არა, მნიშვნელოვანი ვარჯიშიცაა, რომელიც მუცლის კუნთებს აძლიერებს და ბავშვს საკუთარი სხეულის შეცნობაში ეხმარება. ხელს ნუ შეუშლით — გახადეთ წინდები და მიეცით საშუალება, ფეხის თითებით ითამაშოს. ეს მოძრაობა ხერხემლის ქვედა ნაწილსაც ჭიმავს და ადუნებს, ასევე შესაძლოა აირებით გამოწვეული ტკივილის შემცირებას შეუწყოს ხელი.') WHERE id = '5348f17b-ff81-4e2c-b426-336c5630b994';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '4 თვის ბავშვების სიფხიზლის პერიოდი (wake window), ჩვეულებრივ, 1.5 - 2 საათის ფარგლებში მერყეობს. თუ ბავშვი ამაზე დიდხანს ფხიზლობს, ის „გადაღლილობის“ (overtiredness) მდგომარეობაში გადადის და ჩაძინება კიდევ უფრო უჭირს. საათს დახედეთ: თუ ბოლო ძილიდან 1.5 საათი გავიდა და ბავშვი თვალებს იფშვნეტს, დაუყოვნებლივ დაიწყეთ დამამშვიდებელი რიტუალი. ძილის დროის გამოტოვებამ შესაძლოა ღამით გაღვიძებების რაოდენობა გაზარდოს.') WHERE id = '314c334b-e7f8-4072-b418-2d43d8366274';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ზოგჯერ ბავშვი ძუძუთი კვებისას ან ხელოვნური ნარევის მიღებისას უეცრად ტირილს იწყებს, ჭამაზე უარს ამბობს და ზურგს რკალივით უკან ხრის? ეს შესაძლოა „ფარული რეფლუქსის“ ნიშანი იყოს. კუჭის მჟავა საყლაპავში ამოდის და წვის შეგრძნებას იწვევს. თუ ეს ხშირად მეორდება და წონის მატებას აფერხებს, ექიმს მიმართეთ. სახლში კი კვების დასრულებისთანავე ნუ დააწვენთ — 15-20 წუთის განმავლობაში ვერტიკალურად, მხარზე მიყრდნობილი გეჭიროთ, რათა საკვები კუჭში მშვიდად გადავიდეს.') WHERE id = '1f5459ab-1bd2-4191-b9fa-6cb6903bc60f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნუ ინერვიულებთ და ნუ იკითხავთ: „ჩემი ბავშვი ჯერ რატომ არ იცინის/ბრუნდება?“ განვითარების გრაფიკი შეჯიბრი არ არის. ზოგი ბავშვი „დამკვირვებელია“ — მშვიდად აკვირდება გარემოს, შემდეგ კი მოულოდნელად ყველაფერს აკეთებს; ზოგი კი „მოძრავია“ — მუდმივად მოძრაობს და ცდილობს. ორივე შემთხვევა ნორმალურია. ბავშვის სხვა ბავშვებთან, მათ შორის საკუთარ და-ძმასთან, შედარება თქვენ მხოლოდ სტრესს მოგიტანთ, მას კი დაძაბულობას შეუქმნის. მიიღეთ და შეიყვარეთ მისი უნიკალური ხასიათი ისეთი, როგორიც არის.') WHERE id = '6c7ebcbb-cb8d-440f-985f-f7721a4549c7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-5 თვეში! სახლში ის პატარა "ფუთა" აღარ გყავთ — მის ადგილას უკვე ყველაფრით დაინტერესებული, მომღიმარი, ხმამაღლა მოყვირალი და მოძრავი პატარა პიროვნებაა. ამ თვეში მისი ფიზიკური განვითარება კიდევ უფრო დაჩქარდება: გადაბრუნება, ნივთების ერთი ხელიდან მეორეში გადატანა და შესაძლოა, ხოხვის პირველი მცდელობებიც... თქვენ უბრალოდ უსაფრთხო გარემო შეუქმენით (იატაკზე დაფენილი ხალიჩა) და გვერდიდან დააკვირდით. ზოგჯერ საუკეთესო დახმარება სწორედ ჩაურევლობაა.') WHERE id = 'ab2e9390-020b-4160-8af0-d640595e2268';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი ტუჩებს კრავს და "ბუშტუკებს უშვებს" (ნერწყვიან ბუშტებს აკეთებს)? ამას მხოლოდ იმისთვის არ აკეთებს, რომ დასველდეს და გაგაცინოთ! ეს მოძრაობა ავარჯიშებს ენის, ტუჩებისა და ყბის კუნთებს, რომლებიც მეტყველების განვითარებისთვის ძალიან მნიშვნელოვანია. ამასთანავე, ბავშვი ბგერების წარმოქმნის ფიზიკას სწავლობს: "თუ ტუჩებს ასე მოვამოძრავებ, ასეთი ხმა გამოვა". ნუ ეტყვით, რომ ეს ცუდი საქციელია — პირიქით, აჰყევით და თქვენც გამოუშვით ბუშტუკები. ეს "დიალოგი" მისთვის მსოფლიოში ყველაზე საინტერესო თამაშია.') WHERE id = 'ea92481c-f89e-4020-bcda-f62d11c6d1f3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ხელები უკვე უფრო მოქნილი და გაწაფულია. შეუძლია სათამაშო ერთი ხელით დაიჭიროს და შემდეგ მეორეში გადაიტანოს? "შუა ხაზის გადაკვეთის" (crossing the midline) ეს უნარი მიუთითებს, რომ თავის ტვინის ნახევარსფეროებს შორის კავშირი ძლიერდება. ამ უნარის განსავითარებლად ორი სხვადასხვა სათამაშო მიეცით: ერთი მარჯვენა, მეორე კი მარცხენა ხელში. შემდეგ მესამე სათამაშო შესთავაზეთ. დააკვირდით, დააგდებს თუ არა ხელში დაჭერილთაგან ერთ-ერთს, რათა მესამე აიღოს. ეს გადაწყვეტილების მიღების მისი პირველი მომენტია.') WHERE id = 'c16f8e30-0e77-4445-93ae-cd9830a7f241';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-5 თვეში ბავშვები ფერებს, განსაკუთრებით წითელს, ლურჯსა და ყვითელს, უკვე ძალიან მკაფიოდ ხედავენ. ამავე დროს უვითარდებათ სიღრმის აღქმაც (3D მხედველობა). ბავშვს უკვე შეუძლია დაახლოებით განსაზღვროს, რამდენად შორსაა სათამაშო და ხელი პირდაპირ მისკენ გაიწოდოს. ამ პერიოდში სარკის წინ დაყენება ან ფერადი ბურთებით თამაში თვალისა და ხელის კოორდინაციას აუმჯობესებს. თუ ჯერ კიდევ ამჩნევთ სიელმეს (თვალები ზოგჯერ ერთმანეთისკენ იყურება), ამ თვეში ის უკვე უნდა შემცირდეს; თუ გაგრძელდა, სასურველია ბავშვი ექიმს აჩვენოთ.') WHERE id = '1f034b11-0fbb-48ea-bbf4-278ca6b86b2b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როდესაც ბავშვს სხვა ადამიანი აიყვანს ხელში (თუნდაც ბებია ან დეიდა), ტუჩებს კრავს და ტირილს იწყებს? დედებს ხშირად ამის რცხვენიათ და დარდობენ, რომ მათი ბავშვი "უცხოობს". სინამდვილეში კი ეს მისი გონებრივი განვითარების მაჩვენებელია! მას უკვე ესმის განსხვავება "ახლობელსა" (თქვენ და მამა) და "უცხოს" (დანარჩენები) შორის. ეს "უცხო ადამიანების შიში" (stranger anxiety) განვითარების ნორმალური ეტაპია. ნუ გადასცემთ ბავშვს ძალით სხვის ხელში — მიეცით საშუალება, ჯერ თქვენს მკლავებში ყოფნისას შეეჩვიოს იმ ადამიანს და თავი უსაფრთხოდ იგრძნოს.') WHERE id = 'c6a4085b-3a97-4e0b-b5f5-5b36782649fe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ხშირად გირჩევენ: "ბავშვი ვერ ნაყრდება და ღამით იღვიძებს, მოდი, ფაფა მივცეთ"? გახსოვდეთ, რომ ღამით გაღვიძების მიზეზი ხშირად შიმშილი კი არა, ძილის ციკლების ცვლილება, კბილების ამოჭრით გამოწვეული ღრძილების ქავილი ან უბრალოდ თქვენთან ყოფნის სურვილია. 5 თვის ბავშვის საჭმლის მომნელებელი სისტემა ჯერ სრულად ჩამოყალიბებული არ არის (ფერმენტები საკმარისი რაოდენობით არ გამომუშავდება). დამატებითი კვების ნაადრევად დაწყება ზრდის ალერგიის რისკს და დედის რძის შემცირებას იწვევს. ჯანმოს რეკომენდაცია უცვლელია: პირველი 6 თვის განმავლობაში მხოლოდ რძე. ნუ იჩქარებთ — კოვზის დასაჭერად მთელი ცხოვრება წინ აქვს.') WHERE id = 'c26a80c4-409b-4945-b7d2-51c416190946';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე შეგიძლიათ დაიწყოთ ვარჯიში, რათა ბავშვმა საკუთარი სახელის ცნობა ისწავლოს. გარდა იმისა, რომ „საყვარელო“ და „ლამაზო“ დაუძახებთ, ხშირად მიმართეთ სახელითაც. ოთახის მეორე კუთხიდან დაუძახეთ და დააკვირდით, შემობრუნდება თუ არა თქვენკენ. თუ შემობრუნდება და შემოგხედავთ, დიდი სიხარულით შეაქეთ („ყოჩაღ!“). ეს მისი სოციალური იდენტობის ჩამოყალიბების პირველი ნაბიჯია. ბავშვი უკვე იწყებს იმის გააზრებას, რომ ამ სამყაროში ცალკე პიროვნებაა.') WHERE id = 'e2e55b95-3a42-4c60-9aac-15653d87bc0a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ პერიოდში დედების ყველაზე დიდი მტერი „ყველაფრის მცოდნე ნათესავების“ ზეწოლაა: „ბავშვი გამხდარია, ვერ ნაყრდება, ფაფა მიეცი“. გახსოვდეთ: ბავშვის ფუმფულა აღნაგობა ჯანმრთელობის მაჩვენებელი არ არის. მთავარი მაჩვენებლებია სიმაღლეში მატება, თავის გარშემოწერილობა და აქტიურობა. მე-4 თვეში დამატებითი კვების დაწყება, თუ ამის სამედიცინო ჩვენება არ არსებობს, მის ნაწლავებს ზედმეტად დატვირთავს, ალერგიის რისკს გაზრდის და დედის რძის მიღებას შეამცირებს. უბრალოდ უთხარით „კი“ და საუბარი დაასრულეთ, მაგრამ მოიქეცით ისე, როგორც თავად იცით — ჯანმოს რეკომენდაციის შესაბამისად.') WHERE id = '79a1bd17-ef80-4f02-a1a6-cec0947ec9fb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ მუცელზე წოლისას (tummy time) თქვენი ბავშვი ხელებით იატაკს ეყრდნობა და მკერდის სრულად აწევა შეუძლია, წინ საინტერესო სათამაშო დაუდეთ, თუმცა ისეთ მანძილზე, რომ ვერ მისწვდეს. სათამაშომდე მისაღწევად ის შეეცდება სიმძიმის ცენტრის გადატანას და, შესაძლოა, ერთი ხელის იატაკიდან აწევასაც. ეს „წონასწორობის ვარჯიში“ მომავალში ხოხვისთვის ძალიან მნიშვნელოვანია. თუ ვერ გამოუვა და გაღიზიანდება, სათამაშო ოდნავ მიუახლოვეთ, რათა მოტივაცია არ დაკარგოს.') WHERE id = '9069addc-9d36-4d58-8ceb-48b115881ebe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვის მიერ გამოცემული ბგერები უკვე „ა-უ“ ხმოვნებიდან „მ-ბ-პ“ თანხმოვნებზე გადავიდა? შესაძლოა, შემთხვევით „მა-მა“ ან „ბა-ბა“ თქვას. ეს იმას არ ნიშნავს, რომ უკვე გააზრებულად გეძახით — ჯერ მხოლოდ ტუჩის კუნთებს ავარჯიშებს. თუმცა თქვენ დიდი აღფრთოვანებით უპასუხეთ: „დიახ, მე დედა ვარ!“. თქვენი რეაქცია წაახალისებს, გაიმეოროს ეს ბგერები და მეტყველება განივითაროს.') WHERE id = '124a08e0-8297-466a-ad92-5da9e2b40124';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეოთხე თვეში ბავშვის ძილის რეჟიმის ჩამოსაყალიბებლად შეგიძლიათ „ძილის ასოციაცია“ (Sleep Associations) შექმნათ. თუ ის მხოლოდ ძუძუს წოვისას ან რწევისას იძინებს, ნელ-ნელა დაიწყეთ ამ ჩვევის შეცვლა. მაგალითად, როცა ჩაძინებას დაიწყებს, მაგრამ ჯერ ბოლომდე არ ეძინება, საწოლში ჩააწვინეთ, უბრალოდ ხელი დაადეთ და უთხარით „შშშ“. პირველ დღეებში გააპროტესტებს, მაგრამ თუ მოთმინებას გამოიჩენთ, თანდათან საკუთარი თავის დამშვიდებას (self-soothing) ისწავლის. ეს ხანგრძლივი პროცესია, ამიტომ ნუ იჩქარებთ.') WHERE id = '440c73d7-8d87-4380-afc8-4a3037eff65e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! თქვენი ბავშვი უკვე 4 თვისაა! ეს ჩვილობის პერიოდის „ოქროს შუალედია“. ის უკვე არც ძალიან პატარა და უმწეოა და არც იმდენად მოძრავი, რომ დაგღალოთ. ამ თვეში ექიმთან გასინჯვისას შესაძლოა აღმოაჩინოთ, რომ მისი წონა დაბადების წონასთან შედარებით დაახლოებით 2-ჯერ გაიზარდა — ეს საშუალო მაჩვენებელია. ის უკვე ხედავს ფერებს, ცნობს ხმებს და თქვენზე უზომოდ შეყვარებულია. დატკბით ამ პერიოდით, რადგან მალე კბილების ამოჭრისა და ხოხვის თავგადასავლები დაიწყება! თქვენ შესანიშნავად ართმევთ თავს, დედიკო!') WHERE id = 'c7fd582a-aa6d-4d77-b362-3fa53514647a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი კვლავ განაგრძობს ფეხების აღმოჩენას. თუ მას ფეხის თითები პირთან მიაქვს და წოვს, ნუ შეუშლით ხელს. ეს მოძრაობა ხერხემლის მოქნილობას უწყობს ხელს, მენჯ-ბარძაყის სახსრებს ხსნის და სხეულის წონასწორობის პოვნაში ეხმარება. ამავდროულად, ასე ის საკუთარი სხეულის საზღვრებს ეცნობა ("აჰა, ეს თითიც მე მეკუთვნის"). გახადეთ წინდები და მიეცით საშუალება, ფეხები "დააგემოვნოს".') WHERE id = '0696d902-62ea-41fb-ac33-42f63be246d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის წონა უკვე საგრძნობლად გაიზარდა (შესაძლოა, დაახლოებით 6-8 კგ იყოს) და მისი მუდმივად ხელში ტარება თქვენს ხერხემალს სერიოზულად ტვირთავს. ყურადღება მიაქციეთ "ერგონომიული ტარების" წესებს: ბავშვი მენჯთან მყარად დაიჭირეთ და წონა თანაბრად გადაანაწილეთ; მოერიდეთ მის ცალ მხარეს (მხოლოდ მარჯვენა ან მარცხენა თეძოზე) ტარებას, რადგან ამან შესაძლოა ხერხემლის გამრუდებას შეუწყოს ხელი. შეძლებისდაგვარად, უპირატესობა იატაკზე თამაშს მიანიჭეთ. თქვენი წელისა და ზურგის ჯანმრთელობა გადამწყვეტია, რათა ბავშვზე ზრუნვა შეძლოთ.') WHERE id = 'd400ec9f-412b-4ad6-988e-58b62c0416fd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი სათამაშოს იატაკზე აგდებს, თქვენ იღებთ, ის კი კვლავ აგდებს და იცინის? ამან შეიძლება დაგღალოთ, მაგრამ მისთვის ეს ფიზიკის ექსპერიმენტია! ის "მიზეზ-შედეგობრივ" კავშირს სწავლობს: "მე ამას ვაგდებ (მიზეზი), დედა იღებს (შედეგი), ან ხმა ისმის". ეს თამაში მას აგრძნობინებს, რომ სამყაროზე ზემოქმედება შეუძლია. ნუ გაბრაზდებით; გახსოვდეთ, რომ ეს განვითარებისთვის მნიშვნელოვანია და მოთმინებით განაგრძეთ თამაში (ან გამოიყენეთ თოკზე დამაგრებული სათამაშოები).') WHERE id = 'fe5f82f2-00a9-4854-b3e5-0b8ebb578153';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის დღის ძილი თანდათან უფრო მოწესრიგებული ხდება ("დღის ძილის რეჟიმის ცვლილება"). ადრინდელი უწესრიგო და ხანმოკლე ძილი შეიძლება დღეში 3-ჯერ (დილით, შუადღით და ნაშუადღევს) შედარებით ხანგრძლივმა ძილმა ჩაანაცვლოს. ბოლო ძილი (ნაშუადღევის მოკლე თვლემა), ჩვეულებრივ, ხანმოკლეა (30-40 წთ) და ღამის ძილზე გადასვლას ამარტივებს. თუ მას ჯერ კიდევ უწესრიგოდ სძინავს, დააკვირდით "ძილის ფანჯარას" (ღვიძილის ხანგრძლივობას) და ეცადეთ, ზედმეტად დაღლამდე დააძინოთ. ძილს ძილი მოჰყვება.') WHERE id = '5d110284-d82d-4dbe-8144-2a516161ad7f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ბავშვს ფეხები პირთან მიაქვს, თითქოს მათ "აგემოვნებს"? ეს სანახაობა შეიძლება ძალიან სასაცილო იყოს, მაგრამ სინამდვილეში შესანიშნავი მიღწევაა, რომელიც მისი ხერხემლის მოქნილობასა და სხეულის კოორდინაციაზე მიუთითებს. ის სხეულის ქვედა ნაწილს აღმოაჩენს. ნუ შეუშლით ხელს (გახადეთ წინდები, რომ უფრო კომფორტულად იყოს). ეს მოძრაობა აირების დაგროვებით გამოწვეული ტკივილის ბუნებრივად შემსუბუქებასაც უწყობს ხელს.') WHERE id = '66fe21ca-05fd-4c48-95fa-5f031cadebb2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-5 თვეში ბავშვებს ყვირილი, წივილი და ხმის აწევა უყვართ. ზოგჯერ ეს ხმაური შეიძლება ყურისწამღები იყოს, მაგრამ ნუ შეგეშინდებათ — ის თქვენზე არ ბრაზობს. უბრალოდ, საკუთარ ხმოვან იოგებს "ამოწმებს": "ნეტავ, რამდენად ხმამაღლა შემიძლია ვიყვირო?". ასე ის საკუთარი ხმის მართვას სწავლობს. უპასუხეთ ჩურჩულით; ისიც შეეცდება, მოგბაძოთ და ხმას დაუწიოს. ეს შესანიშნავი თამაშია.') WHERE id = 'd03675dd-580b-4a83-a42a-a1376cb7a774';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ უკვე დაიწყეს კითხვები: „ბავშვს ჯდომა შეუძლია?“, ნუ იჩქარებთ. ბავშვის ბალიშებს შორის ჩასმა და ძალით დასმა (თუ თავად ჯერ მზად არ არის) შეიძლება მის ხერხემალს ავნოს. მე-5 თვეში ბავშვებმა შეიძლება სცადონ „სამფეხა ჯდომა“ (წინ ხელებზე დაყრდნობით ჯდომა), თუმცა ჯერ სრულად ვერ ინარჩუნებენ წონასწორობას. საუკეთესო ვარჯიში იატაკზე, მუცელზე წოლით თამაშია. ზურგის კუნთების გაძლიერებასთან ერთად, ის თავად წამოიწევა და დაჯდება.') WHERE id = 'e21494e3-d1b4-470c-8b69-91bdff0641cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბებიების რჩევა — „ცოტა წვნიანის ბულიონი მიეცი, გემო რომ გაიგოს“ — ისევ აქტუალურია? უნდა იცოდეთ, რომ ბავშვის ნაწლავები ჯერ კიდევ „საცერივითაა“ (ნაწლავის გამტარობა მაღალია). დედის რძისა და ხელოვნური ნარევის გარდა მიღებულმა ნებისმიერმა საკვებმა (თუნდაც წყალმა ან წვენმა) შეიძლება ეს ბარიერი გადალახოს და ალერგია ან საჭმლის მონელების პრობლემები გამოიწვიოს. „გემოს გასაგებად“ მას ჯერ კიდევ ბევრი დრო ექნება, ახლა მთავარი მიზანი მისი ნაწლავური ფლორის დაცვაა. თქვენ „ცუდი რძალი“ კი არა, „ცოდნით შეიარაღებული დედა“ ხართ.') WHERE id = '2049b273-04ed-4768-bc4b-392861691428';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გაშინებთ, რომ ბავშვი ღამით ძილში თავისით ბრუნდება მუცელზე? თუ დღის განმავლობაში თავისუფლად ბრუნდება ორივე მიმართულებით (ზურგიდან მუცელზე და მუცლიდან ზურგზე), ღამით ყოველ ჯერზე გადმობრუნება საჭირო არ არის. უბრალოდ დარწმუნდით, რომ მის საწოლში არ დევს ბალიში, საბანი ან რბილი სათამაშოები (დახრჩობის რისკის თავიდან ასაცილებლად). ის თავად აირჩევს მისთვის კომფორტულ პოზას. თქვენც მშვიდად დაიძინეთ.') WHERE id = '75eb58f4-2826-4a4a-8b58-b49e3d0b9d70';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ თვეში ბავშვს შეიძლება თმა დასცვივდეს და მის ადგილას ახალი ამოსვლა დაიწყოს („ჩვილის თმის“ შეცვლა). ზოგჯერ კეფაზე „მელოტი ლაქა“ ჩნდება — ეს უბრალოდ ხახუნისგან (დიდხანს წოლისგან) წარმოიქმნება და სრულიად ნორმალურია. როცა ბავშვი ჯდომას და უფრო მეტ მოძრაობას დაიწყებს, თმაც თანაბრად გაიზრდება. ეს ვიტამინების დეფიციტი არ არის, ნუ ინერვიულებთ.') WHERE id = 'f63f93ff-407c-4880-934c-4db268020afd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე ამჩნევს პატარა საგნებს (მაგალითად, იატაკზე მტვრის ნაწილაკს ან ტანსაცმელზე ძაფს) და თითებით მათ აღებას ცდილობს. მისი მხედველობა იმდენად გამახვილდა, რომ წვრილმანების გარჩევა შეუძლია. ამ პერიოდში უსაფრთხოება 1 ნომერი წესია. ღილები, მონეტები, საყურეები — ყველაფერი მისთვის მიუწვდომელ ადგილას შეინახეთ. ის ჯერ კიდევ პირით შეიცნობს სამყაროს და ყველაფერს, რასაც იპოვის, პირში ჩაიდებს.') WHERE id = '50867048-47ec-4339-857c-cdebcdc6c314';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ჭოჭინის შეძენა გსურთ? კიდევ ერთხელ დაფიქრდით. ბევრ განვითარებულ ქვეყანაში (მაგალითად, კანადაში) ამ მოწყობილობის გაყიდვა აკრძალულია. მიზეზი: ის ხელს უწყობს ბავშვის თითის წვერებზე სიარულს (ქუსლის იატაკზე დაუდგმელად), ხერხემლის ნაადრევ დატვირთვას და, რაც მთავარია, სახიფათო ადგილებამდე (ცხელი ჩაიდანი, კიბე) სწრაფად მიღწევის შესაძლებლობას აძლევს. განვითარებისთვის საუკეთესო საშუალება იატაკია. მიეცით საშუალება, ხოხვით გაიძლიეროს კუნთები.') WHERE id = '700936b7-4cd2-492b-9509-98a14c16e71e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სარკეში ჩახედვისას თავს მოუვლელად და დაღლილად გრძნობთ? დეკრეტული შვებულება ზოგჯერ „ზაზუნას დღეს“ (ერთი და იმავე დღის გამეორებას) ჰგავს. დღეს ბავშვი მამას ან ბებიას დაუტოვეთ და 1 საათით სახლიდან გადით. უბრალოდ მაღაზიაში წასვლა, პარკში მარტო გასეირნება ან თმის შეჭრა თქვენთვის „ჟანგბადის ნიღაბივით“ იმოქმედებს. თუ თქვენ ბედნიერი იქნებით, თქვენი ბავშვიც ბედნიერი იქნება.') WHERE id = '3c6e4f71-0ba2-4930-a133-04552c20e1dd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, მე-5 თვის შუაში ხართ! ბავშვის წონის მატება შესაძლოა ისეთი სწრაფი აღარ იყოს, როგორიც პირველ თვეებში იყო (თვეში 1 კგ-ის ნაცვლად 400-500 გ). ეს ნორმალურია, რადგან ბავშვი უფრო მეტს მოძრაობს და ენერგიას ხარჯავს. სანამ ექიმის გრაფიკზე „მრუდი“ ზემოთ მიემართება, სანერვიულო არაფერია. ნუ ინერვიულებთ იმაზე, რომ „რძე შემიმცირდა და ბავშვმა წონა დაკარგა“ — უბრალოდ დატკბით მისი აქტიურობით.') WHERE id = '77295e93-c83b-4ff4-8d09-da9b139b8a65';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როცა ჭამთ, თქვენი ბავშვი პირს აღებს, ყურადღებით გაკვირდებათ ან თქვენს თეფშს ხელით სწვდება? ეს „საკვებისადმი ბიოლოგიური ინტერესია“. მას თქვენი მიბაძვა სურს და ეს აუცილებლად არ ნიშნავს, რომ შია. დამატებითი კვების დასაწყებად მხოლოდ ინტერესი საკმარისი არ არის; ბავშვს უნდა შეეძლოს თავის ვერტიკალურად დაჭერა, დაუხმარებლად (ან მცირედი დახმარებით) ჯდომა და, რაც მთავარია, „ენის გამოყოფის რეფლექსი“ (საკვების ენით უკან გამოდევნა) უნდა ჰქონდეს გამქრალი. ჯერჯერობით ცარიელი კოვზი მიეცით და თამაშის საშუალება მისცეთ, საკვების მიცემამდე კი კიდევ ცოტა მოითმინეთ.') WHERE id = '7853d6dc-3fa1-4c99-9bee-ffadc85c9246';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მუცელზე წოლისას თქვენი ბავშვი ხელებსა და ფეხებს ჰაერში სწევს და „სუპერმენივით“ დაფრინავს? მიუხედავად იმისა, რომ ეს მოძრაობა ძალიან საყვარლად გამოიყურება, სინამდვილეში სერიოზული ვარჯიშია. ზურგის, კისრისა და დუნდულების კუნთების დაძაბვით ის მომავალი ცოცვისა და ჯდომისთვის ძალას იკრებს. ამ დროს ხელს ნუ შეუშლით, უბრალოდ წინ საინტერესო სათამაშო დაუდეთ, რათა მოტივაცია მისცეთ.') WHERE id = 'ee5e432a-11cb-49f0-b780-4af770910a6e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-5 თვეში ბავშვები ზოგჯერ უცნაურ ხმებს გამოსცემენ — ხიხინს, ხველის იმიტაციას ან ხმამაღალ შეძახილებს. როცა შეშინდებით და ექიმთან წასასვლელად მოემზადებით, მან შეიძლება გაგიღიმოთ. ეს მისი პატარა „ექსპერიმენტია“, რომლის დროსაც საკუთარ ხმოვან იოგებს ცდის. ის სწავლობს, რომელი მოძრაობა რა ხმას გამოსცემს. თუ სიცხე ან დაავადების სხვა ნიშანი არ აქვს, უბრალოდ დატკბით ამ „კონცერტით“.') WHERE id = 'b8f6e7f4-fa6c-4da7-b344-5fdbda538ecd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ამჩნევთ, რომ ძილის დროს ბავშვი თავს ყოველთვის ერთსა და იმავე მხარეს აბრუნებს ან კეფა გაბრტყელებული აქვს, ფხიზლად ყოფნისას თამაშის მიმართულება შეუცვალეთ. თუ ჩვეულებრივ მარჯვენა მხრიდან უახლოვდებით, ახლა მარცხენა მხრიდან დაელაპარაკეთ. საწოლს ადგილი შეუცვალეთ, რათა სინათლის ან თქვენკენ გამოხედვისას ბავშვი იძულებული იყოს, თავი მეორე მხარეს მიაბრუნოს. ეს მარტივი ცვლილება კისრის კუნთების თანაბარ განვითარებას შეუწყობს ხელს.') WHERE id = 'b66d2212-4a92-4a46-b745-aeb8c99cd2a4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კბილების ამოჭრის პერიოდში ბავშვის იმუნიტეტი შეიძლება ოდნავ დასუსტდეს, თუმცა ერთმანეთში არ აურიოთ „კბილების ამოჭრით გამოწვეული სიცხე“ და „ვირუსული ინფექცია“. კბილების ამოჭრისას ტემპერატურა, ჩვეულებრივ, 38 გრადუსზე მაღლა არ იწევს და სურდო ან ხველა არ აღინიშნება. თუ ბავშვს მაღალი სიცხე აქვს და მოთენთილია, ამას მხოლოდ კბილების ამოჭრას ნუ მიაწერთ და ნუ დამშვიდდებით — აუცილებლად შეატყობინეთ მის ექიმს.') WHERE id = 'ec752558-6d74-4751-872c-b47b29cef0cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ პერიოდში დედებს შესაძლოა მენსტრუაცია აღუდგეთ — ზოგს უფრო ადრე, ზოგს კი უფრო გვიან. მოსაზრება, რომ „მეძუძურ დედას მენსტრუაცია არ აქვს“, მითია. მენსტრუაციის დაწყებისას რძის რაოდენობა შეიძლება ოდნავ შემცირდეს ან მისი გემო შეიცვალოს ჰორმონების გავლენით, რის გამოც ბავშვმა შესაძლოა ძუძუზე უარი თქვას. თუმცა რძის ხარისხი არ უარესდება და ის არ „იწამლება“. განაგრძეთ ძუძუთი კვება — ეს დროებითი მდგომარეობაა.') WHERE id = 'ad62d3cf-28a5-411d-86f8-d16d19e156b2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ბავშვს უკვე მოსწონს ხელში დაჭერილი სათამაშოს იატაკზე ან მაგიდაზე ბრახუნი? ეს დამანგრეველი ქცევა კი არა, მისი „ხმის ინჟინერიაა“! ის აღმოაჩენს ხმას, რომელიც მყარი საგნის მყარ ზედაპირზე დარტყმისას წარმოიქმნება. ხელის შეშლის ნაცვლად, მიეცით სხვადასხვა ხმის გამომცემი ნივთები — ხის კოვზი, პლასტმასის ჭურჭელი ან რბილი სათამაშო. აუხსენით განსხვავება: „ნახე, ეს აკაკუნებს, ეს კი ხმას არ გამოსცემს“.') WHERE id = '62ce75ea-f714-4996-ae9c-54a3b27495ac';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ზუსტად ახლაა დრო, სახლში ბავშვის უსაფრთხოებისთვის განკუთვნილი ზომები („Babyproofing“) გააძლიეროთ. ბავშვი ჯერ შესაძლოა არ ხოხავდეს, მაგრამ გადაგორებით ან ცოცვით შეუძლია მისწვდეს ელექტროროზეტებს, ჩამოკიდებულ სადენებს ან სუფრის გადასაფარებლის კიდეს. დაეშვით მის სიმაღლეზე — დაწექით იატაკზე — და სახლს მისი თვალით შეხედეთ: რა ჩანს იატაკიდან სახიფათოდ? მოაშორეთ ყველა სარისკო ნივთი, რადგან უბედური შემთხვევა მოსვლას წინასწარ არ გვატყობინებს.') WHERE id = 'aff088aa-a1cd-4138-acbc-e2c0688efeb6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ბავშვის კანზე მშრალი ლაქები ან სიწითლეები — ატოპიური დერმატიტი/ეგზემა — გაჩნდა, მაშინვე ნუ დააბრალებთ ამას თქვენს რაციონს. ხშირად მიზეზი საკვები კი არა, გარემო პირობებია: მშრალი ჰაერი, სინთეტიკური ტანსაცმელი, სარეცხი ფხვნილი ან ზედმეტად ცხელი წყლით დაბანა. გაზარდეთ ოთახში ჰაერის ტენიანობა, ბავშვს დამატენიანებელი კრემი (ემოლენტი) ნაზი მასაჟით წაუსვით, დაბანის შემდეგ კი კანი არ გაუხეხოთ — მსუბუქი შეხებით შეამშრალეთ.') WHERE id = '572d9eb0-1241-494b-9f36-13d0ee848f80';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! თქვენი ბავშვი უკვე 5 თვისაა! ნახევარ წლამდე (6 თვემდე) სულ ცოტა დრო დარჩა. ეს თვე მისთვის მნიშვნელოვანი გარდამავალი პერიოდია: ის უკვე უფრო მკაფიოდ გამოხატავს ემოციებს — სიხარულისას შეძახილებით გამოხატავს აღტაცებას, ხოლო როცა რამე არ სურს, ხელს ჰკრავს. თქვენც წარმოუდგენლად დიდი გზა გაიარეთ ამ 5 თვის განმავლობაში. უძილო ღამეებისა და დაღლილობის მიუხედავად, თქვენ მისი სამყაროს ცენტრი ხართ. საკუთარ თავს „მადლობა“ უთხარით და ეს დღე პატარა ღიმილით აღნიშნეთ!') WHERE id = '7802c1ee-5da4-41a5-a0b7-633ee14ee9a9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-6 თვის პირველ დღეს! ახლა „დამატებითი კვების“ (supplementary feeding) თემა სახლში ყველაზე აქტუალურია. ბებიებმა შეიძლება იჩქარონ, მაგრამ გახსოვდეთ ჯანმოს ოქროს წესი: 6 თვის შესრულებამდე — მხოლოდ დედის რძე (ან ხელოვნური საკვები). თუმცა მომზადება უკვე შეგიძლიათ დაიწყოთ! შეამოწმეთ, მზად არის თუ არა ბავშვი ამისთვის: შეუძლია დაუხმარებლად ჯდომა? თავს გამართულად იჭერს? როცა თქვენ ჭამთ, ინტერესით აცმაცუნებს პირს? თუ პასუხები „კი“ არის, თავგადასავალი ახლოსაა.') WHERE id = 'c07d39a8-4230-4141-b911-a428b18acb0f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი ძუძუთი კვებისას გკბენთ? ეს შეიძლება ნიშნავდეს, რომ ღრძილები ექავება ან უკვე დანაყრებულია და თამაში სურს. ნუ დაუყვირებთ და ნუ შეაშინებთ — ამან შესაძლოა ძუძუზე უარი ათქმევინოს. მშვიდად უთხარით „არა“ და ძუძუ პირიდან გამოაცალეთ (ნეკა თითი პირის კუთხეში ფრთხილად ჩაუდეთ, რომ ვაკუუმი დაირღვეს). თუ მიხვდება, რომ კბენა კვებას ასრულებს, ამას აღარ გაიმეორებს. კბენის წინააღმდეგ თქვენი საუკეთესო დამხმარე ცივი კბილთსაჭრელია.') WHERE id = '1c9ac763-40c0-4c2c-9037-aa4d0926c708';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის დასასმელად „ბალიშების ციხესიმაგრეების“ გამოყენებას ნუ იჩქარებთ. თუ ის თავად არ ცდილობს დაჯდომას და ზურგს მოხრის ისე, რომ „C“ ასოს ემსგავსება (მოკუნტული პოზა), ესე იგი, მისი კუნთები ჯერ მზად არ არის. ძალით დასმამ შესაძლოა ხერხემალი დაუზიანოს. მიეცით საშუალება, მეტი დრო გაატაროს იატაკზე და თავად მიიღებს „Tripod“ პოზას (ხელებზე წინ დაყრდნობით). ბუნებრივი განვითარება ყოველთვის ყველაზე უსაფრთხოა.') WHERE id = '026af185-68d2-497b-b2e5-6cbcde3b4230';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კბილების ამოსვლის გელის (gel) გამოყენებისას ძალიან ფრთხილად იყავით. „Lidokain“-ის ან „Benzokain“-ის შემცველმა გელებმა შეიძლება ბავშვს სერიოზული საფრთხე შეუქმნას (ყლაპვის გაძნელებისა და გულის რიტმის დარღვევების რისკი). FDA (ამერიკის სურსათისა და წამლების ადმინისტრაცია) ჩვილებისთვის ამ ნივთიერებების გამოყენებას არ გირჩევთ. ამის ნაცვლად, ბუნებრივი შემადგენლობის გელები ან უბრალოდ გაცივებული რეზინის სათამაშოები და ნესტიანი დოლბანდით ღრძილების მასაჟი უფრო უსაფრთხო და ეფექტურია.') WHERE id = 'd57483e9-dfea-4122-86d2-ac70acfdcbfd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როცა ბავშვი მუცელზე წევს, ხელებით იატაკს აწვება და უკან („კიბორჩხალასავით“) ხოხვა დაიწყო? ეს ხოხვის პირველი ეტაპია! მას წინ წასვლა სურს, მაგრამ რადგან ხელები ფეხებზე ძლიერი აქვს, უკან გადაადგილდება. ამან შეიძლება გააღიზიანოს. დასახმარებლად ხელისგული ტერფებთან მიუდეთ, რათა მასზე დაყრდნობით წინ გაიწიოს. მოთმინება იქონიეთ — მალე მთელ სახლს დაიპყრობს.') WHERE id = '1cfdff71-da32-4931-b5cb-94e1a37d4db0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ამ თვეში ბავშვის ძილი შესაძლოა კვლავ აირიოს, თუმცა ამჯერად მიზეზი შეიძლება „განშორების შფოთვა“ (separation anxiety) იყოს. ოთახიდან თქვენს გასვლას ის აღიქვამს, როგორც „მიმატოვა“. დაძინებისას ცოტა მეტხანს დარჩით მის გვერდით და შეეხეთ, თუმცა ნუ იჩქარებთ ხელში აყვანასა და ტარებას (თორემ შეიძლება ჩვევად ექცეს). ეთამაშეთ „ჭიტა“ (დამალობანა), რათა ისწავლოს, რომ დედა მიდის და ისევ ბრუნდება. ეს შიში დროებითია, ნდობის განცდა კი — მუდმივი.') WHERE id = 'bda07f09-37eb-4be3-a16a-4bf2694b38b8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'აქტუალური ხდება კითხვა: "როდის დავიწყოთ წყლის მიცემა?" იმ დღეს, როცა დამატებითი საკვების (მყარი საკვების) მიცემას დაიწყებთ, წყალიც უნდა შესთავაზოთ. მანამდე (თუ ჯერ მყარ საკვებს არ აძლევთ) წყალი საჭირო არ არის — დედის რძე/ხელოვნური ნარევი საკმარისია. შეგიძლიათ ახლავე უყიდოთ პატარა, არადამღვრელი "წყლის ჭიქა" (sipper cup/sulud) და გააცნოთ (წყლის ჩასხმის გარეშე). მიეცით, რომ ხელში დაიჭიროს, პირთან მიიტანოს და სათამაშოსავით ეთამაშოს. ასე, როცა დრო მოვა, მისთვის უცხო აღარ იქნება.') WHERE id = 'ff09c584-fe70-41cf-951d-eb545f630c39';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის საფენის გამოცვლა უკვე ჭიდაობის შეჯიბრს დაემსგავსა? ის არ ჩერდება, ტრიალდება და გაქცევას ცდილობს. ეს იმიტომ ხდება, რომ მოძრაობის თავისუფლებით ტკბება. ნუ გაღიზიანდებით, უბრალოდ სტრატეგიულად იმოქმედეთ: საფენის გამოცვლისას ხელში მიეცით საინტერესო ნივთი, რომელიც მანამდე არ უნახავს (მაგალითად, კრემის სუფთა ქილა), ან სიმღერით გადაატანინეთ ყურადღება. ზოგჯერ შეიძლება საფენის გამოცვლა ფეხზე დგომისას ან ოთხზე ცოცვისასაც კი მოგიწიოთ — სწორედ ეს არის დედობის ოსტატობა!') WHERE id = '5c0bcce8-2d98-4e33-ab73-d613b0c76c24';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი იმეორებს მარცვლებს "ბა-ბა", "და-და", "მა-მა"? მამები, ჩვეულებრივ, სიხარულით ამბობენ: "მამა თქვა!", თუმცა ჯერჯერობით ეს გაცნობიერებული მიმართვა კი არა, უბრალოდ ბგერებით ვარჯიშია (babbling). მაგრამ თქვენ ამ ბგერებს მნიშვნელობა შესძინეთ: "დიახ, ეს მამაა!", "დიახ, მე დედა ვარ!". როდესაც ამ სიტყვებს საგნებს ან ადამიანებს უკავშირებთ, ბავშვის გონებაში ლექსიკური მარაგი ყალიბდება. მალე ის ამ სიტყვების მიზანმიმართულად გამოყენებას დაიწყებს.') WHERE id = 'ea83f521-c253-469b-809a-6bfb8bc161b2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '6 თვემდე (ნახევარ წლამდე) სულ რაღაც 20 დღე დარჩა! უკვე შეარჩიეთ დამატებითი კვებისთვის "საბავშვო სკამი" (კვების სკამი)? სკამის შერჩევისას ყველაზე მნიშვნელოვანი პირობაა: ბავშვს ზურგი სწორად უნდა ჰქონდეს, ფეხები კი აუცილებლად ეყრდნობოდეს საყრდენს (ფეხის დასადებს). თუ ბავშვს ფეხები ჰაერში აქვს ჩამოკიდებული, ის დისკომფორტს განიცდის და ჭამაზე ყურადღებას ვერ ამახვილებს. აუცილებელი არ არის, სკამი ძვირადღირებული ბრენდის იყოს — მთავარია, ერგონომიული და ადვილად გასაწმენდი იყოს (რადგან ძალიან დასვრება!).') WHERE id = '5376c7fc-e6df-4f63-941d-2e00e5209d33';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე დაიწყეთ დამატებითი კვებისთვის საჭირო ნივთების შეძენა? პირველ რიგში, მნიშვნელოვანია ბავშვისთვის სპეციალური კოვზის შერჩევა. ლითონის კოვზმა შეიძლება მისი მგრძნობიარე სასა დააზიანოს, სითბოს სწრაფად გატარების გამო კი ენა დაუწვას. საუკეთესო არჩევანია პატარა ზომის კოვზი რბილი სილიკონის წვერითა და გრძელი ტარით. მოსაზრება — "დიდი კოვზით მივცემ, რომ სწრაფად დანაყრდეს" — მცდარია; რაც უფრო პატარაა კოვზი, მით უფრო მარტივად მოერგება ბავშვის ყლაპვის რეფლექსი. ფერადი კოვზები საკვებისადმი მის ინტერესს გაზრდის.') WHERE id = '1d96ab29-9c6c-4bb8-ba1f-f5f3f11a1dbb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი ღამით უეცრად ტირილით იღვიძებს და ძნელად მშვიდდება? მე-6 თვის მოახლოებისას ღრძილებში წნევა ღამით უფრო მეტად იგრძნობა (რადგან წოლისას თავისკენ სისხლის ნაკადი იმატებს). ნუ გაუბრაზდებით — მას უბრალოდ სტკივა. ძილის წინ ღრძილების სუფთა თითით ან სპეციალური სილიკონის ჯაგრისით მსუბუქი მასაჟი სისხლის მიმოქცევას აუმჯობესებს და დისკომფორტს ამცირებს. მოთმინება გამოიჩინეთ — როდესაც ის პატარა "მარგალიტები" გამოჩნდება, ყველა უძილო ღამე დაგავიწყდებათ.') WHERE id = '4bb38a42-9207-48cc-87a0-6e8506859c1d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნუ დაუჯერებთ უფროსებს, რომლებიც გეუბნებიან: „იატაკი ცივია, ბავშვს გააციებთ“, და ნუ გამოკეტავთ ბავშვს დივანზე ან საწოლში. სუფთა ხალიჩა ან სპეციალური სათამაშო ხალიჩა (ფაზლების ხალიჩა) ბავშვისთვის საუკეთესო სპორტული დარბაზია. თუ სიცივის გეშინიათ, უბრალოდ სათანადოდ ჩააცვით (წინდები ან ბამბის შარვალი). რაც უფრო მეტს იტრიალებს, იხოხებს და იფართხალებს იატაკზე, მით უფრო სწრაფად გაუმაგრდება კუნთები. უმოძრაობა განვითარების შემაფერხებელი ყველაზე დიდი მტერია.') WHERE id = '5ed49a9c-59aa-4f08-b836-cd7056d33992';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვთან ერთად წიგნების კითხვა მანამდე დაიწყეთ, სანამ ის ლაპარაკს ისწავლის. ახლა სწორედ შესაფერისი დროა „შეეხე და შეიგრძენი“ (touch and feel) ან შრიალა წიგნების შესაძენად. ის ეცდება ფურცლების გადაფურცვლას (ამის სწავლა ნატიფი მოტორიკისთვის შესანიშნავი ვარჯიშია), შეეხება სურათებს და შესაძლოა წიგნის ღრღნაც კი დაიწყოს. ეს „წიგნის სიყვარულის“ დასაწყისია. აჩვენეთ ცხოველები და მათი ხმები გამოსცით („როგორ ამბობს ძროხა? მუუუ!“). ეს მარტივი თამაში მის პასიურ ლექსიკას ამდიდრებს.') WHERE id = 'a556f86c-ce31-4428-944f-44af737aa8ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'როდესაც თქვენი ბავშვი დაჯდომას ცდილობს, ხელებს წინ დებს და სამკუთხედის/სამფეხას პოზაში წონასწორობის შენარჩუნებას ცდილობს? ეს შესანიშნავი ნიშანია! თუმცა ჯერ სრულიად დაუზღვევლად ნუ დატოვებთ, რადგან შეიძლება მოულოდნელად უკან ან გვერდზე გადავარდეს. ირგვლივ (ზურგსა და გვერდებზე) ბალიშები დაუწყვეთ და „უსაფრთხოების წრე“ შეუქმენით. თუმცა ბალიშებს შორის ნუ მოამწყვდევთ და ნუ დატოვებთ უმოძრაოდ; მიეცით საშუალება, თავად ისწავლოს სხეულის მართვა და წონასწორობის პოვნა.') WHERE id = '75dd1faa-e49b-4521-a298-8ff13485c3cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'რატომ ვიწყებთ დამატებითი საკვების მიცემას სწორედ 6 თვის ასაკში? მიზეზი მხოლოდ კუჭი კი არა, სისხლიცაა. რკინის მარაგი (ფერიტინი), რომელიც ბავშვმა დედის მუცლად ყოფნისას დააგროვა, დაახლოებით მე-6 თვიდან იწურება, ხოლო დედის რძეში არსებული რკინა მის მზარდ მოთხოვნილებას სრულად ვეღარ აკმაყოფილებს. ამიტომ პირველ საკვებად, ჩვეულებრივ, რკინით მდიდარ პროდუქტებს (ხორცს, რკინით გამდიდრებულ ფაფებს) ირჩევენ. ეს ფიზიოლოგიური აუცილებლობაა და არა მხოლოდ „დანაყრების“ საკითხი.') WHERE id = 'd0ee725f-9b61-4b89-bc59-14a2829f8036';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვების სკამზე „უსაფრთხოების ღვედს“ უყურადღებოდ ნუ დატოვებთ. ფიქრი — „ჩემი ბავშვი ჯერ არ მოძრაობს, სად წავა?“ — ყველაზე დიდი შეცდომაა. ბავშვები შეიძლება ერთ წამში ქვემოთ ჩაცურდნენ ან წამოდგომა სცადონ. ამასთანავე, სკამს ფეხის საყრდენი (footrest) უნდა ჰქონდეს. ბავშვს, რომელსაც ფეხები ჰაერში აქვს, ყლაპვისას შეიძლება გაუჭირდეს (გადაცდენის რისკი იზრდება). როდესაც ფეხები საყრდენს ეყრდნობა, სხეული უფრო სტაბილურია და ყლაპვაც უფრო უსაფრთხოდ მიმდინარეობს.') WHERE id = '625e4f6a-1f8a-44b3-838c-95a927b0b1a5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დედა წავიდა!“ — განშორების შფოთვა (Separation Anxiety) ამ პერიოდში შეიძლება გაძლიერდეს. თუ ოთახიდან გასვლისას ტირის, კარს მიღმაც განაგრძეთ მასთან საუბარი: „აქ ვარ, მესმის შენი, ახლავე მოვალ“. თქვენი ხმა დაამშვიდებს. ასევე, უფრო ხშირად ეთამაშეთ „ჭიტა“ (Pee-ka-boo). ეს თამაში ასწავლის, რომ მაშინაც კი, როდესაც ადამიანები უჩინარდებიან (სახეს იფარებენ), ისინი აუცილებლად ბრუნდებიან. ეს ფსიქოლოგიური ვარჯიშია.') WHERE id = '422035de-73c2-492a-bbec-313984910971';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-6 თვეში ბავშვების მეხსიერება საგრძნობლად ძლიერდება. ის უკვე ცნობს ყოველდღიურ რიტუალებს. მაგალითად, ხვდება, რომ წინსაფრის გაკეთების შემდეგ ჭამა მოუწევს, ხოლო პირსახოცის დანახვისას — ბანაობა. ეს სტაბილურობა მას უსაფრთხოების განცდას უჩენს. ამიტომ ეცადეთ, რიტუალები არ დაარღვიოთ. ესაუბრეთ და ყოველი ნაბიჯი აუხსენით: „ახლა რას გავაკეთებთ?“ თქვენი ხმა და მოქმედებების ასეთი თანმიმდევრულობა მის სამყაროს უფრო უსაფრთხოსა და გასაგებს ხდის.') WHERE id = '024b161c-2539-4cac-976f-5bf08fd88827';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ პირველი კბილები ჯერ არ ამოსულა, ნუ ინერვიულებთ — ზოგ ბავშვს კბილების ამოჭრა 1 წლამდეც უგვიანდება. თუმცა ღრძილები შესაძლოა უკვე შეშუპებული და მტკივნეული იყოს. ბავშვს ძალიან დაამშვიდებს ღრძილების სუფთა, ნოტიო და ცივი დოლბანდით მსუბუქად დამასაჟება. ამ თვეებში ჭარბმა ნერწყვმა გაღიზიანება რომ არ გამოიწვიოს, პირის ირგვლივ კანი მშრალად შეინარჩუნეთ და დამცავი კრემები გამოიყენეთ.') WHERE id = '5905275f-db82-478c-ba85-c28c03e494ac';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამატებითი კვების დაწყების შემდეგ ბავშვის განავლის (საფენის შიგთავსის) ფერი, სუნი და კონსისტენცია მკვეთრად შეიცვლება. ამან არ შეგაშინოთ! ნაწლავები პირველად ცდილობს რძისგან განსხვავებული საკვების მონელებას. ზოგჯერ ბოსტნეული შესაძლოა თითქმის უცვლელი, მოუნელებელი სახით გამოვიდეს — ესეც ნორმალურია. მთავარია, ბავშვს არ ჰქონდეს მუცლის ძლიერი ტკივილი ან შეკრულობა. თუ ასეთი რამ მოხდება, რამდენიმე დღით შეწყვიტეთ იმ საკვების მიცემა და უპირატესობა რძეს მიანიჭეთ.') WHERE id = '2175d91f-594f-42b1-b5ca-5375fe51dcff';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დააკვირდით ბავშვის „ნატიფ მოტორიკას“: ის უკვე ცდილობს, საგნები არა მთელი ხელისგულით, არამედ თითებით დაიჭიროს, თუმცა ჯერ სრულყოფილი „პინცეტური“ მოჭიდება არ აქვს. მიეცით უსაფრთხო, სხვადასხვა ფორმის სათამაშოები. ამ პერიოდში რეზინის, ქსოვილისა და ხის მასალებს შორის განსხვავების შეგრძნება მისი სენსორული განვითარებისთვის ძალიან მნიშვნელოვანია. გახსოვდეთ, ის ჯერ კიდევ ყველაფერს „პირით ამოწმებს“, ამიტომ ყურადღება მიაქციეთ სათამაშოების სისუფთავეს და დარწმუნდით, რომ მათ მცირე ზომის ნაწილები არ აქვს.') WHERE id = 'ad5ab394-baf9-4d75-b342-9b228c2343bc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ხვალ თქვენს ბავშვს ზუსტად ნახევარი წელი (6 თვე) უსრულდება! დღეს კიდევ ერთხელ შეამოწმეთ ყველაფერი, რაც დამატებითი კვებისთვის დაგჭირდებათ: ორთქლსახარში, ბლენდერი ან უბრალოდ საწური და პლასტმასის ჭურჭელი. თუმცა ყველაზე მნიშვნელოვანი ფსიქოლოგიური მზადყოფნაა. ბავშვმა შესაძლოა პირველი კოვზი გადმოაფურთხოს, სახე და ტანსაცმელი მოისვაროს ან საერთოდ არ მოისურვოს ჭამა. ნუ გაღიზიანდებით და ნუ დააძალებთ. პირველი თვის მიზანი ბავშვის დანაყრება კი არა, გემოების გაცნობაა. თქვენი მოთმინება ამ პროცესის უმთავრესი ინგრედიენტია.') WHERE id = '99a11b8e-07bd-49f3-b3dd-d51a0720e2b5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, შესანიშნავო დედა! დღეს თქვენს ბავშვს 6 თვე შეუსრულდა! თქვენ უკვე წარმატებით გაიარეთ გზის ნახევარი — მისი პირველი წლის ნახევარი. ბავშვის წონა დაბადების შემდეგ დაახლოებით გაორმაგდა და ის სრულად შეეგუა გარესამყაროს. დღეს მასთან ერთად პირველი ოფიციალური „საკვების დღესასწაული“ აღნიშნეთ. რამდენიმე კოვზი პიურეთი დაწყებული ეს თავგადასავალი მისი ზრდის ახალი ეტაპია. იამაყეთ საკუთარი თავით — უძილო ღამეებისა და დაუღალავი შრომის შედეგს დღეს მის ტკბილ ღიმილში დაინახავთ, როცა ის შემოგხედავთ!') WHERE id = '6314b77b-4ba8-4969-86b0-43b2ae2976dd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამატებითი კვების დაწყებისას წყლის მიცემაც მნიშვნელოვანი გახდება. ბავშვი უკვე ახლავე გააცანით „წყლის ჭიქას“ (Sippy cup-ს ან ჩვეულებრივ პატარა ჭიქას). ჩაასხით ძალიან ცოტა წყალი (ერთი ყლუპი) ან ცარიელი მიეცით. მიეცით საშუალება, ისწავლოს ჭიქის დაჭერა, პირთან მიტანა და „დახრილი“ კუთხით დაჭერა (თავის უკან გადაწევა). საწოვარიანი ბოთლისგან განსხვავებით, ჭიქიდან დალევა პირისა და ენის სრულიად განსხვავებულ კოორდინაციას მოითხოვს.') WHERE id = '276120aa-1546-4b32-a95c-f7c80f3724d7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გჯერათ? ნახევარ წლამდე (6 თვემდე) სულ რაღაც 10 დღე დარჩა! ეს მნიშვნელოვანი ეტაპია. თქვენი ბავშვი უკვე თითქმის მზადაა, „დიდი ბავშვი“ გახდეს. ამ დღეებში გადაუღეთ ფოტოები და ვიდეოები. შეადარეთ პირველი თვეების მოკუნტული, მშვიდი ბავშვი ახლანდელ აქტიურ მკვლევარს. თქვენ მას არა მხოლოდ რძე, არამედ ნდობა, სიყვარული და გამბედაობაც მიეცით. დატკბით ამ ბოლო 10 დღით, რადგან წინ „დალაქავებული წინსაფრებისა“ და „კოვზებით ომების“ პერიოდი გელით!') WHERE id = 'eeef4f12-67b6-4638-9c3f-cfa2a5c6b644';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-6 თვის ბოლო ათდღეულში! დამატებითი კვებისთვის სამზარეულოში მზადება უკვე პიკს აღწევს. დასაწყისისთვის ბოსტნეულის პიურე (მაგალითად, ყაბაყის ან ყვავილოვანი კომბოსტოს) ან ბრინჯის/წიწიბურას ფაფა, როგორც წესი, ყველაზე უსაფრთხო არჩევანია. მნიშვნელოვანი წესი: თითოეული ახალი საკვები ცალ-ცალკე მიეცით და 3-დღიანი მოცდის წესი დაიცავით. მხოლოდ ასე შეძლებთ გაიგოთ, აქვს თუ არა ბავშვს ამ საკვებზე ალერგია. ნუ იჩქარებთ — პირველ დღეებში მიზანი ბავშვის დანაყრება კი არა, მხოლოდ ახალი გემოების გაცნობაა.') WHERE id = 'f895f071-f97f-4fb0-9772-e32eeffab324';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე სულ უფრო უახლოვდება დამოუკიდებლად, საყრდენის გარეშე ჯდომას. როდესაც იატაკზე დასვამთ, შესაძლოა შეამჩნიოთ, რომ წონასწორობის შესანარჩუნებლად ხელებით გვერდებზე ეყრდნობა. ამ პერიოდში მნიშვნელოვანია, მის გარშემო რბილი საფენები ან ბალიშები დააწყოთ, რადგან ერთი წამით უყურადღებობისას შეიძლება უკან ტომარასავით გადაყირავდეს. თუმცა ბალიშებში ნუ „ჩაფლავთ“ — მიეცით საშუალება, საკუთარი კუნთებით წონასწორობის შენარჩუნებაში ივარჯიშოს. რაც უფრო მეტად ამუშავებს ზურგისა და მუცლის კუნთებს, მით უფრო მალე შეძლებს გამართულად ჯდომას.') WHERE id = '5a9ac2d0-eaf0-4588-afbc-9d21af03e70a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამატებით კვებაზე გადასვლის პერიოდში „გადაცდენის“ შიში ყველა დედის კოშმარია. უნდა იცოდეთ, რომ ბავშვებში „Gag reflex“ (პირღებინების რეფლექსი) ენის უფრო წინა ნაწილშია; ანუ, თუ ბავშვს გული ერევა, ეს იმას კი არ ნიშნავს, რომ იხრჩობა, არამედ იმას, რომ საკვებს უკან გამოდევნის. სასუნთქ გზებში საკვების რეალურად გაჭედვისას ბავშვი ხმას ვერ გამოსცემს და ფერი ეცვლება. პირღებინების რეფლექსის დროს კი ახველებს და საკვებს პირიდან აგდებს. ამ რეფლექსის ამოცნობა დაგამშვიდებთ და ბავშვს ჭამის სწავლისას მეტ გამბედაობას შემატებს.') WHERE id = '70a66a9a-563a-4960-829c-3c543e77de0b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ბავშვს უკვე სრულიად თავისუფლად გადააქვს საგნები ერთი ხელიდან მეორეში. ეს თავის ტვინის ნახევარსფეროების კოორდინირებულ მუშაობაზე მიუთითებს. ეთამაშეთ თამაშები, რომლებიც ამ უნარს ავითარებს: მიეცით ერთი სათამაშო, ხოლო მას შემდეგ, რაც დაიჭერს, მეორე ხელთან კიდევ ერთი სათამაშო მიუტანეთ. ვნახოთ, პირველს დააგდებს თუ მეორე ხელში გადაიტანს? ეს მარტივი თამაში აძლიერებს როგორც ნატიფ მოტორიკას, ისე პრობლემების გადაჭრის უნარს.') WHERE id = 'ae843217-76c1-4871-8e0d-ffc6c753bdec';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-7 თვეში! დამატებითი კვების თავგადასავალი უკვე ოფიციალურად დაიწყო. თუ პირველ დღეებში შეამჩნევთ, რომ ბავშვი საკვებს ენით უკან უბიძგებს, არ ინერვიულოთ — ეს ბუნებრივი რეაქციაა, რომელიც თვეების განმავლობაში ჩამოყალიბებული წოვის რეფლექსითაა გამოწვეული. უბრალოდ შესთავაზეთ 1-2 ჩაის კოვზი პიურე და ნუ დააძალებთ. ამ ეტაპზე ჩვენი მიზანი ბავშვის დანაყრება კი არა, მისი სხვადასხვა გემოსა და ტექსტურისთვის გაცნობაა. დედის რძე ან ხელოვნური ნარევი ჯერ კიდევ მისი ენერგიის ძირითადი წყაროა.') WHERE id = '359c78b7-5eb4-4ddd-8230-6dac6d1fbced';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'პირველი ბოსტნეულის გასინჯვის შემდეგ ბავშვის განავლის ფერისა და სუნის შეცვლა სრულიად ნორმალურია. თუ საფენში პიურეს ნაწილაკებს თითქმის უცვლელი, მოუნელებელი სახით დაინახავთ, ნუ შეშინდებით — ბავშვის საჭმლის მომნელებელი სისტემა ახალ საკვებთან შეგუებას ცდილობს. მთავარი, რასაც ყურადღება უნდა მიაქციოთ, არის კანზე უეცარი სიწითლის, გამონაყარის ან მუცლის ძლიერი შებერილობის არსებობა. თუ ეს ნიშნები არ აღინიშნება, ყველაფერი რიგზეა!') WHERE id = 'e2b1e9c6-06ca-442f-a823-59969208dc77';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამატებითი კვების დაწყების დღიდანვე დაიწყეთ ბავშვისთვის წყლის შეთავაზება. ბავშვს ჯერ ყოველდღიურად ბევრი წყალი არ სჭირდება, თუმცა ჭამის შემდეგ რამდენიმე ყლუპის დალევა პირის ღრუსაც წმენდს და სამომავლო ჩვევასაც აყალიბებს. ეცადეთ, წყალი საწოვარიანი ბოთლით კი არა, პატარა ჭიქით ან სპეციალური საწრუპიანი ჭიქით (sipper cup) მისცეთ. ეს მისი ქვედა ყბის კუნთების განსხვავებულად განვითარებას შეუწყობს ხელს.') WHERE id = '0368b56f-7108-4cef-9b22-96d46e080b4f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'იცავთ 3-დღიანი მოცდის წესს? თითოეული ახალი ბოსტნეული ან ხილი ცალ-ცალკე მიეცით, რათა ორგანიზმის რეაქციას დააკვირდეთ. მაგალითად, თუ დღეს გოგრის პიურეს სთავაზობთ, მომდევნო 2 დღის განმავლობაში სხვა ახალი პროდუქტი არ დაამატოთ. თუ ალერგია გამოვლინდება, ეს მისი გამომწვევის დაუყოვნებლივ პოვნაში დაგეხმარებათ. მოთმინება გამოიჩინეთ — ბავშვის გემოვნების რეცეპტორები ახლა პატარა ლაბორატორიასავით მუშაობს!') WHERE id = '6a73b0da-2d2c-48e8-a871-941a5e9014db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი ჭამის დროს ცდილობს, კოვზი გამოგართვათ ან პიურეში ხელები ჩაყოს? ხელს ნუ შეუშლით! ბავშვები საკვებს მხოლოდ გემოთი კი არა, შეხებითაც ეცნობიან. გარშემო ცოტა არეულობა ნორმალურია — ეს „დასვრაც“ კი მნიშვნელოვანია მისი სენსორული განვითარებისა და დამოუკიდებლად ჭამის ჩვევის ჩამოსაყალიბებლად. მიეცით საშუალება, საკვების ტექსტურა შეიგრძნოს — ეს მომავალში „საკვების არჩევითობის“ პრობლემის თავიდან აცილების ერთ-ერთი საუკეთესო გზაა.') WHERE id = '81644d16-8ba2-4b27-83e5-5d3f50deae69';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამატებითი კვების პერიოდში შესაძლოა შეკრულობა გამოვლინდეს. ბავშვის ნაწლავები რძისგან განსხვავებული საკვების გადამუშავებას ეჩვევა. თუ ბავშვი ძლიერ იჭინთება და განავალი ძალიან მაგარია, შესაძლოა სასარგებლო იყოს პიურეში ცოტაოდენი ზეითუნის ზეთის დამატება ან ქლიავის პიურეს მიცემა. ნუ დაგავიწყდებათ საკმარისი წყლის შეთავაზება. თუ პრობლემა დიდხანს გაგრძელდება, აუცილებლად მიმართეთ პედიატრს, თუმცა პირველ დღეებში ამგვარი ცვლილებები მოსალოდნელია.') WHERE id = '467b7c20-7f80-4ea7-b9c0-93bd0e277a7e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '6 თვის შემდეგ ბავშვის მეხსიერება და ყურადღება მნიშვნელოვნად უმჯობესდება. ის უკვე იწყებს საგნების სახელებთან დაკავშირებას. მაგალითად, თუ ჰკითხავთ: „ბურთი სად არის?“, თვალებით დაიწყებს მის ძებნას. ეთამაშეთ ასეთი კითხვა-პასუხის თამაშები. თქვენ მისთვის „ბგერების ბიბლიოთეკაც“ ხართ. რაც უფრო მეტ სიტყვას გაიგონებს, მით უფრო სწრაფად გამდიდრდება მის ტვინში სიტყვათა მარაგი. მოუსმინეთ, როგორც დიდ ადამიანს და მის თითოეულ ბგერას აზრიანი პასუხი გაეცით.') WHERE id = '5b5665e4-15b0-42d4-8279-20912bd71937';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე უფრო თავდაჯერებულად ცდილობს დაუხმარებლად ჯდომას? თეძოსა და წელის კუნთების გასაძლიერებლად „იატაკზე გატარებული დრო“ საუკეთესო ვარჯიშია. როცა მუცელზე დააწვენთ, მის წინ, შედარებით მოშორებით, საინტერესო სათამაშო დადეთ. სათამაშოს მისაწვდომად ის შეეცდება ტანის შემობრუნებას და შესაძლოა, ხოხვასაც. ეს მოძრაობები სხეულის კოორდინაციისთვის გადამწყვეტია. გახსოვდეთ, ყოველი წაქცევა სწავლის გამოცდილებაა — უბრალოდ დარწმუნდით, რომ გარემო უსაფრთხოა.') WHERE id = '85f7b4d5-b074-40cb-b8e7-126bfcb368b7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ბავშვმა ღამით კვლავ უფრო ხშირად დაიწყო გაღვიძება, ეს შეიძლება კბილების ამოჭრას ან გაზრდილ ფიზიკურ აქტივობას უკავშირდებოდეს. ბავშვი დღისით ნასწავლ მოძრაობებს (მაგალითად, გადაბრუნებას ან ხოხვას) ძილშიც კი „იმეორებს“. თუ არ ტირის, მაშინვე ხელში აყვანას ნუ იჩქარებთ; აცადეთ, თავად დამშვიდდეს და კვლავ დაძინება სცადოს. შესაძლოა, საკმარისი იყოს, უბრალოდ აგრძნობინოთ, რომ მის გვერდით ხართ (ხელი ზურგზე დაადოთ).') WHERE id = 'aa9eef25-9e2b-4d46-bc09-aebaa1272eaa';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე ოფიციალურად მე-7 თვეში ხართ! ბავშვის წონა დაბადების წონასთან შედარებით დაახლოებით გაორმაგებული უნდა იყოს (ეს საშუალო მაჩვენებელია). თუ კბილები ჯერ არ გამოჩენილა, ნუ შეშინდებით — თუ ძვლების განვითარება ნორმალურად მიმდინარეობს, კბილებმა ნებისმიერ დროს შეიძლება „მოგესალმონ“. სცადეთ, დღეს მისთვის მომზადებულ ბოსტნეულის პიურეს ძალიან მცირე რაოდენობით (რამდენიმე წვეთი) მაღალი ხარისხის ცივად დაწურული ზეითუნის ზეთი დაუმატოთ; ეს მონელებასაც შეუწყობს ხელს და მის ტვინსაც სასარგებლო ცხიმოვანი მჟავებით მოამარაგებს.') WHERE id = 'd3b9ca7e-7233-4280-976e-e11828d20cca';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ბოსტნეულს უკვე დაუმეგობრდით, შეგვიძლია ნელ-ნელა ცილების სამყაროში გადავინაცვლოთ. ხორცთან პირველი გაცნობისთვის საუკეთესო არჩევანია უცხიმო ხბოს, ინდაურის ან კურდღლის ხორცი. ხორცი ძალიან კარგად მოხარშეთ, სრულად დააბლენდერეთ პიურეს კონსისტენციამდე და ბოსტნეულის პიურეს დაუმატეთ. ხორცი ბავშვის სწრაფად კლებადი რკინის მარაგის შესავსებად ერთ-ერთი ყველაზე მნიშვნელოვანი საკვებია. პირველ დღეებში მხოლოდ ერთი ჩაის კოვზი ხორცის პიურეც საკმარისია.') WHERE id = 'd543dbe5-6df1-4d22-a7ce-cbb22da34fc3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ბავშვს უკვე შეუძლია სათამაშოს ერთი ხელიდან მეორეში გადატანა და ორივე ხელით ერთდროულად მოქმედება? ეს თავის ტვინის ნახევარსფეროების კოორდინირებული განვითარების ნიშანია. ეთამაშეთ „დაიჭირე-გაუშვი“. მაგალითად, ერთ ხელში სათამაშო მიეცით, შემდეგ კი იმავე ხელთან მეორე სათამაშო მიუტანეთ; ვნახოთ, გადაიტანს თუ არა პირველს მეორე ხელში და აიღებს თუ არა ახალს? ეს მარტივი ვარჯიში აუმჯობესებს როგორც მის ნატიფ მოტორიკას, ისე პრობლემის გადაჭრის უნარს.') WHERE id = 'a8158232-7247-4508-af89-b5e8c2455782';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვერცხის გულის გასინჯვის დროა! კვერცხი მაგრად მოხარშეთ და მისი გულიდან მხოლოდ მუხუდოს მარცვლისოდენა ნაწილი დედის რძეს ან პიურეს შეურიეთ და ბავშვს მიეცით. კვერცხის გული მდიდარია ტვინის განვითარებისთვის მნიშვნელოვანი ქოლინითა და ცხიმოვანი მჟავებით. ფრთხილად იყავით: კვერცხის ცილა (პროტეინი) ძლიერი ალერგენია, ამიტომ 1 წლამდე არ არის რეკომენდებული. ყოველ ჯერზე ოდნავ გაზარდეთ კვერცხის გულის რაოდენობა და ბავშვის რეაქციას დააკვირდით.') WHERE id = '348776a6-90b7-44de-bed5-439f8ce3ea57';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი ხოხვისთვის „საწყის“ პოზიციას იღებს? ის შეიძლება ხელებსა და მუხლებზე დადგეს და წინ და უკან ირწეოდეს. ამგვარი „რწევით“ ის წონასწორობის შეგრძნებასა და კუნთების ძალას ამოწმებს. როცა ამას დაინახავთ, შეაქეთ და გაამხნევეთ. ხოხვის დაწყება რომ გაუადვილდეს, დარწმუნდით, რომ იატაკი სრიალა არ არის (ხალიჩა ან რბილი ხალიჩა იდეალურია). სულ მალე ის სახლის ყველა კუთხეს მისწვდება!') WHERE id = '075eebcf-bf5d-40ba-b7ae-a5f38e71818b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამატებითი კვების პერიოდში წყლის სმა უკვე არჩევანი კი არა, აუცილებლობაა. ახალი საკვების გადამუშავებისას ბავშვის თირკმელებს მეტი წყალი სჭირდება. თუ თქვენი ბავშვი წყალზე უარს ამბობს, მისი დაინტერესება სხვადასხვა საწრუპიანი ან პატარა ფერადი ჭიქით სცადეთ. წყალი ჭამისთანავე და დღის განმავლობაში ხშირად შესთავაზეთ. გახსოვდეთ, წვენები და კომპოტები წყალს ვერ ჩაანაცვლებს; სუფთა წყალი ყველაზე ჯანსაღი არჩევანია.') WHERE id = '5ed536ec-a0b5-4447-9d9a-377e3e5da4a3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„განშორების შფოთვა“ (სეპარაციული შფოთვა) ამ დღეებში შეიძლება უფრო მკვეთრად გამოვლინდეს. თუ ოთახიდან გასვლისთანავე ბავშვი ტირილს იწყებს, ეს მის „ცუდ ხასიათს“ კი არ ნიშნავს, არამედ თქვენი დაკარგვის შიშს. ოთახიდან გასვლისას აუცილებლად უთხარით: „დედა სამზარეულოშია და ახლავე მოვა“. შორიდან თქვენი ხმის გაგონება მას უსაფრთხოების განცდას უჩენს. „ჭიტას“ თამაში უფრო რთული ფორმებით ითამაშეთ; დაიმალეთ და სხვა ადგილიდან გამოჩნდით — ეს მას ამ შიშის დაძლევაში დაეხმარება.') WHERE id = '9d97a34c-0a55-4e17-9a40-0912d5c81137';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ბავშვის კანზე, განსაკუთრებით პირის გარშემო ან სხეულზე, უეცარ სიწითლეს შენიშნავთ, გაიხსენეთ ახალი საკვები, რომელიც მას ბოლო 3 დღის განმავლობაში მიეცით. თუ ალერგიულ რეაქციაზე ეჭვი გაქვთ, დაუყოვნებლივ შეწყვიტეთ ამ საკვების მიცემა და 1-2 კვირის შემდეგ კვლავ სცადეთ (მცირე რაოდენობით). ზოგჯერ ორგანიზმი მხოლოდ საკვების ტექსტურაზე რეაგირებს, ზოგჯერ კი ეს ნამდვილი ალერგიაა. საეჭვო შემთხვევებში უმჯობესია პედიატრს მიმართოთ.') WHERE id = 'c73b10f1-26e8-49f8-a842-9fc9eb05c61a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კიდევ ერთხელ შეამოწმეთ სახლის უსაფრთხოება. ბავშვი უკვე ნივთებისკენ იწევს, ქაჩავს მათ და გემოს უსინჯავს. ელექტროროზეტებზე დამცავები დააყენეთ, ხოლო ბასრი კუთხეები დაარბილეთ. რაც მთავარია, იატაკზე ან ხალიჩაზე არცერთი პატარა ნივთი (ღილი, მძივი, ელემენტი) არ უნდა დარჩეს. ბავშვის მხედველობა იმდენად მახვილია, რომ შეუძლია თქვენთვის შეუმჩნეველი პატარა ძაფიც კი იპოვოს და პირში ჩაიდოს.') WHERE id = 'cb68fae9-cc1f-40fd-8358-d8d8262537c7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილი შესაძლოა კვლავ დაერღვეს. ამის მიზეზი ხშირად „მოტორული განვითარებაა“. ბავშვს სურს, დღის განმავლობაში ნასწავლი მოძრაობები (მაგალითად, მუხლებზე დადგომა) ძილშიც კი გაიმეოროს. თუ ღამით ძილში მუხლებზე დგება და ირწევა, მაშინვე ნუ აიყვანთ ხელში. მშვიდად დააწვინეთ და ზურგზე მოეფერეთ. მიეცით შესაძლებლობა, თავად დამშვიდება ისწავლოს.') WHERE id = 'e9e1b950-57d8-4d65-82e5-7c7681ec6159';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! თქვენი ბავშვი უკვე 200 დღისაა! ეს ნამდვილად მნიშვნელოვანი რიცხვია. თქვენ უკვე „ახალბედა დედა“ კი არა, საკმაოდ გამოცდილი მშობელი ხართ. როდესაც ბავშვი გიყურებთ და გიღიმით ან თქვენს ჩახუტებას ცდილობს, გრძნობთ, რომ მთელი თქვენი შრომა ამად ღირდა. დღეს მისთვის განსაკუთრებული „გემოების ფესტივალი“ მოაწყვეთ — საყვარელი ბოსტნეულისა და ხორცის ნარევით გემრიელი პიურე მოუმზადეთ. თქვენ საოცარი ხართ, დედა!') WHERE id = '8ef38899-1def-4d57-bd7d-f28245d50ca5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '200-დღიანი მნიშვნელოვანი ეტაპი უკვე გადავლახეთ, ახლა კი მენიუ ოდნავ უფრო მრავალფეროვანი გავხადოთ! თუ ბავშვი უკვე მიეჩვია ბოსტნეულისა და ხორცის პიურეებს, რაციონში ხილის დამატების დროა. თავდაპირველად ვაშლით, მსხლით ან ბანანით დაიწყეთ. ხილის ორთქლზე მომზადება და პიურედ ქცევა (ან მინის სახეხზე გახეხვა) მონელებას ამარტივებს. ყურადღებით იყავით: ხილის ტკბილი გემო ბავშვისთვის შესაძლოა ძალიან მიმზიდველი აღმოჩნდეს, ამიტომ, ბოსტნეული რომ არ დაივიწყოს, უმჯობესია ხილი, როგორც წესი, დღის მეორე ნახევარში, დესერტის სახით შესთავაზოთ.') WHERE id = '52048f39-dc3c-4433-994b-496425ac059d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ჯდომის უნარი უკვე „სამფეხას“ პოზიციიდან (ხელებით იატაკზე დაყრდნობა) უფრო გამართულ და დამოუკიდებელ ჯდომაში უნდა გადადიოდეს. მას უკვე შეუძლია ხელები იატაკს მოაშოროს და სათამაშოთი ითამაშოს. თუ ჯერ კიდევ ხშირად გვერდზე ეცემა, ნუ შეშფოთდებით; ზურგის კუნთების გასაძლიერებლად მიეცით შესაძლებლობა, მეტი დრო გაატაროს იატაკზე. ზურგს უკან რბილი ბალიშები დაუდეთ, თუმცა საშუალება მიეცით, წონასწორობა თავად იპოვოს. დამოუკიდებლად ჯდომა მისთვის სამყაროს სრულიად განსხვავებული კუთხით დანახვას ნიშნავს.') WHERE id = '9d5fc99c-ca1a-4324-a7ea-7d36c4768a6e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'რძის პროდუქტების გაცნობის დროა! თუ ექიმს საწინააღმდეგო ჩვენება არ მიუცია, შეგიძლიათ ბავშვს სახლში მომზადებული ნატურალური იოგურტი ან ხაჭო შესთავაზოთ. იოგურტი არა მხოლოდ კალციუმითაა მდიდარი, არამედ ნაწლავის მიკროფლორისთვის სასარგებლო პრობიოტიკებსაც შეიცავს. პირველად მიცემისას მხოლოდ ერთი ჩაის კოვზით დაიწყეთ და კანის რეაქციას დააკვირდით. გახსოვდეთ: მოერიდეთ მაღაზიებში გაყიდულ ხილისა და შაქრის შემცველ „საბავშვო იოგურტებს“ — ყველაზე ჯანსაღი თქვენ მიერ სახლში მომზადებული უბრალო იოგურტია.') WHERE id = '8027ff1e-e9f7-4f2e-9aa6-3293659f2fb7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ბავშვს უკვე სიამოვნებს საგნების ერთმანეთზე დარტყმით ხმის გამოცემა? ამგვარად ის სიღრმისეულად შეისწავლის „მიზეზ-შედეგობრივ“ კავშირს: „თუ ამ ორ სათამაშოს ერთმანეთს დავარტყამ (მიზეზი), ხმა წარმოიქმნება (შედეგი)“. მიეცით სხვადასხვა მასალისგან (ხის, პლასტმასის, ქსოვილის) დამზადებული სათამაშოები, რათა ბგერებსა და შეხებებს შორის განსხვავება შეიგრძნოს. ეს მარტივი თამაში ბავშვს როგორც სმენით აღქმას, ისე მოტორულ უნარებს უვითარებს. სამზარეულოში არსებული პლასტმასის ჭურჭელი და ხის კოვზები ზოგჯერ ყველაზე ძვირად ღირებულ სათამაშოზეც კი უფრო საინტერესო შეიძლება აღმოჩნდეს!') WHERE id = '580f2e78-b4ac-4e71-a08f-98de51b2b255';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მა-მა“, „ბა-ბა“, „და-და“ — ასეთი მარცვლების გამეორება უკვე უფრო რიტმული და უწყვეტი ხდება (რედუპლიკაციური ტიტინი). ბავშვი უკვე ცდილობს, თქვენს ინტონაციას მიბაძოს. როცა ესაუბრებით, ისიც „გპასუხობთ“. გაახანგრძლივეთ ეს დიალოგები! როდესაც ხმებს გამოსცემს, ყურადღებით მოუსმინეთ, შემდეგ კი უპასუხეთ: „ჰო, მართლა? მერე რა მოხდა?“ ეს მას ურთიერთობის სურვილს გაუძლიერებს და მეტყველების ცენტრს გაუაქტიურებს. თქვენ მისი საუკეთესო მოსაუბრე ხართ.') WHERE id = 'cfd5a392-f80a-4d2d-a1a6-3083e4ec4e6d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამატებითი კვების რაციონში უფრო აქტიურად ჩართეთ მარცვლეული (ფაფები). თუ ჯერ არ დაგიწყიათ, ბრინჯის, წიწიბურასა და სიმინდის ფქვილის ფაფები საუკეთესო არჩევანია დასაწყებად, რადგან გლუტენს არ შეიცავს. ფაფა ძალიან სქელი არ მოამზადოთ — თავდაპირველად დედის რძით ან ხელოვნური ნარევით გაათხელეთ. მარცვლეული ბავშვს ხანგრძლივი დროით ენერგიით ამარაგებს და შეიძლება ღამის ძილიც უფრო უწყვეტი გახადოს (რა თქმა უნდა, თუ გაღვიძების მიზეზი შიმშილია).') WHERE id = 'a9b193a4-5558-4e20-a84e-1718f45d9ce1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე იწყებს ნივთების არა მთელი ხელისგულით, არამედ თითებით აღებას („პინცეტური მოჭიდებისთვის“ მზადება)? ეს მისი ნატიფი მოტორიკის განვითარებაში დიდი ნახტომია. მიეცით უსაფრთხო სათამაშოები, რომლებიც საკმარისად დიდია და თან თითებით მოჭიდებასაც შეძლებს. ყურადღებით იყავით: ეს უნარი იმასაც ნიშნავს, რომ ბავშვს შეუძლია იატაკზე დანახული უმცირესი ძაფი ან მტვრის ნაწილაკიც კი აიღოს და პირში ჩაიდოს. სახლის სისუფთავე და იატაკზე წვრილი ნივთების არქონა ახლა უფრო მნიშვნელოვანია, ვიდრე ოდესმე.') WHERE id = 'f62f3f3e-4b0d-4001-8523-9219c3da8c5d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'იწყება „დამოუკიდებლობის“ პერიოდი! ჭამის დროს მიეცით საშუალება, საკუთარი კოვზი დაიჭიროს. დიახ, ყველაფერი დაისვრება, პიურე ბავშვის თმასა და თქვენს სახეზეც აღმოჩნდება, მაგრამ ეს დამოუკიდებლად ჭამის უნარის განვითარებისთვის ფასდაუდებელია. ერთი კოვზი მას ეჭიროს, მეორე კოვზით კი თქვენ აჭამეთ. ასე იგრძნობს, რომ კვების პროცესის აქტიური მონაწილეა. ეს მომავალში „ჭამა არ მინდა“ ჭირვეულობის თავიდან აცილების ერთ-ერთი საუკეთესო გზაა.') WHERE id = '60871d42-5c1c-446f-a627-a65d4f2f7fcb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ კბილების ამოჭრის პროცესი ჯერ კიდევ გრძელდება, ბავშვს შეიძლება მადა შეუმცირდეს. მტკივნეული ღრძილებით მაგარი ან ცხელი საკვების ჭამა მისთვის უსიამოვნო შეიძლება იყოს. ასეთ დღეებში ნუ აიძულებთ ჭამას, უფრო ხშირად მიეცით დედის რძე ან შესთავაზეთ ოთახის ტემპერატურაზე ოდნავ გრილი საკვები. გრილმა ხილის პიურემ შესაძლოა ღრძილები დაუმშვიდოს. მოთმინება გამოიჩინეთ — ეს დისკომფორტი დროებითია. მთავარია, ბავშვს საკვების მიმართ უარყოფითი ემოცია არ ჩამოუყალიბდეს.') WHERE id = 'd3067cbe-ce54-41b6-9dd3-9072dfcf2c69';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, მე-7 თვის ბოლოს მიაღწიეთ! თქვენი ბავშვი უკვე კარგად ცნობს საკუთარ სახელს და დაძახებისას თქვენკენ ბრუნდება. ის ემოციებსაც უფრო მკაფიოდ გამოხატავს: როცა უხარია, ყვირის, ხოლო როცა სათამაშოს ართმევენ, უკმაყოფილებას გამოხატავს. ასე ყალიბდება მისი პიროვნება. დღეს მასთან ერთად იატაკზე წამოწექით და უბრალოდ ითამაშეთ — ის თქვენს ყურადღებას ყველაფერზე მეტად აფასებს. თქვენ საოცარი გზა გამოიარეთ, დედა!') WHERE id = 'bd6cd20e-2a94-483e-b4a1-ed0a0a344bf5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-8 თვეში! ამ თვეში ბავშვი „დამოუკიდებელი მკვლევარის“ სტატუსს იძენს. მას უკვე შეუძლია ოთხზე ცოცვით ოთახის ერთი კუთხიდან მეორემდე სწრაფად გადაადგილება. თუ თქვენი ბავშვი ჯერ არ ცოცავს, ნუ ინერვიულებთ; ზოგი ბავშვი ცოცვის ეტაპს გამოტოვებს და პირდაპირ წამოდგომასა და სიარულზე გადადის. წასახალისებლად საყვარელი სათამაშო ოდნავ მოშორებით დაუდეთ და მიეცით საშუალება, მისწვდეს. მისი ყოველი პატარა წინსვლა დიდი გამარჯვებაა!') WHERE id = 'ecb494cd-7c29-44d1-ad94-78d5bacf0eb8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე დროა, პიურეების ტექსტურა თანდათან შეცვალოთ. საკვების ბლენდერში გატარების ნაცვლად, ჩანგლით დაჭყლეტა დაიწყეთ. კბილები ჯერ რომც არ ჰქონდეს, ბავშვმა რბილი ნაჭრების ღრძილებით დაჭყლეტა უნდა ისწავლოს. ეს საღეჭ კუნთებს ავითარებს და მომავალში მეტყველების უნარზეც დადებითად მოქმედებს. თავდაპირველად შეიძლება პირღებინების რეფლექსი (gag reflex) გამოვლინდეს, რაც ნორმალურია; უბრალოდ მის გვერდით იყავით და გაამხნევეთ.') WHERE id = '2727a145-103d-40b1-93bd-853efdc6e639';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ცდილობს თქვენი ბავშვი ავეჯზე დაყრდნობით წამოდგომას? დივნის კიდეები, სკამები და თქვენი ფეხებიც კი მისთვის საყრდენია. ამ პერიოდში ყურადღება მიაქციეთ სახლში არსებული ავეჯის მდგრადობას. მსუბუქი სკამები ან კუთხის ავეჯი შეიძლება გადაყირავდეს. სწორედ ახლაა დრო, ავეჯის ბასრ კუთხეებზე სპეციალური რბილი დამცავები დაამაგროთ, რადგან წამოდგომის მცდელობები ხშირად მცირე დაცემებით სრულდება.') WHERE id = '2b052f0a-26d0-4470-a503-c5a76302b58f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიქრობთ მენიუში თევზის დამატებაზე? თუ ოჯახში თევზზე მძიმე ალერგიის შემთხვევები არ ყოფილა, თეთრხორციანი თევზი (მაგალითად, ზღვის ქორჭილა ან სხვა უფხო თეთრი თევზი) ომეგა-3-ის შესანიშნავი წყაროა. თევზი ორთქლზე მოამზადეთ და ხელით საგულდაგულოდ შეამოწმეთ, რომ მასში უმცირესი ფხაც კი არ დარჩეს. თევზი ძალიან სასარგებლოა ტვინის განვითარებისა და მხედველობისთვის. შეგიძლიათ კვირაში ერთხელ მცირე ულუფით დაიწყოთ.') WHERE id = '1d9818aa-0e5b-4ba9-aefe-a8e9678137db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„არა“ სიტყვასთან გაცნობა! ბავშვს უკვე ესმის თქვენი ხმის ტონის ცვლილება. როდესაც რაიმე სახიფათოსკენ ხელს გაიწვდის და თქვენ მკაცრი ტონით ეტყვით „არა“ ან „არ შეიძლება“, შესაძლოა გაჩერდეს და შემოგხედოთ. თუმცა ამ სიტყვებს ძალიან ხშირად ნუ გამოიყენებთ, თორემ ეფექტს დაკარგავს. გამოიყენეთ მხოლოდ რეალური საფრთხის დროს (მაგალითად, როდესაც ელექტროროზეტას ეხება). სხვა შემთხვევებში უფრო ეფექტურია, მისი ყურადღება სხვა საინტერესო სათამაშოზე გადაიტანოთ.') WHERE id = 'f3741479-5e2c-4a17-a78f-8627ec0b11aa';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის „პინცეტისებური მოჭიდება“ (pincer grasp) კიდევ უფრო იხვეწება. მას უკვე შეუძლია ცერისა და საჩვენებელი თითის დახმარებით პატარა ნამცეცების აღება. ამ უნარის გასავითარებლად შესთავაზეთ „ხელით საჭმელი“ (finger foods): კარგად მოხარშული და რბილი სტაფილოს ნაჭრები, ბანანის ნაჭრები ან მოხარშული გოგრა. ეს არა მხოლოდ მის მოტორულ უნარებს ავითარებს, არამედ დამოუკიდებლად ჭამის უნარსაც უყალიბებს. ყოველთვის მეთვალყურეობის ქვეშ გყავდეთ!') WHERE id = '832beb7b-28cb-4a32-9588-55e7154e59b5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შეგიმჩნევიათ, რომ როცა ბავშვი სათამაშოს აგდებს, უკვე აკვირდება, სად დაეცა ის? ეს მიუთითებს, რომ „ობიექტის მუდმივობა“ (object permanence) სრულად ჩამოუყალიბდა. მან იცის, რომ სათამაშო, თუნდაც მისი მხედველობის არიდან გაქრეს, არ გამქრალა — უბრალოდ იატაკზე დაეცა. ამიტომ შესაძლოა, ოთახიდან თქვენს გასვლაზე უფრო მძაფრად რეაგირებდეს. შექმენით დამშვიდობების მოკლე რიტუალები, რომლებიც აგრძნობინებს, რომ მიდიხართ, მაგრამ აუცილებლად დაბრუნდებით.') WHERE id = '2f260480-889e-4da7-8269-7ccb344f483a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ძილის რეჟიმი შესაძლოა შეიცვალოს. მე-8 თვეში ზოგი ბავშვი დღის მე-3 ძილზე (ნაშუადღევის მოკლე ძილზე) უარის თქმას იწყებს. ეს სრულიად ნორმალურია. თუ მას დღის განმავლობაში 2-ჯერ შედარებით დიდხანს სძინავს და საღამოს დროულად იძინებს, ესე იგი, ახალ რეჟიმზე გადადიხართ. ფხიზლად ყოფნის პერიოდი უკვე შეიძლება 2.5 - 3 საათამდე გაგრძელდეს. კვლავ დააკვირდით დაღლილობის ნიშნებს (ყურის მოფხანა, თვალების სრესა).') WHERE id = '0800d9fe-eb08-4a4c-84c3-d676b21556f0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველების განვითარების ახალი ეტაპი: შეგიმჩნევიათ, რომ ბავშვი უკვე „თავის ენაზე“ გრძელ წინადადებებს წარმოთქვამს? ეს „ჟარგონის“ პერიოდია. ის უფროსების საუბრის ინტონაციას ბაძავს, კითხვასავით უწევს ხმას ან ხელების მოძრაობით თითქოს რაღაცას ხსნის. ყურადღებით მოუსმინეთ და უპასუხეთ ისეთი ფრაზებით, როგორიცაა: „მართლა? ძალიან საინტერესოა!“ ეს მას ურთიერთობის სურვილს წარმოუდგენლად გაუძლიერებს.') WHERE id = '71cabae0-25d9-4b76-b251-aaf1f4412278';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, მე-8 თვის პირველი ათი დღე დასრულდა! ბავშვი თავის ემოციებს უკვე უფრო რთული ფორმით გამოხატავს: გეალერსებათ, პროტესტს გამოხატავს ან თქვენს დანახვაზე სიხარულით ტაშს უკრავს. დღეს იატაკზე მასთან ერთად ბურთით ითამაშეთ: ბურთი მისკენ გააგორეთ, მან კი სცადოს მისი დაჭერა ან თქვენკენ უკან გამოგორება. ეს მარტივი თამაში თქვენს ფიზიკურ და სოციალურ კავშირს გააძლიერებს. თქვენ შესანიშნავი მეგზური ხართ, დედა!') WHERE id = '9fdaa957-189e-4f2e-b893-b9625e6dd277';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'რძის პროდუქტების სამყაროში მოგზაურობას ვაგრძელებთ! თუ ჯერ არ დაგიწყიათ, რაციონში სახლში მომზადებული ხაჭოს დამატების დროა. ხაჭო კალციუმისა და ცილის შესანიშნავი წყაროა და ბავშვის ძვლებისა და კბილების განვითარებისთვის შეუცვლელია. შეგიძლიათ, ხილის პიურეს შეურიოთ და უფრო გემრიელი გახადოთ. გახსოვდეთ: თუ ხაჭოს მაღაზიაში ყიდულობთ, აუცილებლად შეარჩიეთ უშაქრო, დანამატების გარეშე და ბავშვებისთვის განკუთვნილი სახეობა.') WHERE id = 'ae94f7bd-20c4-400d-a0b5-4fc94f6e2927';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე საკუთარი სხეულის ნაწილების ამოცნობას იწყებს. ჰკითხეთ: „სად არის შენი ცხვირი?“, „სად არის შენი თვალები?“ და საკუთარ სახეზე აჩვენეთ. ეს მარტივი თამაში მის ლექსიკურ მარაგს ამდიდრებს და საკუთარი თავის ცალკეულ პიროვნებად აღქმაში ეხმარება. დადექით სარკესთან და აჩვენეთ მისი ხელები და ფეხები — ასე ეს პროცესი უფრო სახალისო გახდება. ის უკვე ახლოსაა იმის გაგებასთან, რომ სარკეში გამოსახულება მის ანარეკლს წარმოადგენს.') WHERE id = 'c515c840-71f3-41f7-b139-398b94946105';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საყრდენით სიარულის პირველი მცდელობები! თქვენმა ბავშვმა შეიძლება დივანზე ან სკამზე ხელის მოკიდებით გვერდულად ნაბიჯების გადადგმა დაიწყოს. ამას "cruising" ეწოდება. ამ ეტაპზე ნუ იჩქარებთ მისთვის ფეხსაცმლის ჩაცმას; სახლში ფეხშიშველა (ან მოცურების საწინააღმდეგო წინდებით) გადაადგილება საუკეთესოა ფეხის კუნთების სწორად განვითარებისა და წონასწორობის შეგრძნებისთვის. ფეხის თითებით იატაკის შეგრძნება მის ტვინს უფრო მეტ ინფორმაციას აწვდის.') WHERE id = '0028192c-1744-4eba-bb7a-f5c3b5d11c54';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შეამოწმეთ ბავშვის "ნატიფი მოტორიკა": მას უკვე შეუძლია სათამაშო სრულიად თავისუფლად გადაიტანოს ერთი ხელიდან მეორეში და ცერა თითი დანარჩენ თითებს შეახვედროს. ამ პერიოდში მიეცით სხვადასხვა ფორმისა და ფერის "პირამიდის" ტიპის სათამაშოები ან ერთმანეთში ჩასაწყობი ჭურჭელი. მიუხედავად იმისა, რომ ჯერ რგოლებს სწორი თანმიმდევრობით ვერ დააწყობს, მათი დაშლა და აწყობა წარმოუდგენლად ავითარებს მის სივრცით აღქმასა და კოორდინაციას.') WHERE id = 'b139a999-0910-43e1-b5bf-dc2f0d783db4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მრავალფეროვნება მენიუში: თუ ჯერ არ გაგისინჯავთ, შეგიძლიათ პარკოსნების (მაგალითად, წითელი ოსპის) მიცემა დაიწყოთ. ოსპი მცენარეული ცილისა და რკინის წყაროა. თუმცა ფრთხილად იყავით, რადგან პარკოსნებმა შეიძლება აირების დაგროვება გამოიწვიოს. ამიტომ ოსპი წინასწარ დაალბეთ და ბოსტნეულის წვნიანს ძალიან მცირე რაოდენობით დაუმატეთ. დააკვირდით, როგორ რეაგირებს ბავშვის საჭმლის მომნელებელი სისტემა; თუ ყველაფერი რიგზეა, ეს მისთვის ძალიან ნოყიერი სადილი იქნება.') WHERE id = '071fb8f4-fce6-4526-aae9-c60d8797b1ea';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური უნარები: თქვენს ბავშვს უკვე შეუძლია ისეთი ჟესტების მიბაძვა, როგორებიცაა "ნახვამდის" (ხელის დაქნევა) ან "ყოჩაღ" (ტაშის დაკვრა). თუ თქვენ ტაშს უკრავთ და ისიც იმავეს იმეორებს, ეს მის კარგად განვითარებულ მიბაძვის უნარზე მიუთითებს. ეს ჟესტები თამაშად აქციეთ. მიბაძვა სწავლის უმოკლესი გზაა. ყოველი წარმატებული მოქმედების შემდეგ ენთუზიაზმით შეაქეთ — ეს მის თავდაჯერებას გაზრდის.') WHERE id = '5cd6ae76-cf22-4b82-a5b7-ee78e7b002f5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უსაფრთხოების გაფრთხილება: ბავშვს უკვე სიმაღლეზე აძრომა იზიდავს. კარადის უჯრები მისთვის შეიძლება კიბის საფეხურებად იქცეს. ახლა სწორედ დროა, უჯრებზე სპეციალური საკეტები დაამონტაჟოთ. ასევე დარწმუნდით, რომ მძიმე ავეჯი (წიგნების თარო, კომოდი) კედელზე საიმედოდ არის დამაგრებული. ბავშვმა შეიძლება მოქაჩოს და საკუთარ თავზე გადმოაყირაოს. უსაფრთხო სახლი თავისუფლად კვლევის შესაძლებლობას ნიშნავს.') WHERE id = 'a8f4ab5e-3832-4512-afc4-44fcec1c8a18';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წყლის სმის ჩვევა: ბავშვის თირკმლები დამატებით საკვებს ამუშავებს, ამიტომ მისი მოთხოვნილება წყალზე იზრდება. თუ თქვენი ბავშვი წყალზე უარს ამბობს, შესთავაზეთ ის სხვადასხვა საინტერესო გზით. მაგალითად, როცა თავად სვამთ წყალს, მასაც შესთავაზეთ, რადგან ბავშვი თქვენზე დაკვირვებით სწავლობს. წყალი ყოველთვის მისთვის ხელმისაწვდომ ადგილას გქონდეთ. სუფთა წყალი ხელს უწყობს საჭმლის მონელებას და ამცირებს შეკრულობის რისკს.') WHERE id = '73e0efe7-8cf6-4415-b315-772133307918';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ ღამით გაღვიძებები გრძელდება, მიზეზი „განშორების შფოთვასთან“ ერთად კბილების ამოჭრაც შეიძლება იყოს. 8-9 თვის ასაკში, ჩვეულებრივ, ზედა საჭრელი კბილები „გვესალმებიან“. ღრძილები შეიძლება შეშუპებული და მგრძნობიარე იყოს. ძილის წინ სუფთა თითით ღრძილების მსუბუქად დამასაჟება ბავშვს დაამშვიდებს. მოთმინება გამოიჩინეთ — ეს დისკომფორტი დროებითია, თქვენი მხარდაჭერა კი მისთვის მუდმივია.') WHERE id = 'a7e2adf7-fa7d-49f9-b9df-6cb36632b7da';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, უკვე 230 დღე გავიარეთ! თქვენი ბავშვი უკვე ძალიან კარგად ამოიცნობს თქვენს ემოციებს. როცა იღიმებით, მასაც უხარია, ხოლო როცა სერიოზული ტონით საუბრობთ, ჩერდება და გიყურებთ. დღეს მასთან ერთად იატაკზე დაწექით და უბრალოდ „ღიტინი-ღიტინის“ თამაში ითამაშეთ. მისი კისკისი მთელ დაღლილობას დაგავიწყებთ. თქვენ საოცარი კავშირი შექმენით, დედა!') WHERE id = 'd3c12132-2a39-444c-81a2-79aa27f8b6cc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახლა რაციონში სხვადასხვა მარცვლეულის (შვრია, ქერი) დამატებაც შეგიძლიათ. თუ ოჯახში გლუტენზე ალერგია არავის აქვს, შვრიის (oat) ფაფა ბავშვისთვის ნოყიერი და ბოჭკოებით მდიდარი საუზმეა. ბოჭკოვანი საკვები ბავშვის ნაწლავების მუშაობას არეგულირებს და შეკრულობის პრობლემის მოგვარებას უწყობს ხელს. ფაფას შეგიძლიათ ცოტაოდენი დაჭყლეტილი ბანანი ან ვაშლის პიურე დაუმატოთ, რათა მისი გემო უფრო მიმზიდველი გახდეს.') WHERE id = 'f8aaab74-ed0b-4ea9-b26f-011f00ca98cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე ცდილობს, საგნები ერთმანეთში ჩააწყოს ან ერთმანეთზე დაალაგოს? ეს „სივრცითი აღქმის“ განვითარებაზე მიუთითებს. მიეცით სხვადასხვა ზომის პლასტმასის ჭიქები ან ერთმანეთში ჩასაწყობი კონტეინერები. როდესაც აღმოაჩენს, რომ პატარა კონტეინერი დიდში თავსდება, მის ტვინში ახალი ნეირონული კავშირები წარმოიქმნება. ჯერჯერობით კოშკის აშენება შეიძლება გაუჭირდეს, მაგრამ თქვენ მიერ აშენებული კოშკის დანგრევა მისი საყვარელი საქმიანობა გახდება!') WHERE id = '51ca7794-c77c-4014-b77a-c79e37d35c43';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საკუთარი სხეულის გაცნობა: თქვენს ბავშვს უკვე შეუძლია, „ცხვირის“, „თვალის“ ან „პირის“ ხსენებისას მათზე მიგითითოთ ან, როცა თქვენ აჩვენებთ, ღიმილით გამოგეხმაუროთ. ეს საკუთარი თავის შეცნობის მნიშვნელოვანი ნაწილია. ბანაობისას ან ჩაცმისას სხეულის ნაწილები დაასახელეთ და უთხარით: „ახლა მარჯვენა ხელს ვიცვამთ“, „ახლა მარცხენა ფეხს ვბანთ“. ეს ხელს უწყობს როგორც მეტყველების განვითარებას, ისე სხეულის სქემის ჩამოყალიბებას.') WHERE id = '7184c458-15f9-4675-8f4b-a012153962e8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თითებით საჭმელი პროდუქტების“ (finger foods) პერიოდში დახელოვნება: თქვენს ბავშვს უკვე უკეთ შეუძლია, საკვების პატარა ნაჭრები (მაგალითად, მოხარშული სტაფილოს ნაჭერი ან ბარდა) თითებით აიღოს და პირდაპირ პირში ჩაიდოს. ეს უნარი მას თვითრეგულირებისა და დანაყრების შეგრძნების განვითარებაში ეხმარება. დაუდეთ მაგიდაზე უსაფრთხო, რბილი საკვები და მიეცით დამოუკიდებლად ჭამის შესაძლებლობა. ირგვლივ დასვრა ნორმალურია — მთავარია, ბავშვმა ეს უნარი შეიძინოს. ყოველთვის მის გვერდით იყავით და მეთვალყურეობა გაუწიეთ.') WHERE id = 'b13c96d3-3ebb-4786-a1ba-dda465e426a2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე გბაძავთ — თავს ისე აჩვენებს, თითქოს ტელეფონზე საუბრობს, ან თმის დავარცხნას ცდილობს? ეს „ფუნქციური თამაშის“ ეტაპია. ის იწყებს იმის გაგებას, თუ რისთვის გამოიყენება სხვადასხვა ნივთი. მიეცით უსაფრთხო საყოფაცხოვრებო ნივთები (პლასტმასის სავარცხელი, სათამაშო ტელეფონი, ხის კოვზი), რათა მიბაძვის უნარის განვითარებაში დაეხმაროთ. მიბაძვა ბავშვის სოციალური და ინტელექტუალური განვითარების ერთ-ერთი ყველაზე ძლიერი საშუალებაა.') WHERE id = '186aab21-e01b-4cb3-9b1b-f1b7cf5f3b0c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საკვების ტექსტურის შეცვლა: თუ ბავშვს ჯერ კიდევ მთლიანად პიურეს სახით აძლევთ საკვებს, დღეიდან მასში მცირე ნაჭრების რაოდენობა გაზარდეთ. საკვები ბოლომდე არ დააქუცმაცოთ — დატოვეთ მასში პატარა, რბილი ნაჭრები. ეს ბავშვს ღეჭვის უნარს უვითარებს და ღრძილებს უმაგრებს. თუ ბავშვი ნაჭრებს აფურთხებს, ნუ დააძალებთ, თუმცა ყოველი კვებისას კვლავ შესთავაზეთ რამდენიმე ნაჭერი. თუ მოთმინებას გამოიჩენთ, მალე ის ოჯახურ სუფრას სრულად შეეჩვევა.') WHERE id = '0b1ada17-b48a-4258-81e3-556f2db2a842';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური ურთიერთქმედება: თქვენმა ბავშვმა უკვე ისწავლა ხელის დაქნევა „ნახვამდის“ ნიშნად ან ტაშის დაკვრა, როცა ეუბნებით „ყოჩაღ“? ეს ჟესტები მეტყველებამდელი კომუნიკაციის ფორმებია. თუ თქვენი ხელის დაქნევისას ისიც გბაძავთ, ეს თქვენდამი მის მიჯაჭვულობასა და ყურადღებაზე მიუთითებს. ეს მოძრაობები სიმღერებს შეუთავსეთ, რათა პროცესი უფრო სახალისო გახდეს. მის თითოეულ ჟესტს სიხარულით გამოეხმაურეთ, რომ კომუნიკაციის სურვილი გაუძლიერდეს.') WHERE id = '88a30222-647e-4598-aa2c-f27d2f68a4e6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უსაფრთხოების ახალი ეტაპი: ბავშვს უკვე ყველაფერზე აძრომა სურს. დაბალი მაგიდები და დივნის კიდეები მისთვის „მწვერვალებია“. შეამოწმეთ სახლში არსებული ყველა მძიმე ნივთისა და ავეჯის მდგრადობა. განსაკუთრებით დამალეთ ელექტროსადენები (კაბელები), რადგან მათი მოქაჩვა შეიძლება მისთვის ყველაზე საინტერესო საქმიანობად იქცეს. უსაფრთხო სახლი თქვენ სიმშვიდეს მოგანიჭებთ, ბავშვს კი — თავისუფალ სივრცეს გარემოს შესასწავლად.') WHERE id = '42e1e998-0acc-4253-963b-1927f727ffd8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილი და „განშორების შფოთვა“: როდესაც თქვენი ბავშვი ღამით იღვიძებს და ვერ გხედავთ, შეიძლება ხმამაღლა ატირდეს. ამ პერიოდში მნიშვნელოვანია, რომ მას უსაფრთხოების განცდა შეუქმნათ. მასთან მისვლისას შუქი არ აანთოთ, მშვიდი ხმით უთხარით: „დედა აქ არის, დაიძინე“ და მოეფერეთ. ნუ იჩქარებთ მის მაშინვე ხელში აყვანასა და ოთახიდან გაყვანას. მხოლოდ თქვენი იქ ყოფნა და ხმა საკმარის თავდაჯერებას მიანიჭებს, რომ კვლავ დაიძინოს.') WHERE id = 'cab92102-e3a5-49d4-bbd8-bdc2525ea7fb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, სრული 8 თვე უკვე უკან მოვიტოვეთ! თქვენი ბავშვის წონა დაბადების წონასთან შედარებით უკვე დაახლოებით გასამმაგებულია (ეს საშუალო მაჩვენებელია). ის ახლა ძალიან აქტიურია, ხმებს ერთმანეთისგან არჩევს და ოჯახის წევრებს ცნობს. დღეს იატაკზე მასთან ერთად ბურთით ითამაშეთ: ბურთი მისკენ გააგორეთ, ის კი მის დაჭერას შეეცადოს. ეს თამაში ავითარებს როგორც თვალისა და ხელის კოორდინაციას, ისე მონაცვლეობის (სოციალური წესის) უნარს. თქვენ საოცარი გზა გამოიარეთ, დედა!') WHERE id = 'eeeb250d-7860-4dbd-adfd-8f04383dcc0f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-9 თვეში! ამ თვეში ბავშვისთვის „გააზრებული კომუნიკაციის“ პერიოდი იწყება. ახლა, როდესაც ის „მა-მა“-ს ან „ბა-ბა“-ს ამბობს, მხოლოდ ბგერებს კი არ ავარჯიშებს, არამედ პირდაპირ თქვენ ან მამას მოგმართავთ. როცა შემოგხედავთ და ამ სიტყვებს იტყვის, სიხარულით გამოეხმაურეთ და ჩაეხუტეთ. თქვენი დადებითი რეაქცია მას სიტყვების ძალასა და მნიშვნელობას ასწავლის. ახლა ის უკვე ხვდება, რომ ენის საშუალებით საკუთარი სურვილებისა და სიყვარულის გამოხატვა შეუძლია.') WHERE id = 'c35ed773-5541-46b9-a100-13e031ebc738';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ხოხვის ეტაპიდან ოთხზე ცოცვაზე სრული გადასვლა! თქვენი ბავშვი უკვე მუცელს იატაკიდან სწევს და ოთხზე სწრაფად გადაადგილდება. ეს მოძრაობა თავის ტვინის ნახევარსფეროებს შორის ჯვარედინ კოორდინაციას აუმჯობესებს. ოთხზე ცოცვა ასევე საფუძველს უყრის მხედველობით კოორდინაციას, რომელიც მომავალში კითხვისა და წერის უნარებისთვის იქნება საჭირო. მიეცით საშუალება, სახლის ყველა კუთხე გამოიკვლიოს — უბრალოდ დარწმუნდით, რომ მისი გადაადგილების გზები უსაფრთხოა.') WHERE id = 'eef05a4c-d9ba-43c9-8340-a35c1089e87f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვების რაციონის გამრავალფეროვნება: ახლა ბავშვის რაციონს უფრო თამამად შეგიძლიათ დაამატოთ პარკოსნები (მწვანე ოსპი, ლობიოს პიურე) და ხაჭოში შერეული სხვადასხვა სეზონური ხილი. ამ პერიოდში ბავშვის რკინის მარაგის შესანარჩუნებლად ეცადეთ, წითელი ხორცი ან კვერცხის გული მწვანე ბოსტნეულთან ერთად მისცეთ. C ვიტამინი (მაგალითად, ბოსტნეულზე დაწურული რამდენიმე წვეთი ლიმონი) რკინის შეწოვას აუმჯობესებს.') WHERE id = 'c2e87fad-ec56-47c4-9f57-fc56aefe9e8a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პინცეტური მოჭიდება“ (ორი თითით ჩავლება) უკვე ნამდვილ ოსტატობად იქცევა. თქვენი ბავშვი იატაკზე დანახულ უმცირეს ნამცეცსაც კი ორი თითით იღებს. ამ უნარის გასავითარებლად შეგიძლიათ რბილად მოხარშული ბარდის მარცვლები ან ხაჭოს პატარა ნაჭრები შესთავაზოთ. დამოუკიდებლად ჭამა მას თავდაჯერებულობას მატებს. თუმცა ყურადღებით იყავით: ეს უნარი იმასაც ნიშნავს, რომ ბავშვს შეუძლია ღილი, მძივი და სხვა სახიფათო წვრილი საგნები ადვილად ჩაიდოს პირში.') WHERE id = 'afe941be-e174-4b07-9f32-16d62d4cfe8e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ბავშვს უკვე კარგად ესმის სიტყვა „არა“. თუ რაიმე სახიფათოს აკეთებს და ეტყვით „არა“, შეიძლება გაჩერდეს და შემოგხედოთ, პროტესტის ნიშნად კი ატირდეს კიდეც. ასე იწყებს ის საზღვრების გაცნობას. თუმცა ეცადეთ, სახლში ყველაფერზე „არა“-ს თქმა არ გიწევდეთ. სახიფათო ნივთები მოაშორეთ, რათა ბავშვმა თავისუფლად ითამაშოს იქ, სადაც შეგიძლიათ უთხრათ „კი“. საზღვრები მხოლოდ ნამდვილად მნიშვნელოვან შემთხვევებში დაუწესეთ.') WHERE id = 'a85e4f35-e664-455a-b825-3e51d17e5f0d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თამაში „ობიექტის მუდმივობაზე“: თქვენმა ბავშვმა უკვე იცის, რომ თუ სათამაშოს საბნის ქვეშ დამალავთ, ის არ გამქრალა. სათამაშო ნაწილობრივ დამალეთ და ბავშვს მისი პოვნის საშუალება მიეცით. ეს თამაში მის მეხსიერებასა და ლოგიკურ აზროვნებას აძლიერებს. ამასთანავე, „ჭიტას“ თამაში განშორების შიშის შემცირებაშიც ეხმარება — ბავშვი ხვდება, რომ მაშინაც კი, თუ თვალთახედვიდან გაქრებით, აუცილებლად დაბრუნდებით.') WHERE id = '0a1f58ae-f05c-4b6b-aa75-6ff0b27beddc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საყრდენით წამოდგომის უნარი: თქვენი ბავშვი უკვე ყველგან ცდილობს წამოდგომას — დივნის კიდეზე, სკამის ფეხზე ან თუნდაც თქვენს მუხლებზე მოჭიდებით. ამ დროს მან შესაძლოა ჯერ არ იცოდეს, როგორ დაეშვას, ამიტომ იდგეს და დახმარების სათხოვნელად ტიროდეს. აჩვენეთ, როგორ უნდა დაჯდეს; მოუხარეთ მუხლები და ნელა დასვით იატაკზე. ეს მას სხეულის მართვის უნარისა და წონასწორობის შეგრძნების განვითარებაში დაეხმარება.') WHERE id = 'd5785d23-fd09-4663-8877-2740ab81ecbc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილის დროს „მოტორული გამოღვიძებები“: ღამით ძილისას თქვენმა ბავშვმა შეიძლება მოულოდნელად ხოხვა ან ძილბურანში წამოდგომა სცადოს. მისი ტვინი ღამით იმეორებს დღის განმავლობაში ნასწავლ მოძრაობებს. თუ არ ტირის, ნუ შეეხებით — მიეცით საშუალება, თავად იპოვოს მოხერხებული პოზა და ისევ დაიძინოს. თუ ტირის, მშვიდად მიუახლოვდით, სინათლის აუნთებლად დააწვინეთ და დამამშვიდებელი სიტყვები უთხარით. ეს პერიოდი დროებითია.') WHERE id = '3ee50fc0-987b-4449-9a9a-aeac43eacebb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კბილების ამოჭრა და კვება: მე-9 თვეში ხშირად ზედა ან ქვედა გვერდითი საჭრელი კბილები ამოდის. ამ პერიოდში ბავშვს ღრძილები სტკივა, ამიტომ მან შესაძლოა მყარ საკვებზე უარი თქვას. ნუ დააძალებთ; რამდენიმე დღის განმავლობაში უფრო რბილი და გრილი საკვები მიეცით (მაგალითად, ცივი ხილის პიურე ან იოგურტი). კბილის ამოჭრის პროცესის დასრულებისთანავე მადა დაუბრუნდება. თქვენი მოთმინება და სითბო მისთვის საუკეთესო წამალია.') WHERE id = '5c734779-7b9a-4eb8-a3df-dadd22df3bb2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, ერთად უკვე 250-დღიანი დიდი გზა გავიარეთ! თქვენი ბავშვი ახლა უკვე ძალიან ზუსტად კითხულობს თქვენს სახის გამომეტყველებას. როცა თქვენ გიხარიათ, ისიც იცინის, ხოლო როცა სერიოზული ტონით საუბრობთ, ჩერდება და გაკვირდებათ. დღეს მასთან ერთად იატაკზე „წიგნის დათვალიერების“ დრო გაატარეთ. დიდსურათებიან წიგნში ცხოველები აჩვენეთ და მათი ხმები გამოსცეს. ის შეეცდება, მოგბაძოთ. თქვენ მისთვის სამყაროს აღმოჩენის გზაზე ყველაზე სანდო მეგზური ხართ, დედა!') WHERE id = '4168c3b6-34fd-49a6-b076-88e5415caa27';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე მე-9 თვის შუაში ხართ! თქვენი ბავშვი ახლა ნივთებზე დაყრდნობით წამოდგომას სულ უფრო ოსტატურად ახერხებს. თუმცა ყველაზე მნიშვნელოვანი უნარი ჯერ კიდევ წინ არის: მდგომარე მდგომარეობიდან იატაკზე უსაფრთხოდ დაჯდომა. აჩვენეთ, როგორ მოხაროს მუხლები და ნელა დაჯდეს. თუ ზურგზე დაეცემა, ნუ იყვირებთ და ნუ შეაშინებთ; უბრალოდ მიუახლოვდით და კიდევ ერთხელ აჩვენეთ, როგორ უნდა იმოძრაოს სწორად. ეს მისი სხეულის კოორდინაციას აძლიერებს.') WHERE id = '8802254f-c7f7-4ff6-9b20-d9c01f14b494';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის ჟესტებით კომუნიკაცია უკვე აზრს იძენს. მან შეიძლება თითით მიუთითოს სასურველი სათამაშოსკენ (pointing). ეს კოგნიტურ განვითარებაში დიდი ნახტომია! მას სურს, თავისი ყურადღება თქვენთან გაიზიაროს. როცა რაიმეზე მიგითითებთ, მაშინვე დაასახელეთ: „დიახ, ეს ბურთია! ბურთი გინდა?“. ეს დაეხმარება, თავის ტვინში სიტყვებსა და საგნებს შორის კავშირი განამტკიცოს.') WHERE id = '425f3229-dceb-43c5-a7c7-021a098be008';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მრავალფეროვნება კვებაში და ახალი ტექსტურები: უკვე შეგიძლიათ, პიურე საერთოდ დაივიწყოთ. საკვები უბრალოდ ჩანგლით დაჭყლიტეთ და ბავშვს ისე შესთავაზეთ. მისი ღრძილები საკმარისად ძლიერია, რომ კარგად მოხარშული რბილი ხორცის ნაჭრები ან ბოსტნეული დაჭყლიტოს. ღეჭვა აუცილებელია არა მხოლოდ საჭმლის მონელებისთვის, არამედ მეტყველებაში მონაწილე კუნთების განვითარებისთვისაც. თუ ზოგიერთ ლუკმას აფურთხებს, არ ინერვიულოთ — ის ახალ შეგრძნებებს ეჩვევა.') WHERE id = '04975f3b-94a9-41da-8a0a-2994a09d6287';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'განუმტკიცეთ ჭიქიდან წყლის დალევის ჩვევა. ბავშვს უკვე შეუძლია სცადოს ჭიქის ორივე ხელით დაჭერა. მიეცით წყალი პატარა პლასტმასის ან სილიკონის ჭიქით. თავდაპირველად წყლის ნახევარი ზედ გადაესხმება, რაც სრულიად ნორმალურია. ღია ჭიქიდან დალევა ენისა და ყბის სწორი განვითარებისთვის უფრო სასარგებლოა, ვიდრე საწოვარიანი ბოთლიდან დალევა. ეს მისი დამოუკიდებლობისკენ გადადგმული კიდევ ერთი ნაბიჯია.') WHERE id = '2fd76c93-94cc-41aa-af0c-928b17fbd06d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური თამაშები: თამაში „მომეცი-გამომართვი“ უკვე მის საყვარელ საქმიანობად იქცევა. როდესაც სათამაშოს სთხოვთ, შეიძლება გამოგიწოდოთ (თუმცა ზოგჯერ უკანაც წაიღოს!). ეს თამაში მონაცვლეობისა და გაზიარების ცნებების საფუძველს უყრის. არ დაგავიწყდეთ, უთხრათ „გმადლობ“. როდესაც თქვენს დადებით რეაქციას დაინახავს, უფრო ხშირად მოინდომებს ასეთი სოციალური ქცევების გამეორებას.') WHERE id = '7c3fd582-3962-47a8-9de8-b81ab68183e7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პინცეტური მოჭიდება“ (pincer grasp) უკვე სრულყოფილია. ბავშვს იატაკზე არსებული მტვრის უმცირესი ნაწილაკის აღებაც კი შეუძლია. ამ უნარის გასავითარებლად შეგიძლიათ კარგად მოხარშული პარკოსნები (მაგალითად, მუხუდო ან ოსპი) შესთავაზოთ. ეს მას ყურადღების კონცენტრირებაშიც ეხმარება. თუმცა გახსოვდეთ: ყველა პატარა ნივთს, რომელსაც იპოვის, პირში ჩაიდებს, ამიტომ მუდმივად იზრუნეთ, რომ იატაკზე პატარა, სახიფათო საგნები არ ეყაროს.') WHERE id = 'fda4720c-d3a0-4bf6-82ad-06eddb719108';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მეხსიერება უკვე იმდენად გაძლიერდა, რომ რამდენიმე დღის წინ მომხდარი მოვლენების დამახსოვრება შეუძლია. მას შეიძლება ახსოვდეს, სად დამალეთ მისი საყვარელი სათამაშო. ეთამაშეთ უფრო რთული დამალობანას თამაშები. მაგალითად, სათამაშო გადასაფარებლის ქვეშ დამალეთ და დააკვირდით, როგორ იპოვის. ეს აუმჯობესებს როგორც მის ლოგიკურ აზროვნებას, ისე იმის გაგებას, რომ საგნები არ ქრება და მხოლოდ იმალება (ობიექტის მუდმივობა).') WHERE id = '2c349583-ad28-47b1-aaec-34168c563082';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საყრდენზე ხელის მოკიდებით სიარული (cruising) კიდევ უფრო აქტიურდება. ბავშვმა შეიძლება დივნის გასწვრივ ერთი ბოლოდან მეორემდე სწრაფად გაიაროს. ამ ეტაპზე ფეხსაცმელი არ ჩააცვათ. ფეხშიშველი ან მოცურების საწინააღმდეგო წინდებით მოძრაობა ტერფისა და ფეხის თითების სწორად ჩამოყალიბებისთვის იდეალურია. რაც უკეთ შეიგრძნობს იატაკის ზედაპირს, მით უკეთ შეძლებს წონასწორობის შენარჩუნებას.') WHERE id = 'e21e8596-3f21-4200-9b5c-b7f1ca90251a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კბილების ამოჭრის დროს ღრძილების ქავილმა და ტკივილმა შეიძლება ბავშვის ღამის ძილზე იმოქმედოს. თუ ბავშვს ძილში მოუსვენრობა აქვს, ღრძილები სუფთა, ნესტიანი და გრილი პირსახოცით მსუბუქად დაუმასაჟეთ. კბილების ამოჭრის პერიოდში მადის დაქვეითებაც ნორმალურია; ნუ დააძალებთ ჭამას, უფრო ხშირად შესთავაზეთ სითხე და დედის რძე/ხელოვნური ნარევი. თქვენი სითბო მისთვის საუკეთესო ტკივილგამაყუჩებელია.') WHERE id = 'c0bb1b1a-709a-4043-a236-fe5cfd9ea7eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 260 დღე შესრულდა! თქვენი ბავშვი უკვე ყოველთვის ცნობს საკუთარ სახელს და დაძახებისას მაშინვე თქვენკენ ბრუნდება. ის უკვე მკაფიოდ არჩევს ოჯახის წევრებს სხვა ადამიანებისგან და თქვენ მიმართ განსაკუთრებულ მიჯაჭვულობას გამოხატავს. დღეს მასთან ერთად იატაკზე „წიგნის კითხვის“ დრო მოაწყვეთ; მან სურათებზე მიგითითოთ, თქვენ კი მათი სახელები უთხარით. თქვენ მისი ყველაზე სანდო მასწავლებელი და გმირი ხართ, დედა!') WHERE id = '122b28c9-a9e8-422e-9381-d9406e97f79b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე მე-9 თვის ბოლო ათდღეულში შევდივართ. თქვენს ბავშვს ფეხზე დგომისას უკვე შეუძლია, ერთი ხელი დივანს გაუშვას და მეორით სათამაშოს მისწვდეს. ეს აჩვენებს, რამდენად კარგად აქვს განვითარებული წონასწორობის შეგრძნება. ამ პერიოდში დარწმუნდით, რომ მის ირგვლივ არის მყარი ავეჯი, რომელსაც შეიძლება დაეყრდნოს. ის უკვე საკუთარ ძალებს ცდის და მალე პირველი დამოუკიდებელი ნაბიჯის გადასადგმელად გამბედაობას მოიკრებს.') WHERE id = '4ac0d7bc-e3ee-464a-a0d8-d71c88bce550';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახალი მიღწევა ბავშვის „ნატიფ მოტორიკაში“: მას უკვე ძალიან მოსწონს ორი საგნის ერთმანეთზე ერთდროულად დარტყმა და ხმის გამოცემა. ამ დროს ორივე ხელი კოორდინირებულად მუშაობს. მიეცით ორი ხის კუბი ან პლასტმასის ჭურჭელი და დააკვირდით, როგორ აბრახუნებს მათ. ეს მარტივი მოქმედება აძლიერებს როგორც მის სმენით აღქმას, ისე მოძრაობის დაგეგმვის უნარს (motor planning). მუსიკალური რიტმებით ეს თამაში შეგიძლიათ კიდევ უფრო საინტერესო გახადოთ.') WHERE id = 'fddb995c-a311-44d6-a424-3f063a465828';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მრავალფეროვნება კვებაში: თუ ჯერ არ გიცდიათ, ახლა საუკეთესო დროა, რაციონში ხაჭოსთან ან იოგურტთან ერთად რბილი ხილის პატარა ნაჭრები დაამატოთ. ბავშვის ღეჭვითი მოძრაობები უკვე უფრო მოწესრიგებულია. საკვების სრულად დაქუცმაცების ნაცვლად პატარა ნაჭრებად მიცემა ხელს უწყობს ღრძილების გამაგრებას და მომავალში ოჯახის საერთო კვების რეჟიმთან სრულად შეგუებას. მიეცით საშუალება, დამოუკიდებლად ჭამოს — ეს მის თავდაჯერებას ზრდის.') WHERE id = 'b230cf28-523f-407d-9888-06b6c53bb3a6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ურთიერთობაში „მიბაძვის“ პერიოდი: თქვენს ბავშვს უკვე შეუძლია გაიმეოროს თქვენი სახის გამომეტყველება, გამოცემული ხმები და ცემინებაც კი. ის ყურადღებით გაკვირდებათ და სწავლობს. მის წინ სხვადასხვა მოძრაობა გააკეთეთ (მაგალითად, ენა გამოყავით ან თვალები დაახამხამეთ) და ნახეთ, გაიმეორებს თუ არა თქვენს მოქმედებას. მიბაძვის ეს უნარი მისი სოციალური ადაპტაციისა და სწავლის უნარის ერთ-ერთი ყველაზე ძლიერი საშუალებაა.') WHERE id = '671adb79-58b3-4617-94e4-bb4071a9a5ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ობიექტის მუდმივობის“ აღქმა უკვე სრულად ჩამოყალიბებულია. ბავშვმა იცის, რომ თუ სათამაშო ჯიბეში დამალეთ, ის არ გამქრალა — უბრალოდ ჯიბეშია. ის დაგიწყებთ ძებნას და ჯიბეზე მოგქაჩავთ. მეხსიერების ასეთი ვარჯიში მის ლოგიკურ აზროვნებას ავითარებს. მასთან დამალობანა უფრო რთული ფორმებით ითამაშეთ; ეს ასევე დაეხმარება განშორების შფოთვის (separation anxiety) შემცირებაში.') WHERE id = '6997dc99-18bc-4bdc-bae3-c34fc9c367dc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'განუმტკიცეთ ჭიქიდან წყლის დალევის ჩვევა. ბავშვი უკვე სწავლობს, როგორ აკონტროლოს წყლის რაოდენობა, როცა ჭიქის დაჭერასა და პირთან მიტანას ცდილობს. თავდაპირველად წყლის ნახევარი შესაძლოა ტანსაცმელზე გადაესხას — ნუ ინერვიულებთ. ღია ჭიქიდან დალევა ძალიან მნიშვნელოვანია ენისა და ტუჩის კუნთების სწორად განვითარებისთვის. ეს უნარი მომავალში მისი მეტყველების სიცხადეს შეუწყობს ხელს. მოთმინება გამოიჩინეთ — ეს სწავლის პროცესია.') WHERE id = '85d33873-230f-4ec2-aeb2-c03aab1bc8c9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საყრდენზე ხელის მოკიდებით სიარული (cruising) უკვე მნიშვნელოვნად აჩქარდა. ბავშვი დივნის გასწვრივ ისე გადაადგილდება, თითქოს დარბის. ამ ეტაპზე სახლში უსაფრთხოების ზომები კიდევ ერთხელ შეამოწმეთ. ავეჯის ბასრი კუთხეები, ჩამოშვებული სუფრები და იატაკზე გაყვანილი ელექტროსადენები ახლა უფრო დიდ საფრთხეს წარმოადგენს. ბავშვს ყველაფრის მოქაჩვა და თავისკენ მიწევა სურს. უსაფრთხო გარემო მას საშუალებას მისცემს, ცნობისმოყვარეობის შეზღუდვის გარეშე განვითარდეს.') WHERE id = '6cb85c30-34e6-4f9c-a6d7-47b0e62b9c27';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველების განვითარების „ჟარგონის“ ეტაპი: ბავშვი უკვე თავის ენაზე ხანგრძლივ „ისტორიებს“ გიყვებათ. მიუხედავად იმისა, რომ მისი სიტყვები არ გესმით, ის უფროსების საუბრის ინტონაციას შესანიშნავად ბაძავს. ყურადღებით მოუსმინეთ, კითხვები დაუსვით და უპასუხეთ: „მართლა? შემდეგ რა მოხდა?“ ასეთი „დიალოგი“ აძლიერებს საკუთარი აზრის გამოხატვის სურვილს და მის გონებაში სიტყვების მარაგს ამდიდრებს.') WHERE id = '56798677-523b-4029-94dd-1e80eef243c7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კბილების ამოჭრისას ღრძილების ქავილმა და ტკივილმა შეიძლება ბავშვის ღამის ძილზე იმოქმედოს. თუ ბავშვს ძილში მოუსვენრობა აქვს, ღრძილები სუფთა, ნოტიო და გრილი ქსოვილით ნაზად დაუმასაჟეთ. კბილების ამოჭრის პერიოდში მადის დაქვეითებაც ნორმალურია; ნუ დააძალებთ ჭამას, უფრო ხშირად შესთავაზეთ სითხე და დედის რძე/ხელოვნური ნარევი. თქვენი სითბო მისთვის საუკეთესო ტკივილგამაყუჩებელია.') WHERE id = '953f792e-f8bd-44cc-a2d0-c3b8471c1a51';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 9 თვე შესრულდა! ბავშვი უკვე ყოველთვის ცნობს საკუთარ სახელს და დაძახებისთანავე თქვენკენ ბრუნდება. ის ოჯახის წევრებს სხვა ადამიანებისგან უკვე მკაფიოდ არჩევს და თქვენ მიმართ განსაკუთრებულ მიჯაჭვულობას გამოხატავს. დღეს მასთან ერთად იატაკზე „წიგნის კითხვის“ დრო მოაწყვეთ; მან სურათებზე მიგითითოთ, თქვენ კი მათი სახელები უთხარით. თქვენ მისი ყველაზე სანდო მასწავლებელი და გმირი ხართ, დედა!') WHERE id = 'b5fee624-3a8a-4073-bf22-e9bf23545a25';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-10 თვეში! ეს თვე შეიძლება ბავშვის „დამოუკიდებლობის დეკლარაციის“ თვედ ჩაითვალოს. მას უკვე უფრო თავდაჯერებულად შეუძლია ავეჯზე მოჭიდებით დგომა და რამდენიმე წამით საყრდენის გარეშეც კი ცდილობს გაჩერებას. წონასწორობის შენარჩუნების ეს ხანმოკლე მომენტები პირველი ნაბიჯების მოახლოებას გვაუწყებს. შეუქმენით მას ფართო და უსაფრთხო სივრცე. გახსოვდეთ, ყოველი წაქცევა მას მიზიდულობის ძალისა და საკუთარი სხეულის მართვას ასწავლის. უბრალოდ მის გვერდით იყავით და გაამხნევეთ.') WHERE id = '162ad9af-c711-43da-b203-5c312cf418b0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მეტყველებაში ისეთი სიტყვები, როგორიცაა „მა-მა“, „ბა-ბა“ ან „ად-და“, უკვე სრულიად გააზრებულ მნიშვნელობას იძენს. თუ ამ სიტყვების წარმოთქმისას ის თქვენ ან მამას გიყურებთ, ეს ნიშნავს, რომ მან სიტყვა შესაბამის საგანს ან ადამიანს დაუკავშირა. პასუხის გაცემისას მარტივი და გასაგები წინადადებები გამოიყენეთ. მაგალითად, როცა ის ამბობს „ბურთი“, უპასუხეთ: „დიახ, ეს წითელი ბურთია“ და ამგვარად გაუმდიდრეთ ლექსიკა. თქვენი ყოველი პასუხი მის ტვინში ახალ ენობრივ კავშირებს აყალიბებს.') WHERE id = 'be8f3e1a-5335-4ace-960c-562783ff9dcb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვების ახალი ეტაპი: „პინცეტური მოჭიდება“ (pincer grasp) უკვე იმდენად კარგად არის განვითარებული, რომ თქვენს ბავშვს შეუძლია პატარა ბარდის მარცვალი ან რბილად მოხარშული სტაფილოს ნაჭერი დამოუკიდებლად აიღოს და პირთან მიიტანოს. მიეცით მას მეტი შესაძლებლობა, თავად ჭამოს. ეს ხელს უწყობს როგორც მოტორული უნარების განვითარებას, ისე დანაყრების შეგრძნების დამოუკიდებლად მართვას. ნუ შეგეშინდებათ, თუ ირგვლივ ყველაფერი დაისვრება — ეს „შემოქმედებითი უწესრიგობა“ მისი განვითარებისთვის მნიშვნელოვანია.') WHERE id = '58ffad0f-55f8-47af-b047-3975e8528016';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე ოსტატურად გბაძავთ. როცა ტელეფონით საუბრობთ, ისიც იღებს ხელში რაიმე საგანს და ყურთან მიაქვს; როცა თმას ივარცხნით, ისიც მსგავს მოძრაობას აკეთებს. ეს „ფუნქციური მიბაძვის“ პერიოდია. ხელი შეუწყვეთ ამ უნარის განვითარებას და მიეცით უსაფრთხო საყოფაცხოვრებო ნივთები (პლასტმასის სავარცხელი, სათამაშო ტელეფონი, ხის კოვზი). ის სამყაროს თქვენზე დაკვირვებით სწავლობს, ამიტომ ეცადეთ, თქვენი ქცევით კარგი მაგალითი მისცეთ.') WHERE id = 'a6c8ab18-10f6-4956-855e-8fca749308ef';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„ობიექტის მუდმივობის“ თამაში: თქვენმა ბავშვმა უკვე იცის, რომ თუ სათამაშოს ჭურჭელში ჩადებთ და ზემოდან დაფარავთ, ის არ გამქრალა. ითამაშეთ მასთან დამალობანას უფრო რთული ვარიანტები. მაგალითად, სათამაშო ორი სხვადასხვა საფარიდან ერთ-ერთის ქვეშ დამალეთ და დააკვირდით, როგორ იპოვის მას. ეს აუმჯობესებს როგორც მის მეხსიერებას, ისე ყურადღების კონცენტრირების უნარს. როცა ამოცანას ამოხსნის, დიდი ენთუზიაზმით შეაქეთ.') WHERE id = '535f32b7-37dd-475b-9f52-55c5a1160920';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საყრდენზე მოჭიდებით სიარული (cruising) უკვე სრულიად ავტომატურ უნარად იქცა. თქვენს ბავშვს შეუძლია, დივანზე მოჭიდებით ოთახის ერთი ბოლოდან მეორემდე სწრაფად გადაადგილდეს. ამ ეტაპზე კიდევ ერთხელ შეამოწმეთ სახლის უსაფრთხოება: ჩამოშვებული სუფრები, იატაკზე გაბნეული ელექტროსადენები და ბასრი კუთხეები ახლა უფრო დიდ საფრთხეს წარმოადგენს. მას ყველაფრის მოქაჩვა, თავისკენ მიზიდვა და ყველგან აცოცება სურს. უსაფრთხო გარემო მას თავისუფლად აღმოჩენის შესაძლებლობას აძლევს.') WHERE id = 'd10583a3-e400-4339-b85b-3d395175b72a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახალი ჟესტები სოციალურ ურთიერთობაში: თქვენი ბავშვი უკვე თითით მიგითითებთ სასურველ საგანზე (pointing). ეს კოგნიტურ განვითარებაში დიდი ნახტომია. მას სურს, თავისი ყურადღება თქვენც გაგიზიაროთ. როცა რაიმეზე მიგითითებთ, მაშინვე დაასახელეთ: „დიახ, ეს ჩიტია! შეხედე, ჩიტი მიფრინავს“. ეს მის ლექსიკურ მარაგსაც ზრდის და თქვენთან ემოციურ კავშირსაც აძლიერებს. ძალიან მნიშვნელოვანია, მისი ინტერესის მიმართ გულგრილი არ დარჩეთ.') WHERE id = '1c394285-7074-4a0d-ac82-eab79473970a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დაეხმარეთ ბავშვს ჭიქიდან წყლის სმის უნარის დახვეწაში. თქვენი ბავშვი უკვე თითქმის ახერხებს, ჭიქა ორივე ხელით დაიჭიროს და წონასწორობა შეინარჩუნოს. მიეცით მცირე რაოდენობით წყალი პატარა პლასტმასის ან სილიკონის ჭიქით. წყლის დაღვრა სწავლის პროცესის ნაწილია. ღია ჭიქიდან სმა ენისა და ტუჩის კუნთების სწორად განვითარებისთვის საწოვარიან ბოთლთან შედარებით უფრო სასარგებლოა და მომავალში უფრო მკაფიო მეტყველების ჩამოყალიბებას უწყობს ხელს.') WHERE id = '863feabb-ad16-4aad-8a94-087f99977902';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ კბილების ამოჭრის პროცესი გრძელდება, ბავშვს შესაძლოა კვლავ დაერღვეს ძილი და მადა. მე-10 თვეში, ჩვეულებრივ, ზედა ან ქვედა გვერდითი საჭრელი კბილები ამოდის. თუ ღრძილები ძალიან ექავება, მიეცით გაგრილებული (მაგრამ არა გაყინული) კბილების ამოსაჭრელი სათამაშო ან გრილი ბოსტნეულის ნაჭრები (თქვენი მეთვალყურეობით). ამ პერიოდში მეტი სითხისა და დედის რძის შეთავაზება მას ორგანიზმში სითხის საჭირო დონესაც შეუნარჩუნებს და დაამშვიდებს კიდეც. თქვენი სითბო საუკეთესო ტკივილგამაყუჩებელია.') WHERE id = '22dd56cb-e699-4f81-b502-66f9d54e2b23';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 280 დღე გავიარეთ! თქვენი ბავშვი უკვე ყოველ ჯერზე ცნობს საკუთარ სახელს და მკაფიოდ რეაგირებს. მას უკვე შეუძლია საყვარელი სათამაშოს ან ადამიანის არჩევა და საკუთარი „ხასიათის“ გამოვლენას იწყებს. დღეს მასთან ერთად იატაკზე დაწექით და უბრალოდ „მიბაძობანა“ ითამაშეთ: მან გამოსცეს ხმა და თქვენ გაიმეორეთ, თქვენ დაუკარით ტაში და მან გაიმეოროს. თქვენ მისთვის ყველაზე საიმედო ნავსაყუდელი ხართ, საიდანაც სამყაროს შეისწავლის, დედა!') WHERE id = '71654afe-3791-4e59-a41c-7da09d0ef29c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე მე-10 თვის შუაგულში ხართ! თქვენი ბავშვი ახლა უკვე ოსტატურად დგება ფეხზე საგნებზე დაყრდნობით და რამდენიმე წამით ხელების გაშვებასა და დამოუკიდებლად დგომასაც კი ცდილობს. ეს აჩვენებს, რამდენად გაუმყარდა წონასწორობის უნარი და ფეხის კუნთები. ნუ დააძალებთ დამოუკიდებლად დგომას — დაე, ეს ნაბიჯი მაშინ გადადგას, როცა თავს მზად იგრძნობს. შეუქმენით უსაფრთხო „სათამაშო სივრცე“, რომელსაც გარშემო რბილი ბალიშები ექნება შემოწყობილი, რათა დაცემის არ შეეშინდეს.') WHERE id = '03d76f01-bcab-4644-9f10-2526c187201c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახალი ეტაპი ბავშვის მეტყველებაში: „ჟარგონული“ საუბარი! თითქოს თქვენთვის რაღაცის ახსნას ცდილობს — წარმოთქვამს გრძელ, ინტონაციითა და ემოციებით სავსე „წინადადებებს“. მიუხედავად იმისა, რომ ჯერ ვერცერთ სიტყვას ვერ იგებთ, ეს მისი მომავალი მეტყველების საფუძველია. ყურადღებით მოუსმინეთ და უპასუხეთ: „მართლა? ძალიან საინტერესოა, მერე რა მოხდა?“ ასეთი დიალოგები საკუთარი აზრის გამოხატვის სურვილს უძლიერებს და მის გონებაში ლექსიკურ მარაგს სწრაფად ამდიდრებს.') WHERE id = 'e6d2e0ec-fef4-4fdf-bd36-60be17d3ab5e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დაასრულეთ კვების ტექსტურაზე გადასვლის პროცესი. პიურეს ეტაპი უკვე სრულად წარსულში უნდა დარჩეს. საკვები უბრალოდ ჩანგლით დასრისეთ ან პატარა, რბილ ნაჭრებად (finger foods) შესთავაზეთ. ბავშვის ღრძილები უკვე საკმარისად ძლიერია, რომ რბილად მომზადებული ხორცი ან ბოსტნეული დაჭყლიტოს. ეს ღეჭვის უნარს აძლიერებს და მომავალში „საკვების არჩევითობის“ პრობლემების თავიდან აცილებას უწყობს ხელს. იყავით მომთმენი — ყოველი ახალი ტექსტურა სწავლის გამოცდილებაა.') WHERE id = '25d3da74-5500-488e-93bc-4e022b9fdf57';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ თამაშებში „რიგრიგობით მოქმედების“ უნარი: თქვენს ბავშვს უკვე უკეთ ესმის თამაში „მომეცი — მოგცემ“. გაუწოდეთ სათამაშო, შემდეგ კი სთხოვეთ: „ახლა შენ მომეცი ბურთი“. თუ მოგცემთ, აღფრთოვანებით შეაქეთ. ეს თამაში საფუძველს უყრის გაზიარების გაგებასა და ორმხრივი კომუნიკაციის წესების ათვისებას. ამასთანავე, აუმჯობესებს ხელისა და თვალის კოორდინაციას და საგნის ხელიდან გაშვების უნარს.') WHERE id = '639df12e-60c1-4322-9712-2375f1060042';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„კატეგორიები“ შემეცნებით განვითარებაში: თქვენი ბავშვი უკვე იწყებს მსგავსი საგნების ერთმანეთისგან გარჩევას. მაგალითად, მალე მიხვდება, რომ სხვადასხვა ფორმის ბურთი მაინც „ბურთია“. აჩვენეთ სხვადასხვა ფერისა და ზომის ბურთები ან კუბები. ეს აბსტრაქტული აზროვნების პირველი ნაბიჯებია. თამაშისას ხმამაღლა დაასახელეთ საგნების ფერი და ფორმა: „ეს დიდი მანქანაა, ეს კი პატარა მანქანაა“.') WHERE id = '4207275f-8c9b-455a-be42-c07fcdc66c91';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პინცეტური ჩავლება“ (pincer grasp) უკვე სრულყოფილად აქვს ათვისებული. თქვენი ბავშვი იატაკზე დანახულ უმცირეს ნამცეცსაც კი ცერა და საჩვენებელი თითებით იღებს. ამ უნარის კიდევ უფრო გასავითარებლად მიეცით კარგად მოხარშული ოსპის მარცვლები ან ხაჭოს პატარა, რბილი ნაჭრები. ყურადღებით იყავით: ეს უნარი იმასაც ნიშნავს, რომ ბავშვმა ნებისმიერი ნაპოვნი სახიფათო წვრილი ნივთი (ღილი, მძივი) შეიძლება იმავე სიმარჯვით პირში ჩაიდოს. სახლის სისუფთავე ახლა უფრო მნიშვნელოვანია, ვიდრე ოდესმე.') WHERE id = 'd9053aab-2643-4a33-bd40-377294e7163f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საყრდენზე ხელის მოკიდებით სიარული (cruising) იმდენად აჩქარდა, რომ თქვენი ბავშვი დივნის კიდის გასწვრივ თითქმის დარბის. ამ ეტაპზე კიდევ ერთხელ შეამოწმეთ, რამდენად მყარად დგას სახლში ავეჯი. ბავშვს ყველაფერზე ხელის მოკიდებით წამოდგომა და აძრომა სურს. ჩამოშვებული სუფრები აიღეთ, რადგან თუ ბავშვი მათ ჩაეჭიდება და წამოდგომას შეეცდება, შეიძლება მაგიდაზე არსებული ყველაფერი ზედ გადმოიყაროს. უსაფრთხო გარემო ბავშვს თავდაჯერებას მატებს და საშუალებას აძლევს, გარემო შიშის გარეშე შეისწავლოს.') WHERE id = '22ae7b1e-0f5e-4f2c-a0b9-f363eec03221';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'საკუთარი თავის გაცნობიერება: თქვენი ბავშვი უკვე იწყებს მიხვედრას, რომ სარკეში საკუთარი ანარეკლია. თუ ცხვირზე პატარა ფერად ლაქას დავუსვამთ და სარკეში ჩავახედებთ, ის საკუთარ სახეზე ლაქის მოშორებას შეეცდება (ამას „პომადის ტესტი“ ეწოდება). ეს თვითცნობიერების (self-awareness) განვითარების ნიშანია. დადექით მასთან ერთად სარკის წინ და განსხვავებები აჩვენეთ სიტყვებით: „ეს შენი ცხვირია, ეს კი დედის ცხვირია“. ეს ასევე შესანიშნავი სავარჯიშოა სხეულის სქემის ჩამოსაყალიბებლად.') WHERE id = 'aee72c71-4ab2-40ae-a72a-f441c99bcf9d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილის დროს „განშორების შფოთვამ“ შესაძლოა კვლავ იჩინოს თავი. გაღვიძებისას, თუ ბავშვი ვერ დაგინახავთ, შეიძლება მაშინვე ატირდეს. მის დასამშვიდებლად მიუახლოვდით, შუქის აუნთებლად ნაზად მოეფერეთ და ჩასჩურჩულეთ: „დედა აქ არის, დაიძინე“. ნუ იჩქარებთ მის მაშინვე ხელში აყვანასა და ოთახიდან გაყვანას; მიეცით საშუალება, იგრძნოს თქვენი სიახლოვე და თავად სცადოს ხელახლა დაძინება. თქვენი მოთმინება ამ პერიოდის უფრო მშვიდად გავლაში დაგეხმარებათ.') WHERE id = '807f6974-949a-4673-9e12-ca050a097e4d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 290 დღე გავიარეთ! ბავშვი უკვე ავლენს საკუთარ ხასიათს: რა მოსწონს, რისი ეშინია, რომელი საკვები უყვარს... დღეს მასთან ერთად იატაკზე წამოწექით და უბრალოდ ითამაშეთ თამაში, რომელსაც თავად წარმართავს. მიეცით საშუალება, „გიხელმძღვანელოთ“, სათამაშო გადმოგცეთ ან მოგბაძოთ. მასთან გატარებული ყოველი წუთი მისი მომავალი ბედნიერების საფუძველია. თქვენ საოცარი გზა გამოიარეთ, დედა!') WHERE id = '2489cf6a-6c9a-4826-ac80-afae063dcb86';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-10 თვის ბოლო ათდღეულში! ბავშვი უკვე თავდაჯერებით დგამს ნაბიჯებს, როცა ერთი ხელით გიჭირავთ, თუ ჯერ კიდევ ვერ ბედავს საყრდენის გარეშე დგომას? ორივე შემთხვევა ნორმალურია. ზოგი ბავშვი მე-10 თვეში იწყებს სიარულს, ზოგი კი 15-16 თვემდე იცდის. ფეხის კუნთების გასაძლიერებლად მიეცით საშუალება, მეტი დრო გაატაროს იატაკზე. როგორც კი საკუთარ ძალებში დარწმუნდება, პირველი დამოუკიდებელი ნაბიჯით გაგაოცებთ!') WHERE id = '96dedeae-65fd-4082-8b02-077d47cad21d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის „ობიექტის მუდმივობის“ აღქმა უკვე იმდენად განვითარებულია, რომ მას არ ბეზრდება ნივთის ყუთში ჩადება და შემდეგ იქიდან ამოღება. ეს „ჩადებისა და ამოღების“ თამაში ავითარებს როგორც სივრცით აღქმას, ისე წვრილ მოტორიკას. მიეცით სხვადასხვა ზომის ჭურჭელი და უსაფრთხო ნივთები, რომელთა შიგნით მოთავსებასაც შეძლებს. ეს მარტივი სავარჯიშო მომავალში რთული ამოცანების გადაჭრის უნარის საფუძველია.') WHERE id = 'a8043f3c-dcb0-41ac-858a-58401aab3cc0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახალი ნახტომი მეტყველების განვითარებაში: ბავშვი უკვე ზოგიერთ სიტყვას ან ბგერას კონკრეტულ მოვლენებს უკავშირებს. მაგალითად, კარზე ზარის დარეკვისას შეიძლება თქვას „მამა“, ხოლო შიმშილის დროს — განსაკუთრებული ხმა გამოსცეს. ეს გააზრებული მეტყველების დასაწყისია. ყურადღებით უპასუხეთ მის ყოველ ხმოვან მიმართვას: „დიახ, კარზე ზარი დარეკეს, მამა მოვიდა!“. თქვენი ასეთი „თარგმანი“ მის გონებაში სიტყვების მნიშვნელობას მყარად ამკვიდრებს.') WHERE id = '7f7f52b6-f75a-4125-9bb5-a72c5365ce29';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მრავალფეროვნება კვებაში: ბავშვის რაციონში უკვე შეგიძლიათ ძალიან მცირე რაოდენობით დაამატოთ მთლიანი მარცვლეული (კარგად მოხარშული), რბილი მაკარონი ან პურის რბილობი. ეს ეხმარება მას სხვადასხვა ტექსტურის შეგრძნებასა და ღეჭვის უნარის გაუმჯობესებაში. გახსოვდეთ, საკვებს ჯერ კიდევ არ ვუმატებთ მარილსა და შაქარს. ბუნებრივი გემოები საუკეთესოა მისი გემოს რეცეპტორების სწორად ჩამოყალიბებისთვის.') WHERE id = 'b9f43156-8bbe-4d46-a470-47337a11cf3a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'იწყება „მე თვითონ!“ პერიოდი. ჭამის დროს თქვენს ბავშვს სულ უფრო მეტად მოუნდება, კოვზი ხელიდან გამოგართვათ ან საკვები პირდაპირ ხელებით ჭამოს. ნუ ჩაახშობთ მის დამოუკიდებლობისკენ სწრაფვას. მიეცით საშუალება, ხელები დაისვაროს და სახე პიურეთი მოითხუპნოს. ეს პროცესი მას თავდაჯერებას შემატებს და საკვებთან დადებითი დამოკიდებულების ჩამოყალიბებაში დაეხმარება. თქვენი მოთმინება საფუძველს უყრის იმას, რომ მომავალში კარგი მადის მქონე და დამოუკიდებელი ბავშვი გახდეს.') WHERE id = 'b31abab7-200d-4d55-b197-62b606e68100';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური უნარები: თქვენს ბავშვს უკვე შეუძლია ისეთი ჟესტების გამეორება, როგორებიცაა „ნახვამდის“ (ხელის დაქნევა) ან „კოცნის გამოგზავნა“ (ჰაეროვანი კოცნა). ეს ჟესტები მეტყველებამდელი კომუნიკაციის ფორმებია. თუ ხელის დაქნევისას ისიც გბაძავთ, ეს თქვენდამი მის მიჯაჭვულობასა და ყურადღებაზე მიუთითებს. ეს მოძრაობები სიმღერებს შეუთავსეთ, რათა პროცესი უფრო სახალისო გახდეს. მის თითოეულ ჟესტს სიხარულით გამოეხმაურეთ, რომ კომუნიკაციის სურვილი გაუძლიერდეს.') WHERE id = 'db90e8f1-9d73-4d53-8169-2122571f4a13';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უსაფრთხოების ახალი ეტაპი: ბავშვს უკვე მაღლა აძრომის სურვილი უჩნდება. დაბალი მაგიდები და დივნის კიდეები მისთვის „მწვერვალებია“. შეამოწმეთ სახლში არსებული ყველა მძიმე ნივთისა და ავეჯის მდგრადობა. განსაკუთრებით დამალეთ ელექტროსადენები (კაბელები), რადგან მათი მოქაჩვა შეიძლება მის ერთ-ერთ მთავარ ინტერესად იქცეს. უსაფრთხო სახლი თქვენ სიმშვიდეს მოგანიჭებთ, ბავშვს კი — კვლევისთვის ფართო სივრცეს.') WHERE id = 'cd4b7de4-c97d-44b4-ae4b-d87984914859';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილი და შემეცნებითი განვითარება: ღამით გაღვიძებულმა ბავშვმა შეიძლება ხმამაღლა იტიროს, თუ ვერ დაგინახავთ. ამ პერიოდში მნიშვნელოვანია, მას დაცულობის განცდა შეუქმნათ. როცა მასთან მიხვალთ, შუქის აუნთებლად, მშვიდი ხმით უთხარით: „დედა აქ არის, დაიძინე“ და მოეფერეთ. ნუ იჩქარებთ მის მაშინვე ხელში აყვანასა და ოთახიდან გაყვანას. მხოლოდ თქვენი იქ ყოფნა და ხმა საკმარისად დაამშვიდებს, რომ კვლავ ჩაეძინოს. ეს „განშორების შფოთვის“ დროებითი ეტაპია.') WHERE id = 'd5f8c50f-64e6-4aba-ad9f-5604b24fb65b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ხვალ თქვენი ბავშვის დაბადებიდან ზუსტად 300 დღე შესრულდება! ამ 10 თვის განმავლობაში მან წარმოუდგენელი გზა გაიარა: უმწეო ჩვილიდან საკუთარი ხასიათის, სურვილებისა და უნარების მქონე პატარა ადამიანად იქცა. თქვენც ამ ხნის განმავლობაში დიდი გამოცდილება შეიძინეთ. დღეს მასთან ერთად იატაკზე წამოწექით და უბრალოდ უყურეთ მის ღიმილს. თქვენი სიყვარული მისი განვითარების ყველაზე ძლიერი მამოძრავებელი ძალაა.') WHERE id = '2638511c-740a-477b-ab58-1fbe5fd5c94a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! თქვენი ბავშვის დაბადებიდან 300 დღე გავიდა! ეს ერთი წლის შესრულებამდე ბოლო მნიშვნელოვანი ეტაპია. თქვენი ბავშვი უკვე ცნობს საკუთარ სახელს ყოველ ჯერზე, როცა დაუძახებთ, მკაფიოდ გამოხატავს ემოციებს და, შესაძლოა, პირველი ნაბიჯების გადასადგმელადაც ემზადება. აღნიშნეთ ეს დღე მასთან ერთად განსაკუთრებული თამაშით ან მისი საყვარელი ხილით. თქვენ შესანიშნავად გაართვით თავი, დედიკო! 300-დღიანი შრომის შედეგი იმ ბედნიერ თვალებში ჩანს, რომლებიც ყოველდღე შემოგყურებენ.') WHERE id = '4dbc6d6a-ae47-4867-ba96-b66058f91a2f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-11 თვეში! პირველ დაბადების დღემდე სულ რაღაც ორი თვე დარჩა. ამ პერიოდში თქვენს ბავშვს უკვე უკეთ ესმის განსხვავება „მე“-სა და „შენ“-ს შორის. ის თქვენი სახის გამომეტყველების მიბაძვით ემოციურ ინტელექტს ავითარებს. როცა მოწყენილი ხართ, ისიც შეიძლება დასერიოზულდეს, ხოლო როცა იცინით, შეიძლება ხმამაღლა გადაიკისკისოს. ესაუბრეთ მას გრძნობების შესახებ — ეს მომავალში საკუთარი ემოციების მართვის უნარს მყარ საფუძველს შეუქმნის.') WHERE id = '9a834d06-30b3-4c6c-92b2-859a3c7000f4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე თავდაჯერებულად დადის, როცა ერთი ხელით გიჭირავთ, თუ ჯერ კიდევ მხოლოდ დივნის კიდეს მიუყვება? ამ დღეებში მან შეიძლება წონასწორობის შესანარჩუნებლად ხელები გვერდებზე გაშალოს და ერთი-ორი დამოუკიდებელი ნაბიჯი გადადგას. ასეთი „ბალანსის“ მოძრაობები მის ტვინში წონასწორობის ცენტრს (ვესტიბულურ აპარატს) ავარჯიშებს. ნუ დააჩქარებთ — მიეცით საშუალება, საკუთარ ძალებში სრულად დარწმუნდეს.') WHERE id = 'a31576c9-38ba-4027-9aca-cbc63e6f334a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'შემეცნებით განვითარებაში „სურვილების გამოხატვა“: თქვენს ბავშვს უკვე შეუძლია, მხოლოდ ტირილის ნაცვლად, თითით მინიშნებითა და განსაკუთრებული ბგერების გამოცემით გაგაგებინოთ, რა სურს. როდესაც სათამაშოსკენ მიგითითებთ, მისი სურვილი სიტყვიერად დაადასტურეთ: „დიახ, ეს დათუნია გინდა?“ ეს მას უჩენს განცდას, რომ „ჩემი ესმით“, და მომავალში ხელს უწყობს გაუგებრობით გამოწვეული აგრესიული ქცევის (ტირილის) თავიდან აცილებას.') WHERE id = 'aa86788c-ff14-4450-8f10-2208ffcc316b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლობა კვებისას: თქვენს ბავშვს უკვე სურს, კოვზი მთლიანად თვითონ დაიჭიროს და პირთან მიიტანოს. დიახ, საკვების დიდი ნაწილი იატაკსა და წინსაფარზე აღმოჩნდება, მაგრამ ეს ნატიფი მოტორიკისა და ხელისა და თვალის კოორდინაციის ერთ-ერთი უმნიშვნელოვანესი ვარჯიშია. მიეცით მისთვის მოსახერხებელი სილიკონის ან სქელსახელურიანი კოვზი. ამავდროულად, თქვენც შეგიძლიათ სხვა კოვზით დაეხმაროთ. ეს „გუნდურ მუშაობას“ ჰგავს!') WHERE id = '3159f58c-c8a2-418a-a8bd-3b961ca0266e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ცხოველების ხმების“ პერიოდი დადგა! თქვენმა ბავშვმა შეიძლება უკვე საკუთარ ენაზე დაიწყოს პასუხის გაცემა ისეთ კითხვებზე, როგორიცაა „როგორ ყეფს ძაღლი?“ და „რა ხმას გამოსცემს კატა?“. ამ ეტაპზე ბგერების მიბაძვის უნარი პიკს აღწევს. განაგრძეთ ასეთი თამაშები ცხოველების სურათებიანი წიგნების დათვალიერებისას. ბგერების მიბაძვა სამეტყველო აპარატს (ენასა და ტუჩის კუნთებს) მომავალში რთული სიტყვების წარმოსათქმელად ამზადებს.') WHERE id = '43246706-501b-4546-a51a-8e59351b53c5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პინცეტური მოჭიდება“ (pincer grasp) უკვე იმდენად დაიხვეწა, რომ ბავშვს იატაკიდან უწვრილესი ძაფის ან პაწაწინა ნამცეცის აღებაც კი მარტივად შეუძლია. ამ უნარის გამოსაცდელად შეგიძლიათ კარგად მოხარშული პარკოსნები (მუხუდო, ოსპი) შესთავაზოთ. თუმცა გახსოვდეთ: ჩვევა, რომ ნებისმიერი ნაპოვნი პატარა ნივთი პირში ჩაიდოს, ასევე პიკს აღწევს. იატაკის სისუფთავე და მცირე ზომის ნივთების მიუწვდომელ ადგილას შენახვა კვლავ უსაფრთხოების უმნიშვნელოვანეს წესად რჩება.') WHERE id = '1053192f-a2a7-43d0-8335-34db00482590';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური თამაშების გართულება: თქვენს ბავშვს თამაში „მომეცი-გამომართვი“ უკვე ახალ დონეზე გადაჰყავს. მან შეიძლება სათამაშო მოგცეთ და მაშინვე უკან მოითხოვოს, ან როცა ეტყვით „მომეცი“, განზრახ დამალოს. ეს მისი პირველი „ხუმრობებია“. მის იუმორის გრძნობას სიცილით უპასუხეთ. სიცილი და ერთად გართობა თქვენ შორის ემოციურ კავშირს წარმოუდგენლად აძლიერებს.') WHERE id = '3451f734-1652-4c0f-97a4-7d508b0bb860';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ძილის რეჟიმი და ფხიზლად ყოფნის პერიოდი: მე-11 თვეში ბავშვებმა შესაძლოა დღის 2 ძილიდან 1 ძილზე გადასვლის ნიშნები გამოავლინონ, მაგრამ ჯერ ნუ იჩქარებთ. ბავშვების უმეტესობას 14-15 თვემდე დღის განმავლობაში 2-ჯერ ძილი სჭირდება. თუ ბავშვს დილით ჩაძინება უჭირს, სცადეთ, ფხიზლად ყოფნის პერიოდი ოდნავ გაუხანგრძლივოთ (დაახლოებით 3 - 3.5 საათი). კარგად დასვენებული ბავშვი ახალ უნარებს მეტი ხალისით სწავლობს.') WHERE id = '852db72f-d9a2-475c-b994-d1ab8a6b4f97';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცის აღქმა“: თქვენს ბავშვს უკვე მოსწონს ყუთებში ჩახედვა, თავსახურების გახსნა-დახურვა და ნივთების ერთმანეთში ჩაწყობა. მიეცით სხვადასხვა ზომის პლასტმასის კონტეინერები. როდესაც აღმოაჩენს, რომ პატარა კონტეინერი დიდში თავსდება, მის ტვინში რთული მათემატიკური და ლოგიკური კავშირები ყალიბდება. მიუხედავად იმისა, რომ ეს მარტივად გამოიყურება, სინამდვილეში დიდი აღმოჩენაა.') WHERE id = '114fd473-c44c-4c3b-b5d0-19ac5cbf17e6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 310 დღე გავიარეთ! თქვენი ბავშვი უკვე საკუთარ ნებას ავლენს: როცა ჩაცმა არ სურს, ფეხებს ჭიმავს, ხოლო საყვარელი საკვების დანახვისას ტაშს უკრავს. მიუხედავად იმისა, რომ „პიროვნულობის“ ამ ნიშნებმა შეიძლება ზოგჯერ დაგღალოთ, სინამდვილეში ისინი მისი ჯანსაღი ფსიქოლოგიური განვითარების მაჩვენებელია. დღეს მასთან ერთად იატაკზე ითამაშეთ მხოლოდ ის თამაში, რომელიც თავად სურს. თქვენი ყურადღება მისთვის მსოფლიოში ყველაზე დიდი ჯილდოა.') WHERE id = '2a98f756-8ee8-4fcc-b117-1adb344f61bd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენს ბავშვს უკვე შეუძლია, რამდენიმე წამით ხელები გაუშვას და დამოუკიდებლად იდგეს? ეს მისი თავდაჯერებულობის მწვერვალია. მიუხედავად იმისა, რომ ჯერ არ დადის, წონასწორობის შენარჩუნების ეს მომენტები მის ტვინში წონასწორობის ცენტრს (ვესტიბულურ აპარატს) ავითარებს. შეაქეთ, ხელები გაუწოდეთ და წაახალისეთ, რომ თქვენკენ ერთი ნაბიჯი გადმოდგას. ყოველი პატარა მცდელობა დიდი ნაბიჯის მომასწავებელია!') WHERE id = '94901ac5-33b9-4db0-bb43-734602fe969c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სიტყვა „არას“ გაგება და გამოცდა! როცა ეუბნებით „არა“, თქვენი ბავშვი უკვე ჩერდება და გიყურებთ, თუმცა ზოგჯერ იმავე მოქმედებას განზრახ იმეორებს. ასე ის საზღვრებსა და თქვენს რეაქციას ამოწმებს. გამოიჩინეთ მოთმინება და შეინარჩუნეთ სიმტკიცე. სახიფათო სიტუაციებში მიზეზი სერიოზული, მაგრამ მშვიდი ტონით აუხსენით. ის თქვენი სახის გამომეტყველებისა და ხმის ტონის მიხედვით სოციალური წესების სწავლას აგრძელებს.') WHERE id = '996a8930-2fe4-4558-a5f9-55c594d11cb6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილში „მოტორული გამოღვიძებები“: თქვენი ბავშვი შეიძლება ძილში მოულოდნელად წამოდგეს ან მძინარემ ხოხვა სცადოს. მისი ტვინი ღამით იმეორებს დღის განმავლობაში ნასწავლ მოძრაობებს. თუ არ ტირის, ნუ შეეხებით — აცადეთ, თავად იპოვოს მოხერხებული პოზა და ისევ დაიძინოს. თუ ტირის, მშვიდად მიუახლოვდით, სინათლის აუნთებლად დააწვინეთ და დამამშვიდებელი სიტყვები უთხარით. თქვენი გვერდით ყოფნაც საკმარისია, რომ კვლავ ჩაეძინოს.') WHERE id = '8706f5e6-ca0d-4a1d-8941-e5de02cc1dad';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 320 დღე შესრულდა! პირველ დაბადების დღემდე სულ რაღაც 45 დღე დარჩა. თქვენი ბავშვი უკვე მტკიცედ ავლენს საკუთარ ხასიათს, არჩევანსა და სურვილებს. დღეს მასთან ერთად იატაკზე დაწექით და უბრალოდ „მიბაძობანა“ ითამაშეთ: მან გამოსცეს ხმა და თქვენ გაიმეორეთ, თქვენ დაუკარით ტაში და მან გაიმეოროს. თქვენ მისთვის ყველაზე საიმედო ნავსაყუდელი და უახლოესი მეგობარი ხართ, დედიკო — სწორედ თქვენი გვერდიდან შეიმეცნებს ის სამყაროს!') WHERE id = '6671dafc-f72e-46f2-8504-39bf2769162e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უკვე მე-11 თვის ბოლო ათდღეულში შევდივართ. თქვენი ბავშვი ერთი ხელით რომ გიჭირავთ, უკვე საკმაოდ თავდაჯერებულად დადის თუ ჯერ კიდევ მხოლოდ დივნის კიდეს მიუყვება? ამ დღეებში მან შეიძლება წონასწორობის შესანარჩუნებლად ხელები გვერდებზე გაშალოს და ერთი-ორი დამოუკიდებელი ნაბიჯი გადადგას. ეს „ბალანსის“ მოძრაობები მის ტვინში წონასწორობის ცენტრს (ვესტიბულურ აპარატს) ავარჯიშებს. ნუ დააჩქარებთ — აცადეთ, საკუთარ შესაძლებლობებში სრულად დარწმუნდეს.') WHERE id = '223de2de-87c5-4289-96a9-08ae91456aa1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე იწყებს იმის გაგებას, თუ რისთვის გამოიყენება სხვადასხვა ნივთი (ფუნქციური თამაში). მაგალითად, სავარცხელს თავთან მიაქვს, ტელეფონს ყურთან იდებს ან ფინჯანს პირთან მიაქვს და თავს ისე აჩვენებს, თითქოს სვამს. ეს კოგნიტიურ განვითარებაში დიდი ნახტომია! მიეცით უსაფრთხო საყოფაცხოვრებო ნივთები და ამით მიბაძვის უნარის განვითარებაში დაეხმარეთ. ის სამყაროს თქვენზე დაკვირვებით სწავლობს, ამიტომ ეცადეთ, თქვენი ქცევით კარგი მაგალითი მისცეთ.') WHERE id = '1023ea09-5e35-4d01-b1e5-ee2d0049110b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თამაში „ობიექტის მუდმივობაზე“: თქვენმა ბავშვმა უკვე იცის, რომ თუ სათამაშოს ჭურჭელში ჩადებთ და ზემოდან დააფარებთ, ის არ გამქრალა. ითამაშეთ მასთან დამალობანას უფრო რთული ვარიანტები. მაგალითად, სათამაშო ორი სხვადასხვა საფარიდან ერთ-ერთის ქვეშ დამალეთ და დააკვირდით, როგორ იპოვის. ეს ავითარებს როგორც მის მეხსიერებას, ისე ყურადღების კონცენტრირების უნარს. როცა ამოცანას ამოხსნის, დიდი სიხარულით შეაქეთ.') WHERE id = '8ef86f1c-b50a-4f76-b6a2-1deccffcaf49';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლობა კვებისას: თქვენს ბავშვს უკვე სურს, კოვზი მთლიანად დამოუკიდებლად დაიჭიროს და პირთან მიიტანოს. დიახ, საკვების დიდი ნაწილი იატაკსა და წინსაფარზე აღმოჩნდება, მაგრამ ეს ნატიფი მოტორიკისა და ხელისა და თვალის კოორდინაციის ერთ-ერთი ყველაზე მნიშვნელოვანი ვარჯიშია. მიეცით მისთვის მოსახერხებელი სილიკონის ან სქელსახელურიანი კოვზი. ამავდროულად, თქვენც შეგიძლიათ მეორე კოვზით დაეხმაროთ. ეს ნამდვილი „გუნდური მუშაობაა“!') WHERE id = '7871caf2-41cf-4c3f-b2a8-4d60c9c5acd7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში "ჟარგონი" (თავის ენაზე ლაპარაკი) უკვე უფრო რთულ ხასიათს იძენს. ბავშვი ხმას ისე უწევს, თითქოს კითხვას სვამს, ან ხელებს ისე ამოძრავებს, თითქოს რაღაცას ხსნის. ეს იმაზე მიუთითებს, რომ ის მეტყველების ინტონაციას (პროსოდიას) სწავლობს. ყურადღებით მოუსმინეთ და დიალოგი განაგრძეთ სიტყვებით: "ჰო, მართლა? ძალიან საინტერესოა!" თქვენი ასეთი დაინტერესება მასში კომუნიკაციის სურვილს წარმოუდგენლად გაზრდის.') WHERE id = '79994c5e-b38e-4456-bddc-86c51746ecdb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ოჯახურ სუფრასთან კვების ინტეგრაცია: თქვენს ბავშვს უკვე შეუძლია, თითქმის ყველაფერი თქვენთან ერთად მიირთვას (იმ პირობით, რომ საკვები უმარილო და წიწაკის გარეშე იქნება). მიეცით მას საკუთარი კოვზი და ჭიქა, რომლიდანაც დამოუკიდებლად დალევს. დამოუკიდებლად ჭამის შესაძლებლობა არა მხოლოდ მის მოტორულ უნარებს აძლიერებს, არამედ ჭამას სასიამოვნო სოციალურ აქტივობადაც აქცევს. სუფრასთან ერთად ჯდომა საუკეთესო მაგალითია მისი სამომავლო კვებითი ჩვევების ჩამოსაყალიბებლად.') WHERE id = '4a48790e-7f13-40fe-9b6e-dd306e1f2a08';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"სივრცითი მეხსიერება" და ძიება: თქვენს ბავშვს უკვე შეუძლია, რამდენიმე წუთის შემდეგაც გაიხსენოს, სად დამალეთ მისი საყვარელი სათამაშო. ითამაშეთ მასთან უფრო რთული "დამალობანა". მაგალითად, სათამაშო გადასაფარებლის ქვეშ დამალეთ და დააკვირდით, როგორ იპოვის. ეს მის მეხსიერებასაც აუმჯობესებს და ყურადღების კონცენტრირების უნარსაც. როცა ამოცანას ამოხსნის, დიდი ენთუზიაზმით შეაქეთ.') WHERE id = 'f29f91f0-dc1e-44f0-842d-ac8ae1283e19';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ უნარებში "გაზიარების" მცდელობები: ბავშვმა შეიძლება ხელში დაჭერილი სათამაშო ისე გამოგიწოდოთ, თითქოს "გაძლევთ", შემდეგ კი უკან წაიღოს. ეს მისი პირველი ხუმრობები და სოციალური მანიპულაციის მცდელობებია! მის ამ "თამაშს" სიცილითა და სიხარულით უპასუხეთ. სიცილი და ერთად მხიარულება თქვენ შორის ემოციურ კავშირს წარმოუდგენლად აძლიერებს და ბავშვს იუმორის გრძნობის საფუძველს უყალიბებს.') WHERE id = 'ffe2c8a7-1840-4df7-a9fa-47dc0268105b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"პინცეტური მოჭიდება" (pincer grasp) უკვე სრულყოფილად აქვს განვითარებული. მას იატაკიდან ყველაზე წვრილი ძაფის ან პატარა ნამცეცის აღებაც კი ადვილად შეუძლია. ამ უნარის გასავითარებლად შესთავაზეთ კარგად მოხარშული პარკოსნები ან ხაჭოს პატარა ნაჭრები. თუმცა ფრთხილად იყავით: ეს მოქნილობა იმასაც ნიშნავს, რომ მას შეუძლია ნებისმიერი სახიფათო წვრილი ნივთი იმავე სისწრაფით ჩაიდოს პირში. უსაფრთხოება მუდმივად უნდა აკონტროლოთ!') WHERE id = 'c1101eea-3caa-455b-a661-c216864cdeb4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მუსიკა და რიტმი: თქვენი ბავშვი მუსიკის გაგონებისას უკვე აყოლებს სხეულს ან ტაშს უკრავს? მუსიკის რიტმის შეგრძნება მისი სმენისა და სხეულის კოორდინაციის განვითარების ნიშანია. იცეკვეთ მასთან ერთად და ტაში დაუკარით. ეს არა მხოლოდ მის ფიზიკურ აქტივობას ზრდის, არამედ ესთეტიკური გემოვნებისა და რიტმის შეგრძნების ჩამოყალიბებასაც უწყობს ხელს. სცადეთ, სიმღერების სიტყვები ერთად გაიმეოროთ.') WHERE id = '3a1cdf9f-7bc8-427f-b1e3-a23a8f78241b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ცხოველების ხმების“ პერიოდი დადგა! თქვენმა ბავშვმა შეიძლება უკვე თავისებურად დაიწყოს პასუხის გაცემა ისეთ კითხვებზე, როგორებიცაა: „როგორ ყეფს ძაღლი?“ და „რა ხმას გამოსცემს კატა?“. ამ ეტაპზე ბგერების მიბაძვის უნარი პიკს აღწევს. განაგრძეთ ეს თამაშები ცხოველების სურათებიანი წიგნების დათვალიერებისას. ბგერების მიბაძვა სამეტყველო აპარატს (ენას, ტუჩის კუნთებს) მომავალში რთული სიტყვების წარმოთქმისთვის ამზადებს.') WHERE id = 'cdc84d0d-886f-4a27-bf41-fd9c5be5503c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პინცეტური ჩავლება“ (pincer grasp) უკვე იმდენად დახვეწილია, რომ ბავშვს იატაკზე დაგდებული უწვრილესი ძაფის ან პატარა ნამცეცის აღებაც კი მარტივად შეუძლია. ამ უნარის გამოსაცდელად შეგიძლიათ კარგად მოხარშული პარკოსნები (მუხუდო, ოსპი) შესთავაზოთ. თუმცა გახსოვდეთ: ჩვევა, რომ ყველა ნაპოვნი პატარა ნივთი პირში ჩაიდოს, ასევე პიკს აღწევს. იატაკის სისუფთავე და ბავშვის გარშემო წვრილი ნივთების არარსებობა უსაფრთხოების უმნიშვნელოვანეს წესად რჩება.') WHERE id = '03beae21-c620-431a-a745-a2cb5663e55d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური თამაშები რთულდება: თქვენმა ბავშვმა თამაში „მომეცი–გამომართვი“ უკვე ახალ საფეხურზე გადაიყვანა. მან შეიძლება სათამაშო მოგცეთ და მაშინვე უკან მოგთხოვოთ, ან განზრახ დამალოს, როცა ეუბნებით „მომეცი“. ეს მისი პირველი „ხუმრობებია“. იუმორის ამ გამოვლინებას სიცილით უპასუხეთ. სიცილი და ერთად გართობა თქვენს შორის ემოციურ კავშირს საოცრად აძლიერებს.') WHERE id = '3339985d-3305-4eb1-9ee4-eac876362604';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ძილის რეჟიმი და სიფხიზლის პერიოდი: მე-11 თვეში ბავშვებს შეიძლება დღის განმავლობაში 2 ძილიდან 1 ძილზე გადასვლის (nap transition) ნიშნები გამოუვლინდეთ, თუმცა ჯერ ნუ იჩქარებთ. ბავშვების უმეტესობას 14-15 თვემდე დღისით 2-ჯერ ძილი სჭირდება. თუ ბავშვს დილით ჩაძინება უჭირს, სცადეთ სიფხიზლის პერიოდის ოდნავ გახანგრძლივება (დაახლოებით 3 - 3.5 საათამდე). კარგად დასვენებული ბავშვი ახალ უნარებს მეტი მონდომებით სწავლობს.') WHERE id = 'db42c776-feed-4c94-906a-857e9999bca9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცის აღქმა“: თქვენს ბავშვს უკვე მოსწონს ყუთებში ჩახედვა, თავსახურების გახსნა-დახურვა და ნივთების ერთმანეთში მოთავსება. მიეცით სხვადასხვა ზომის პლასტმასის ჭურჭელი. როდესაც აღმოაჩენს, რომ პატარა ჭურჭელი დიდში თავსდება, მის ტვინში რთული მათემატიკური და ლოგიკური კავშირები ყალიბდება. ეს შეიძლება მარტივად ჩანდეს, თუმცა სინამდვილეში დიდი აღმოჩენაა.') WHERE id = 'c317d6dc-6305-468b-bef4-37407eacbfe2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 330 დღე გავიარეთ! პირველ დაბადების დღემდე სულ ერთი თვე დარჩა. თქვენი ბავშვი უკვე საკუთარ ნებას ავლენს: თუ ჩაცმა არ სურს, ფეხებს ჭიმავს, საყვარელი საკვების დანახვისას კი ტაშს უკრავს. „პიროვნების“ ეს ნიშნები ზოგჯერ შეიძლება დამღლელი იყოს, თუმცა სინამდვილეში ისინი მისი ჯანსაღი ფსიქოლოგიური განვითარების მაჩვენებელია. თქვენ საოცარი გზა გამოიარეთ, დედა!') WHERE id = 'c209d7a9-28c5-4bcf-a9ab-ed5e68cd5e38';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-12 თვეში! პირველ დაბადების დღემდე სულ რაღაც 30 დღე დარჩა. თქვენი ბავშვი უკვე სრულიად განსხვავებულ პატარა პიროვნებად ჩამოყალიბდა. ის თქვენს მოქმედებებს უბრალოდ კი აღარ იმეორებს, არამედ მათ მნიშვნელობასაც ხვდება. ამ თვეში თავდაჯერებულობის გასაზრდელად მარტივი არჩევანის გაკეთების საშუალება მიეცით. მაგალითად: „ამ მაისურის ჩაცმა გინდა თუ ამის?“ ეს გადაწყვეტილების მიღების უნარის პირველ საფუძვლებს უყრის.') WHERE id = 'fd9ad5fc-02c4-489e-8c2f-e2ab1ee56a7e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თუ თქვენმა ბავშვმა უკვე დაიწყო დამოუკიდებლად სიარული, სახლში უსაფრთხოების ზომები „ექსტრემალურ“ დონემდე გაამკაცრეთ. თუ ჯერ არ დადის, არ ინერვიულოთ — ბევრი ჯანმრთელი ბავშვი 15 თვემდე არ იწყებს სიარულს. სიარულის დაწყების დრო ინტელექტის მაჩვენებელი არ არის. მთავარია, მას შეეძლოს ფეხზე დგომა და გარემოს შესწავლის მოტივაცია ჰქონდეს.') WHERE id = 'e0fb9df8-7033-4ff7-a1b1-5c3d3e6afa83';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „გააზრებული სიტყვები“: იყენებს თქვენი ბავშვი უკვე სათანადო სიტუაციაში ისეთ მარტივ სიტყვებს, როგორებიცაა „წყალი“, „მომეცი“, „მოდი“? მას უკვე შეუძლია, საკუთარი სურვილი მხოლოდ ერთი სიტყვით ან ჟესტით გაგაგებინოთ. თქვენ კი განავრცეთ მისი ეს მცდელობები: „დიახ, წყლის დალევა გინდა? აი, ეს შენი ლურჯი ჭიქაა“. ეს მის ტვინში სიტყვებს შორის გრამატიკული კავშირების ჩამოყალიბებას უწყობს ხელს.') WHERE id = 'c5cc511f-2fea-4b22-b8e8-1b77f482261c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვების მხრივ ბავშვი სრულად ერთვება ოჯახის საერთო სუფრაში. მას უკვე შეუძლია, თქვენთან ერთად მიუჯდეს სუფრას და თითქმის იგივე საკვები მიირთვას. ეს მისი სოციალიზაციისთვის ძალიან მნიშვნელოვანია. მიეცით საკუთარი ჭურჭელი და დამოუკიდებლად ჭამის შესაძლებლობა. მისთვის ჭამა ვალდებულება კი არა, საინტერესო და გემრიელი აქტივობა უნდა იყოს.') WHERE id = '8b39909f-51d2-4504-9985-513b605dc042';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„პინცეტური მოჭიდება“ (pincer grasp) უკვე სრულყოფილია, წვრილი მოტორიკა კი უფრო რთული თამაშების შესაძლებლობას იძლევა. აჩვენეთ, როგორ დააწყოს კუბები ერთმანეთზე, როგორ აასხას ძაფზე დიდი მძივები (თქვენი მეთვალყურეობით!) ან როგორ ააწყოს მარტივი თავსატეხები (puzzle). ეს თამაშები წარმოუდგენლად ავითარებს როგორც ყურადღების კონცენტრაციას, ისე ხელისა და თვალის კოორდინაციას.') WHERE id = 'e3225412-1384-48a0-aa55-7ca8a5ef8659';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ურთიერთობაში „ემპათიის“ პირველი ნიშნები ჩნდება. როცა მოწყენილი ხართ ან ტირით, ბავშვი შეიძლება თქვენთან მოვიდეს, შეგეხოთ ან თავისი სათამაშო მოგცეთ. ეს აჩვენებს, რომ ის სხვა ადამიანების გრძნობების გაგებას იწყებს. მის ამ მზრუნველ ქმედებებს სიყვარულით უპასუხეთ. ეს მომავალში ემოციურად ჯანსაღ პიროვნებად ჩამოყალიბებაში დაეხმარება.') WHERE id = '31745949-5ef4-444a-8a69-ec5929c0332b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ უნარებში „ხუმრობა“: ბავშვი განზრახ გაწვდით სათამაშოს, შემდეგ კი მაშინვე უკან მიაქვს და იცინის? ეს მიანიშნებს, რომ მას იუმორის გრძნობა და სოციალური ურთიერთქმედების უნარები უვითარდება. ენთუზიაზმით აჰყევით მის ამ „თამაშს“. ერთად სიცილი თქვენს შორის ემოციურ კავშირს აძლიერებს და ბავშვს ჯანსაღ თავდაჯერებას უყალიბებს.') WHERE id = 'f977f0c6-061a-4189-bf33-4e6656c97984';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებისას შეიძლება „პრეტენზიულობა“ დაიწყოს. ბავშვმა შეიძლება დღეს კატეგორიულად უარი თქვას საკვებზე, რომელიც გუშინ მიირთვა. ამით ის უკვე საკუთარ ნებას გამოხატავს. ნუ აიძულებთ ჭამას, თუმცა ცოტა ხნის შემდეგ მისთვის არასასურველი საკვები განსხვავებული ფორმით კვლავ შესთავაზეთ. მთავარია, სუფრასთან დაძაბულობა არ შეიქმნას. ჭამის დრო მისთვის სასიამოვნო რიტუალად უნდა დარჩეს.') WHERE id = 'eb15bd6a-93d6-4986-92eb-7294c9a935c2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში „კონსტრუირების“ უნარი: ბავშვი უკვე ცდილობს, კუბები ერთმანეთზე დააწყოს და პატარა „კოშკები“ ააშენოს. ჯერჯერობით კოშკი შეიძლება მალე დაინგრეს, მაგრამ ეს ხელისა და თვალის კოორდინაციისა და ყურადღების კონცენტრაციის შესანიშნავი ვარჯიშია. მიეცით მას სხვადასხვა ზომისა და ფერის კუბები. დანგრეულ კოშკზე ერთად გაიცინეთ და სიტყვებით „მოდი, კიდევ ერთხელ ავაშენოთ!“ მოტივაცია მიეცით.') WHERE id = '7a4a5884-cfbe-4717-937f-7483274cf1dd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცის აღქმა“ და მეხსიერება: ბავშვმა უკვე იცის, სად არის დამალული მისი საყვარელი სათამაშო და მის საპოვნელად დაბრკოლებებს (მაგალითად, ბალიშს) გვერდზე სწევს. ეს პრობლემების გადაჭრის უნარის განვითარებაზე მიანიშნებს. მასთან ერთად დამალობანას უფრო რთული ვარიანტები ითამაშეთ. დაბრკოლებების გადალახვა მის ტვინში ლოგიკურ კავშირებს აძლიერებს.') WHERE id = '87a69c40-9317-47d9-89ca-fad250ba27cf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თვითშემეცნება და დამოუკიდებლობა: ბავშვი ჩაცმისას უკვე ცდილობს თქვენს „დახმარებას“? მაგალითად, ფეხს წინდისკენ იშვერს ან ხელს მაისურის სახელოში ყოფს. მხარი დაუჭირეთ ამ მცდელობებს და შეაქეთ. სიტყვები „რა ლამაზად ჩაიცვი!“ მნიშვნელოვნად დაეხმარება მას, აღიქვას თავი ცალკე პიროვნებად და გაუძლიერებს დამოუკიდებლობის სურვილს.') WHERE id = '82ceaad9-caa0-45d0-ae94-6fb25e59d3dc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კბილების ამოჭრის პერიოდის ბოლო ეტაპები (პირველი წლისთვის): 1 წლის ასაკთან მიახლოებულ ბავშვთა უმეტესობას უკვე 4-8 კბილი აქვს. ღრძილები შეიძლება კვლავ შეშუპდეს ან ატკივდეს. საღეჭად მიეცით გრილი ბოსტნეულის ნაჭრები (სტაფილო, კიტრი – მხოლოდ მეთვალყურეობის ქვეშ!). ღეჭვა არა მხოლოდ ღრძილებს უკეთებს მასაჟს, არამედ ყბის კუნთებსაც აძლიერებს.') WHERE id = '3fe62d47-f929-4c62-b0de-6bc80e34943b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ჭიქიდან წყლის სმის ჩვევა უკვე სრულად უნდა იყოს ჩამოყალიბებული. დროა, საწოვარიანი ბოთლის გამოყენებას თანდათან შეაჩვიოთ. ბოთლის ხანგრძლივად გამოყენებამ შესაძლოა უარყოფითად იმოქმედოს კბილების განლაგებასა და მეტყველების განვითარებაზე. შესთავაზეთ მას საინტერესო, ფერადი სასწავლო ჭიქა ან ჩვეულებრივი ღია ჭიქა. დამოუკიდებლად დალევა მას თავისუფლებისა და დამოუკიდებლობის დიდ შეგრძნებას მიანიჭებს.') WHERE id = '38eafb23-62e2-4538-a93f-213f32e35986';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცითი მეხსიერება“ და წესრიგი: თქვენმა ბავშვმა უკვე იცის, სად ინახება მისი სათამაშოები. თამაშის დასრულების შემდეგ ისინი ერთად დაალაგეთ. წაახალისეთ სიტყვებით: „მოდი, დათუნია თავის სახლში (ყუთში) დავაბრუნოთ“. ეს მას პასუხისმგებლობის გრძნობას უყალიბებს და ეხმარება გააცნობიეროს, რომ თითოეულ ნივთს თავისი ადგილი აქვს. წესრიგისა და დისციპლინის ჩვევები სწორედ ამ თვეებში იწყებს ჩამოყალიბებას.') WHERE id = 'c880f2e4-5f85-403c-b1f7-b1634ed3e06b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილი და ფხიზლად ყოფნის პერიოდი: თქვენმა ბავშვმა შესაძლოა დღის ძილის ხანგრძლივობა შეამციროს ან ძილის ერთ-ერთი მონაკვეთი გამოტოვოს. თუ დღის განმავლობაში ერთხელ დაძინების შემთხვევაშიც თავს კარგად გრძნობს, რეჟიმი ამის მიხედვით მოარგეთ. თუმცა 1 წლის ბავშვების უმეტესობას ჯერ კიდევ ორჯერ დაძინება სჭირდება. განაგრძეთ დაღლილობის ნიშნებზე დაკვირვება; კარგად დასვენებული ბავშვი უფრო ბედნიერი და სწავლისადმი მეტად განწყობილია.') WHERE id = '9898d949-3ccb-4708-a982-1de8127dfcfd';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 340 დღე გავიარეთ! პირველ დაბადების დღემდე სულ რაღაც 25 დღე დარჩა. თქვენი ბავშვი უკვე პატარა პიროვნებაა – თავისი გემოვნებით, ხასიათითა და საყვარელი თამაშებით. დღეს მასთან ერთად იატაკზე წამოწექით და უბრალოდ მის მიერ არჩეული თამაში ითამაშეთ. მის სამყაროში თქვენი ჩართვა მისთვის ყველაზე დიდი საჩუქარია. თქვენ შესანიშნავი წელი გაიარეთ, დედიკო!') WHERE id = 'c4c0444c-fad1-4344-8a31-c99f7a9878d9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დაბადების დღემდე სულ რაღაც 25 დღე დარჩა! თუ თქვენი ბავშვი უკვე დამოუკიდებლად დგამს რამდენიმე ნაბიჯს, ეს ნიშნავს, რომ მისი წონასწორობის ცენტრი კარგად არის განვითარებული. თუ ჯერ არ დადის, ნუ აიძულებთ ხელებით დაჭერილს სიარულს. ამან შესაძლოა მის ხერხემალს ზედმეტი დატვირთვა შეუქმნას. უმჯობესია, მის წინ დადგეთ, ხელები გაშალოთ და წაახალისოთ, თქვენკენ წამოვიდეს. თქვენი თავდაჯერებული მზერა მას უდიდეს გამბედაობას მატებს.') WHERE id = '8681364a-206a-4e87-acfa-4a44f4404ec8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „რეცეპტული ენის“ (გაგების უნარის) განვითარება: თქვენს ბავშვს უკვე ესმის მარტივი მითითებები. როდესაც ეუბნებით: „ბურთი მომეცი“, „აქ მოდი“, „ქუდი აიღე“, შეუძლია მათი შესრულება? მიუხედავად იმისა, რომ ჯერ ყველა სიტყვის წარმოთქმა არ შეუძლია, მის გონებაში უკვე სიტყვების დიდი მარაგია დაგროვილი. განაგრძეთ მასთან საუბარი და სიტყვებით აღწერეთ თითოეული მოქმედება. ეს მისი მომავალი მეტყველების მყარი საფუძველია.') WHERE id = 'b0d73932-0d82-458c-b55b-ddc718662495';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-2 წელს! პირველი დაბადების დღის მღელვარება უკვე უკან დარჩა, თუმცა ნამდვილი თავგადასავალი ახლა იწყება. თქვენს პატარას უკვე ოფიციალურად აქვს „ახლად ფეხადგმული ბავშვის“ (toddler) სტატუსი. ამ თვიდან მას სამყაროს უფრო მეტად „ფეხზე მდგომს“ შესწავლა მოუნდება. მისი მოძრაობითი აქტივობის ზრდასთან ერთად ენერგიის საჭიროებაც იცვლება. თუმცა გახსოვდეთ, დედის რძე ან ხელოვნური ნარევი კვლავ შეიძლება მისი კვების რაციონის მნიშვნელოვანი ნაწილი იყოს.') WHERE id = '165b6f1d-3374-4097-b9a4-8e514ea4fdd0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სიარულის უნარი უმტკიცდება! თუ თქვენი პატარა უკვე დამოუკიდებლად დადის, შეამჩნევთ, რომ მისი ნაბიჯები ჯერ კიდევ ოდნავ „ბარბაცაა“, ხოლო ფეხებს ფართოდ დგამს. ეს წონასწორობის შესანარჩუნებელი ბუნებრივი მექანიზმია. სახლში შეძლებისდაგვარად ფეხშიშველი ატარეთ. ეს ტერფის სწორად ჩამოყალიბებისა და ტვინისთვის ზედაპირის ტექსტურის შესახებ მეტი ინფორმაციის მიწოდების საუკეთესო საშუალებაა.') WHERE id = 'c278e801-c9bd-49de-b0fb-e7e23f4f7d75';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '1 წლის შემდეგ ბავშვებს მადა შეიძლება უეცრად შეუმცირდეთ. ამას „ფიზიოლოგიური ანორექსია“ ეწოდება. მიზეზი მარტივია: ზრდის ტემპი პირველ წელთან შედარებით ნელდება და ბავშვს იმდენი კალორია აღარ სჭირდება, რამდენიც ადრე. ნუ ეცდებით მის იძულებით გამოკვებას. მთავარია, შეთავაზებული საკვები ხარისხიანი და მრავალფეროვანი იყოს. მან თავად უნდა ისწავლოს, განსაზღვროს, რამდენი საკვები სჭირდება.') WHERE id = 'dd5c13fb-e41c-4d49-a21d-c17c38691c1f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „ერთსიტყვიანი წინადადებების“ პერიოდი იწყება. თქვენი პატარა უკვე ერთი სიტყვით მთლიან აზრს გამოხატავს. მაგალითად, „ტა-ტა“ შეიძლება ნიშნავდეს როგორც „გარეთ წავიდეთ“, ისე „ფეხსაცმელი ჩამაცვი“. უპასუხეთ მისი ერთსიტყვიანი ნათქვამის გაფართოებით: „დიახ, ახლა ფეხსაცმელს ჩავიცვამთ და ეზოში გავალთ (ტა-ტა)“. ეს მას წინადადებების აგების უნარს სწრაფად განუვითარებს.') WHERE id = '4f614506-d560-4d40-bad9-c0ba7ee808d8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ!“ ეტაპი სულ უფრო ძლიერდება. როდესაც თქვენი პატარა ხელების დაბანას, კიბეზე ასვლას ან ჩაცმას ცდილობს, შეიძლება თქვენს დახმარებაზე უარი თქვას. ეს სიჯიუტე კი არა, დამოუკიდებლობისკენ სწრაფვაა. ყველა უსაფრთხო სიტუაციაში მიეცით მას „ნებადართული თავისუფლება“. იმის დანახვა, რომ რაღაც თავად შეუძლია, მისი თვითშეფასების (self-esteem) ჩამოყალიბების უმნიშვნელოვანესი ფაქტორია.') WHERE id = '884b93ff-cafb-4926-88b8-45e9267f348c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური უნარების განვითარებისას „პარალელური თამაშის“ ეტაპი იწყება. თუ თქვენს პატარას თანატოლებთან მიიყვანთ, შეამჩნევთ, რომ ის სხვა ბავშვებთან ერთად კი არა, მათ გვერდით თავისთვის თამაშობს. ეს 1-2 წლის ბავშვებისთვის სრულიად ნორმალურია. მათ ჯერ არ იციან გაზიარება და ერთად თამაში, თუმცა ერთმანეთზე დაკვირვებით ბევრს სწავლობენ. სოციალიზაციისთვის კვლავ ატარეთ ბავშვი პარკებსა და სათამაშო ჯგუფებში.') WHERE id = 'e23b48b6-63ac-4bcc-9b95-51974a62ac74';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლად ჭამის ჩვევა უკვე უნდა მყარდებოდეს. დიახ, ბავშვს ჯერ კიდევ შეიძლება კოვზი უკუღმა ეჭიროს ან საჭმლის ნახევარი იატაკზე დაჰყაროს, მაგრამ ის, რომ თავად ცდილობს ჭამას, მისი თავდაჯერებულობისთვის ყველაფერზე მნიშვნელოვანია. მიეცით მისთვის მოსახერხებელი ღრმა თასი და რეზინისტარიანი კოვზი. მოთმინება გამოიჩინეთ — სულ მალე ის საოჯახო სუფრის ყველაზე აქტიური და „დამოუკიდებელი“ წევრი გახდება.') WHERE id = 'd42878d7-1b6d-456a-b198-9e59777aacf0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„განშორების შფოთვამ“ (Separation anxiety) 1 წლის ასაკისთვის შესაძლოა კვლავ პიკს მიაღწიოს. როცა ოთახიდან გადიხართ, ბავშვის ხმამაღალი ტირილი თქვენდამი მისი ძლიერი მიჯაჭვულობისა და ჯერ კიდევ არსებული შიშის — „დედა წავა და აღარ დაბრუნდება“ — გამოხატულებაა. ყოველთვის უთხარით, სად მიდიხართ და როდის დაბრუნდებით (მაშინაც კი, თუ მხოლოდ სხვა ოთახში გადიხართ). თქვენი გულწრფელობა მას უსაფრთხოებისა და ნდობის განცდის აღდგენაში დაეხმარება.') WHERE id = 'bf1abd20-6eb2-41e7-85ec-e1c3f46808a3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკის ახალი მიღწევა: „თავსახურის გახსნა და დახურვა“. თქვენს ბავშვს უკვე სიამოვნებს ყუთებისთვის თავსახურის მოხსნა და ბოთლების თავსახურების დატრიალების მცდელობა. ეს მაჯისა და თითების კუნთების მაღალ კოორდინაციას მოითხოვს. მიეცით სხვადასხვა ზომის პლასტმასის ჭურჭელი და საშუალება, ერთმანეთში ჩააწყოს. ეს მისი პირველი მათემატიკური/ლოგიკური აზროვნების სავარჯიშოცაა.') WHERE id = '4e49e60c-de35-4a74-ac4f-e95ac56a3410';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალური წესების შესწავლა: თქვენი ბავშვი უკვე გააზრებულად იყენებს ისეთ ჟესტებს, როგორებიცაა „ნახვამდის“ (ხელის დაქნევა), „კოცნის გაგზავნა“ ან „ხელის ჩამორთმევა“. ეს საზოგადოებაში შესასვლელად მისი პირველი „ვიზებია“. მის ასეთ დადებით ქცევებს ყოველთვის სიხარულით შეხვდით. თქვენი რეაქცია ბავშვს ეხმარება გაიგოს, რომელი ქცევაა „კარგი“.') WHERE id = '21db9180-06af-489e-83b0-28bdcc1730d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ხვალ თქვენი ბავშვი ზუსტად 1 წლის ხდება! დღეს გაიხსენეთ ბოლო 12 თვის თავგადასავალი: პირველი ღიმილი, პირველი კბილი, პირველი ხოხვა... რაც უნდა რთული ყოფილიყო, თქვენ ეს შეძელით! თქვენი ბავშვი უკვე აღარ არის სრულიად უმწეო ჩვილი — ის საკუთარი ხასიათისა და სურვილების მქონე პატარა ადამიანია. ამაღამ, დაძინებისას, საკუთარ თავსაც უთხარით „ყოჩაღ“. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '74f434ee-a5bf-498f-af06-34cc0939c106';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ! გილოცავთ პირველ დაბადების დღეს! 🎂 თქვენი ბავშვი უკვე ოფიციალურად 1 წლისაა. ეს წელი როგორც მის, ისე თქვენს ცხოვრებაში უდიდესი ცვლილებების წელი იყო. ახლა ის უკვე „Toddler“-ია (ბავშვი, რომელმაც სიარული დაიწყო) და მზადაა, იაროს, ილაპარაკოს და სამყარო დაიპყროს. აღნიშნეთ ეს დღე სტრესის გარეშე — მხოლოდ მისი ღიმილითა და თქვენი სიყვარულით. გზა მუდამ ხსნილი, ცხოვრება კი ბედნიერი და ბარაქიანი გქონოდეთ!') WHERE id = '56917d9b-b358-4310-b651-30aecbaf8560';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სიტყვა „არას“ ძალა: თქვენმა ბავშვმა შეიძლება უკვე გააპროტესტოს თქვენი „არა“, იატაკზეც კი დაწვეს და ატირდეს (პირველი ტანტრუმები). ეს იმიტომ ხდება, რომ მან ჯერ არ იცის, როგორ მართოს საკუთარი ემოციები. შეინარჩუნეთ სიმშვიდე, მის სიმაღლეზე ჩადით და მისი გრძნობები სიტყვებით გამოხატეთ: „ახლა გაბრაზებული ხარ, რადგან სათამაშო არ მოგეცი, მესმის“. თქვენი სიმშვიდე მისთვის საუკეთესო გაკვეთილია, რომელიც ემოციურ სტაბილურობას ასწავლის.') WHERE id = '627b69c9-1a97-4379-b790-7b2e4d39bfb2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 350 დღე უკან მოვიტოვეთ! პირველ დაბადების დღემდე სულ რაღაც 15 დღე დარჩა! დღეს გადახედეთ პირველი თვეების ფოტოებს და დაფიქრდით, რამხელა გზა გაიარეთ. ის უმწეო ჩვილი ახლა საკუთარი ხასიათის მქონე პატარა პიროვნებად იქცა. დატკბით ამ 15 დღით სტრესის გარეშე — უბრალოდ გაატარეთ დრო მასთან. თქვენ საოცარი წელი გამოიარეთ, დედა!') WHERE id = '8417d81b-7389-4675-845a-7c49bcb07801';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'პირველ დაბადების დღემდე სულ რაღაც 10 დღე დარჩა! შეუძლია თქვენს ბავშვს უკვე წიგნის ფურცლების გადაშლა (ჯერჯერობით რამდენიმე ფურცლის ერთად)? ეს როგორც მისი ნატიფი მოტორიკის, ისე წიგნებისადმი ინტერესის მაჩვენებელია. განაგრძეთ მისთვის დიდი და ფერადი სურათების მქონე წიგნების კითხვა. თუ სურათზე გამოსახულ ძაღლს შეხედავთ და ჰკითხავთ: „ჰაფ-ჰაფი სად არის?“, ხოლო ის თითით მიგანიშნებთ, ეს მისი აღქმის უნარის შესანიშნავი გამოვლინებაა.') WHERE id = '3e342e5d-4541-4b82-ae58-b2cc792f784b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი მუსიკის გაგონებისას უკვე აყოლებს სხეულს, მუხლებს ხრის და შლის და „ცეკვავს“? მუსიკის რიტმის შეგრძნება მიუთითებს, რომ მისი სმენა და სხეულის კოორდინაცია სულ უფრო იხვეწება. მასთან ერთად დაუკარით ტაში და აჰყევით რიტმს. ეს მხიარული წუთები მის ტვინში ბედნიერების ჰორმონების დონეს ზრდის და თქვენ შორის კავშირს კიდევ უფრო აძლიერებს.') WHERE id = '824b4580-ab45-4cbc-9104-e999a9e050cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე სრულად ესმის „საგნების დანიშნულება“. სავარცხლის დანახვისას ის თავთან მიაქვს, ფეხსაცმლის დანახვისას კი ფეხზე მორგებას ცდილობს. მას უკვე ესმის, რომ ნივთები მხოლოდ სათამაშოები არ არის და თითოეულ მათგანს თავისი დანიშნულება აქვს. მიეცით საშუალება, უსაფრთხო საყოფაცხოვრებო ნივთებით (პლასტმასის ჭურჭელი, სუფთა ჯაგრისები) ითამაშოს. ეს ყოველდღიურ ცხოვრებასთან მის შეგუებას დააჩქარებს.') WHERE id = '40fb0a95-63d4-4ada-888b-1faf14ddd19d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „გამეორების“ პერიოდი დაიწყო. ბავშვმა შეიძლება თქვენ მიერ ნათქვამი სიტყვების ბოლო მარცვლების გამეორება სცადოს. მაგალითად, როცა თქვენ ამბობთ „ვაშლი“, მან შეიძლება თქვას „ლი“. ასე ის მეტყველების აპარატს აქტიურად ავარჯიშებს. ყოველთვის მკაფიოდ და სწორი გამოთქმით ესაუბრეთ. „ბავშვის ენაზე“ (ბუბუ, ნიამ-ნიამ და სხვ.) საუბრის ნაცვლად, საგნებს ნამდვილი სახელები უწოდეთ — ეს მისი ლექსიკური მარაგის სწორად ჩამოყალიბებას უწყობს ხელს.') WHERE id = '40321163-794d-42e6-bcde-127caef60c13';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკის დაუფლება: თქვენს ბავშვს უკვე შეუძლია ფანქარი ან ფუნჯი დაიჭიროს (ჯერჯერობით მთელი ხელისგულით) და ქაღალდზე "ჯღაბნოს". ეს მისი თვალისა და ხელის კოორდინაციის ახალი ეტაპია. მიეცით დიდი ზომის ფურცლები და ბავშვებისთვის უსაფრთხო ფერადი ფანქრები. ეს აქტივობა მისი შემოქმედებითი წარმოსახვის პირველ მარცვლებსაც თესავს. ყოველთვის მეთვალყურეობის ქვეშ გყავდეთ, რომ კედლები "ხელოვნების ნიმუშებად" არ იქცეს!') WHERE id = '0b6473c4-31af-4b7f-87fd-2d01229d5be8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ძილის რეჟიმის ცვლილება: მე-13 თვეში ბევრ ბავშვს დღის ორი ძილიდან ერთზე გადასვლა სურს. თუ მას დილით დაძინება უჭირს ან შუადღის ძილი ძალიან გვიან უწევს, რეჟიმის შეცვლის დროა. დღის ერთ ძილზე გადასვლას შეიძლება რამდენიმე კვირა დასჭირდეს და ამ გარდამავალ პერიოდში ბავშვი საღამოობით ცოტა უფრო "მოუსვენარი" იყოს. გამოიჩინეთ მოთმინება — ახალი რეჟიმი მალე ორივესთვის უფრო კომფორტული გახდება.') WHERE id = '04380a78-48ac-47f1-b32c-6d6f9bfeb4d4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უსაფრთხოება და "სიმაღლის" ფაქტორი. თქვენი ბავშვი უკვე სკამებზე ძვრება და მაგიდაზე ასვლას ცდილობს. მას ჯერ სრულად არ აქვს გაცნობიერებული სიმაღლის შიში და მასთან დაკავშირებული საფრთხეები. შეამოწმეთ ფანჯრების საკეტები და მაღალი ავეჯი კედელზე დაამაგრეთ. თქვენი მთავარი ამოცანაა, ბავშვის გადაადგილების თავისუფლების შეზღუდვის გარეშე გარემო დაცემისგან მაქსიმალურად უსაფრთხო გახადოთ.') WHERE id = '6948a89f-6493-4c6e-9adb-708a1f0063cb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მე-13 თვის პირველი ათი დღე დაასრულეთ! თქვენი ბავშვი უკვე გააზრებულად ასრულებს მარტივ მითითებებს ("სათამაშო ყუთში ჩადე", "აქ მოდი"). ეს მისი როგორც მეტყველების, ისე სოციალური განვითარების მნიშვნელოვანი მაჩვენებელია. დღეს მასთან ერთად წაიკითხეთ წიგნი და სთხოვეთ, იპოვოს სურათზე გამოსახული საგნები. თქვენთან ხარისხიანად გატარებული ყოველი წუთი მისი განვითარებისთვის უდიდესი მხარდაჭერაა.') WHERE id = '702b1e33-f64a-46f4-9e5d-44efebebe748';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენმა ბავშვმა უკვე აღმოაჩინა სიტყვა "არას" ძალა! ამ პერიოდში ის ყველაფერს ეწინააღმდეგება და ამგვარად საკუთარ საზღვრებს ამოწმებს. ეს სიჯიუტე კი არა, მისი დამოუკიდებელ პიროვნებად ჩამოყალიბების ნაწილია. როდესაც თქვენ ეუბნებით "არას", შეიძლება განზრახ გაიმეოროს აკრძალული მოქმედება და თქვენს რეაქციას დააკვირდეს. ეცადეთ, სიმშვიდე შეინარჩუნოთ — თქვენი ემოციური სტაბილურობა საუკეთესო გზამკვლევია, რომელიც მას წესებს ასწავლის.') WHERE id = 'e0c32222-756f-4ca9-8533-fb5e6a6bf334';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სიარულის უნარის გაუმჯობესებასთან ერთად ბავშვი უკვე ცდილობს უკან-უკან სიარულს ან ნაბიჯების გადადგმისას ხელში სათამაშოს დაჭერას. ეს როგორც ფიზიკური ძალის, ისე ტვინის კოორდინაციის უნარის განვითარებაზე მიუთითებს. მიეცით ბორბლებიანი სათამაშოები, რომელთა მოქაჩვას და თან ტარებასაც შეძლებს. ასეთი თამაშები მისი ფეხის კუნთებს კიდევ უფრო აძლიერებს.') WHERE id = '49b402b9-bb72-400d-ac9d-7af091029dd1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებაში „პრეტენზიულობის“ პერიოდი გრძელდება. ბავშვმა შეიძლება საკვები, რომელიც გუშინ უყვარდა, დღეს იატაკზე გადააგდოს. ამ ეტაპზე ბავშვს მიანდეთ, თავად გადაწყვიტოს, „რამდენი ჭამოს“, თქვენ კი განსაზღვრეთ, „როდის და რა“ მიირთვას. სუფრასთან იძულების ნაცვლად სასიამოვნო გარემო შექმენით. გახსოვდეთ, რომ მისი კუჭი ჯერ კიდევ პატარაა და მისთვის რამდენიმე ლუკმაც კი შეიძლება საკმარისი იყოს.') WHERE id = '853086ca-90b3-4556-bd83-70b66fd42f49';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში პირველი „საპირისპირო ცნებები“ ჩნდება. ბავშვი უკვე იწყებს ისეთი განსხვავებების ვიზუალურად და შეხებით აღქმას, როგორებიცაა „დიდი-პატარა“ და „ცხელი-ცივი“. თამაშის დროს შეადარეთ საგნები და უთხარით: „ნახე, ეს დიდი ბურთია, ეს კი პატარა“. ასეთი მარტივი დიალოგები სწრაფად ავითარებს მის აბსტრაქტულ აზროვნებას და ლექსიკურ მარაგს.') WHERE id = '8381dd6a-9188-4a53-b0c0-fe9e5722bee4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„განშორების შიში“ (Separation anxiety) ამ თვეებში შესაძლოა პერიოდულად კვლავ გამოვლინდეს. როცა ოთახიდან გადიხართ, მისი ტირილი იმის ნიშანია, რომ მას თქვენ სჭირდებით. წასვლის წინ ყოველთვის უთხარით: „ნახვამდის, მალე დავბრუნდები“ და ჩუმად ნუ გაიპარებით. თქვენი გულწრფელობა განუმტკიცებს რწმენას, რომ „დედა რომც გაუჩინარდეს, აუცილებლად ბრუნდება“.') WHERE id = 'd51eadcf-ced3-43a7-a954-d65ad8f07d93';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახალი ნაბიჯი ნატიფი მოტორიკის განვითარებაში: თავსახურების მოხსნა და დახურვა. ცარიელი პლასტმასის ჭურჭელი და მისი თავსახურები ბავშვისთვის ყველაზე საინტერესო „თავსატეხად“ შეიძლება იქცეს. იმისათვის, რომ თავსახური სწორად მოარგოს, თითებისა და ყურადღების კოორდინირება სჭირდება, რაც მის ტვინში ახალ ნეირონულ კავშირებს ქმნის. მიეცით უფლება, ამ მარტივი სამზარეულოს ნივთებით ითამაშოს.') WHERE id = '6e7fc713-da58-436a-956b-2725c7ebe15b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვს უკვე შეუძლია საკუთარი გრძნობების ფიზიკურად გამოხატვა — ყვირილით, იატაკზე გაწოლით ან თქვენთან ჩახუტებით. ეს მიუთითებს, რომ ემოციების რეგულირების უნარი ჯერ კიდევ სუსტად აქვს განვითარებული. როცა გაბრაზებულია, ჩაიმუხლეთ მის გვერდით, რათა ერთ სიმაღლეზე აღმოჩნდეთ, და უთხარით: „ახლა გაბრაზებული ხარ, მესმის“. ამგვარად საფუძველს უყრით იმას, რომ მომავალში საკუთარი ემოციების მართვა შეძლოს.') WHERE id = '49f6d0be-6454-4212-a7b3-56294a93638b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კბილების ამოჭრის პერიოდში (როგორც წესი, ამ დროს შესაძლოა ძირითადი კბილები ამოუვიდეს) შეიძლება აღინიშნებოდეს ნერწყვის ჭარბი გამოყოფა და ღრძილების ტკივილი. ამან შესაძლოა მის ძილისა და კვების რეჟიმზე იმოქმედოს. მიეცით კბილების მოსაფხანი სათამაშოები ან გრილი ხილის ნაჭრები, რომელთა დაღეჭვასაც შეძლებს. თქვენი სითბო და მოთმინება დაეხმარება, ეს მტკივნეული პერიოდი უფრო ადვილად გადაიტანოს.') WHERE id = '48e458f5-c261-485d-bb67-d4e81e9a6931';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილის დროს შეიძლება "აქტიური მოძრაობები" შეინიშნებოდეს. ბავშვი ძილში შეიძლება გადაბრუნდეს, ადგილი შეიცვალოს ან მოულოდნელად წამოჯდეს. მისი ტვინი ძილში დღის განმავლობაში ნასწავლ ყველა ახალ მოძრაობას "ავარჯიშებს". თუ არ ტირის, ნუ ჩაერევით. მიეცით საშუალება, თავად იპოვოს კომფორტული პოზა და ძილი განაგრძოს.') WHERE id = '5ccc44b7-6be9-42e8-9051-5aba385dfbb3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, მე-13 თვის შუაში ხართ! თქვენს ბავშვს უკვე სრულად ესმის მარტივი თხოვნები და თქვენთვის "დახმარებაც" კი სურს (მაგალითად, სათამაშოს ყუთში ჩადება). ნუ ჩაუქრობთ ამ ენთუზიაზმს და ყოველი მცირე დახმარებისთვის გულწრფელად შეაქეთ. თქვენი მხარდაჭერა დაეხმარება, მომავალში უფრო პასუხისმგებლიან და თავდაჯერებულ პიროვნებად ჩამოყალიბდეს. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '2f2ae51c-beef-4df3-9d10-cb7325ea4331';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი კოვზის გამოყენებას უკვე უკეთ ახერხებს. მართალია, საკვების ნაწილი ჯერ კიდევ იატაკზე იყრება, მაგრამ ბავშვი მაჯის მოძრაობებს უკვე უკეთ აკონტროლებს. მიეცით მეტი შესაძლებლობა, დამოუკიდებლად ჭამოს. როდესაც ხვდება, რომ დანაყრდა და საკვებს გვერდზე სწევს, ეს ნიშნავს, რომ შიმშილისა და დანაყრების შინაგან სიგნალებს უსმენს. ეს მომავალში ჯანსაღი კვების ჩვევების ჩამოყალიბებისთვის ძალიან მნიშვნელოვანია.') WHERE id = '45554d06-2e09-4223-93a8-104614df2f0c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'თქვენი ბავშვი უკვე გააზრებულად ცდილობს "დახმარებას". მაგალითად, სათამაშოებს ყუთში ალაგებს ან რაღაცას გაწვდით. ეს სოციალური პასუხისმგებლობის განცდის პირველი ნიშნებია. ყოველთვის, როცა რამეს მოგიტანთ, უთხარით: "დიდი მადლობა, ძალიან დამეხმარე". ასეთი შექება ბავშვს აგრძნობინებს, რომ საჭირო და უნარიანია.') WHERE id = '5614d8e1-6798-45a7-8bfd-239e88293a49';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ახალი შიშების გაჩენა: 13-14 თვის ბავშვებს შეიძლება მოულოდნელად მტვერსასრუტის ხმის, სიბნელის ან უცხო ადამიანების შეეშინდეთ. ეს წარმოსახვისა და გარემოს აღქმის განვითარებას უკავშირდება. ნუ დასცინებთ მის შიშს და ნუ ეტყვით: "აქ რა არის საშიში?" უბრალოდ მის გვერდით იყავით, ჩაეხუტეთ და აგრძნობინეთ, რომ უსაფრთხოდაა. დროთა განმავლობაში ეს შიშები გაივლის.') WHERE id = '320f797a-413e-4747-8432-a77c70f8f1ae';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"პინცეტური მოჭიდება" უკვე იმდენად განვითარებულია, რომ თქვენს ბავშვს წიგნის ფურცლების (ჯერჯერობით სქელი ფურცლების) სათითაოდ გადაშლა შეუძლია. ეს ხელს უწყობს როგორც ნატიფი მოტორიკის განვითარებას, ისე წიგნებისადმი ინტერესის გაღვივებას. განაგრძეთ მისთვის ფერადი და დიდი ილუსტრაციების მქონე წიგნების კითხვა. სთხოვეთ, დაასახელოს სურათზე ნანახი საგნები და ამგვარად ხელი შეუწყვეთ მეტყველების განვითარებას.') WHERE id = '3f0fc8bf-420a-4d0f-acf7-ab2d58fa2a4b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე მუსიკის გაგონებისას სხეულს რიტმულად ამოძრავებს ან ტაშს უკრავს. რიტმის შეგრძნება მჭიდროდ არის დაკავშირებული ტვინის მათემატიკურ და ენობრივ ცენტრებთან. იცეკვეთ მასთან ერთად, დაუკარით ტაში და აჰყევით სხვადასხვა რიტმს. ეს ერთდროულად ფიზიკური აქტივობაცაა და სახალისო საქმიანობაც, რომელიც თქვენ შორის ემოციურ კავშირს აძლიერებს.') WHERE id = '22fc8a33-8e0b-4e79-86f9-460a94db933b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ურთიერთობაში „ემპათიის“ პირველი ნიშნები: როცა მოწყენილი ჩანხართ ან ფეხს რამეს მიარტყამთ, ბავშვი შეიძლება მოვიდეს, შეგეხოთ, ჩაგეხუტოთ ან თავისი სათამაშო მოგცეთ. ეს მიანიშნებს, რომ ის სხვების გრძნობების აღქმას იწყებს. მის ამ მზრუნველ ქცევას უპასუხეთ სიტყვებით: „დიდი მადლობა, ძალიან კეთილი ხარ“. თანაგრძნობის მარცვალი სწორედ ამ ასაკში ითესება.') WHERE id = '993a5a5e-046b-489d-bd9d-9580428e1cdc';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცითი მეხსიერება“ და ძიება: ბავშვმა უკვე იცის, სად არის დამალული მისი საყვარელი სათამაშო. ითამაშეთ მასთან დამალობანას უფრო რთული ვარიანტები. მაგალითად, სათამაშო ყუთში ჩადეთ და ზემოდან პირსახოცი გადააფარეთ. დაბრკოლებების გადალახვით სათამაშოს პოვნა ბავშვს პრობლემების გადაჭრის უნარს უვითარებს. ეს პატარა „გამარჯვებები“ მის თავდაჯერებას ზრდის.') WHERE id = '63dfa4ff-f8c9-4a30-bd0e-f8d086dd0898';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უსაფრთხოების შეხსენება: ბავშვს უკვე ყველაფერზე აძრომა სურს — დივნებზე, სკამებზე, თაროებზე... მას ჯერ სრულად არ ესმის სიმაღლესთან დაკავშირებული საფრთხე. დარწმუნდით, რომ მძიმე ავეჯი კედელზე საიმედოდ არის დამაგრებული, კიბეებთან კი დამცავი ბარიერებია დამონტაჟებული. მნიშვნელოვანია, ბავშვს უსაფრთხო გარემო შეუქმნათ ისე, რომ სამყაროს კვლევის სურვილი არ ჩაუხშოთ.') WHERE id = 'cc4b37ce-4e2e-4d58-a313-414b2395c5eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „გამეორების“ პერიოდი. ბავშვმა შეიძლება თქვენ მიერ წარმოთქმული სიტყვების ბოლო მარცვლების გამეორება სცადოს. მაგალითად, როცა თქვენ ამბობთ „წყალი“, მან შეიძლება თქვას „ალი“ ან „წყალი“. ყოველთვის სწორად და მკაფიოდ ესაუბრეთ. საგნების ნამდვილი სახელების გამოყენება, ბავშვური სიტყვების ნაცვლად, ხელს უწყობს მისი ლექსიკური მარაგის სწორად ჩამოყალიბებას.') WHERE id = 'd1034aae-153e-40ef-b35f-875a226037db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 13 თვე შესრულდა! თქვენი ბავშვი უკვე სრულად ავლენს თავის ნებას, ხასიათსა და სიყვარულს, როგორც „ტოდლერი“ (ბავშვი, რომელმაც სიარული დაიწყო). დღეს მასთან ერთად იატაკზე წამოწექით და უბრალოდ მის მიერ არჩეული თამაშით გაერთეთ. მასთან ხარისხიანად გატარებული ყოველი წუთი მისი მომავალი ბედნიერების საფუძველია. თქვენ შესანიშნავი დედა ხართ!') WHERE id = '4d58b019-ad51-4763-b775-1cff7a5c244e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კეთილი იყოს თქვენი მობრძანება მე-14 თვეში! ამ თვეში ბავშვი როგორც ფიზიკურად, ისე ემოციურად მეტ „დამოუკიდებლობას“ მოითხოვს. ის უკვე მტკიცედ გაჩვენებთ, სად სურს წასვლა და რისი ჭამა არ უნდა. ეს მისი პიროვნების განვითარების მნიშვნელოვანი ეტაპია. დღის განმავლობაში შესთავაზეთ მცირე არჩევანი (მაგალითად, „ვაშლს შეჭამ თუ მსხალს?“). არჩევანის შესაძლებლობა შეამცირებს მისი პროტესტის ტალღას და თავდაჯერებას გაუზრდის.') WHERE id = '05712130-29d6-4028-9cd7-1eeae1f8b5f6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე უფრო ოსტატურად აწყობს საგნებს ერთმანეთზე (მაგალითად, კუბებით კოშკს აგებს). ეს მხოლოდ თამაში არ არის — ასე ის მიზიდულობის ძალას, წონასწორობასა და სივრცით მიმართებებს შეისწავლის. როდესაც კოშკი იშლება, ბავშვი „მიზეზშედეგობრივ“ კავშირს იაზრებს. მიეცით სხვადასხვა ზომისა და ფერის კუბები, რათა ამ მნიშვნელოვან შემეცნებით პროცესს ხელი შეუწყოთ.') WHERE id = '0c30df46-8b8a-4974-a5d4-fa643bc0045f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მოემზადეთ მეტყველებაში „სიტყვების აფეთქებისთვის“! ბავშვი უკვე ყოველდღე ახალ ბგერებს ან სიტყვებს სწავლობს. ის გარშემო არსებულ საგნებზე თითით მიგანიშნებთ და ელოდება, რომ მათ დაასახელებთ. რაც უფრო მეტ საგანს ასახელებთ, მით უფრო სწრაფად იზრდება მისი პასიური ლექსიკური მარაგი (სიტყვები, რომლებიც ესმის), ვიდრე აქტიური მარაგი (სიტყვები, რომლებსაც ამბობს). მუდმივად ესაუბრეთ — ეს მისი მეტყველების განვითარების დაჩქარების საუკეთესო გზაა.') WHERE id = '462a5499-02c0-46d8-9b87-781f37471081';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'იწყება „ჩემია!“ პერიოდი. ბავშვმა შეიძლება უარი თქვას თავისი სათამაშოების ან ნივთების სხვებისთვის მიცემაზე. ეს „საკუთრების“ ცნების ჩამოყალიბების პირველი ნიშნებია. ნუ აიძულებთ გაზიარებას სიტყვებით „უნდა გააზიარო“, რადგან მას ჯერ ბოლომდე არ ესმის, რას ნიშნავს გაზიარება. ამის ნაცვლად, რიგრიგობით თამაშის მაგალითით („ახლა შენი ჯერია, შემდეგ — მამის“) ასწავლეთ სოციალური წესები.') WHERE id = 'bf0454b9-f968-4795-a96d-a48966050e5d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური აქტივობა: ბავშვი უკვე ცდილობს კიბეზე ასვლას (ხშირად ოთხზე ან თქვენი ხელის დახმარებით). ეს აძლიერებს როგორც ფეხის კუნთებს, ისე კოორდინაციას. კიბეზე ყოველთვის მის გვერდით იყავით და ნუ დაგავიწყდებათ უსაფრთხოების დამცავი ბარიერების გამოყენება. თითოეული საფეხურის დაძლევა მისთვის დიდი „გამარჯვებაა“!') WHERE id = '6d0b9b84-0a2e-4b5d-941c-44ac3c78711f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლად კვების შემდეგი ნაბიჯი: ბავშვს უკვე შეუძლია ჭიქიდან წყლის დალევა ისე, რომ თითქმის არ დაღვაროს. ღია ჭიქიდან სმა მის ტუჩისა და ენის კუნთებს მეტყველებისთვის ამზადებს. თუ ჯერ კიდევ იყენებთ საწოვარიან ბოთლს, უკვე დროა, მასზე სრულად თქვათ უარი. ეს ძალიან მნიშვნელოვანია კბილების სწორად ჩამოყალიბებისა და სასის ჯანმრთელობისთვის.') WHERE id = '59bb00a9-cd0f-4293-859e-3a1c2a23e167';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში „ჯღაბნის“ ხელოვნება იწყება! ბავშვს უკვე შეუძლია ფანქრის დაჭერა და ქაღალდზე თამამი ხაზების გავლება. ეს ხელისა და თვალის კოორდინაციისა და წერისთვის მოსამზადებელი უნარების განვითარების ყველაზე ადრეული ეტაპია. მიეცით მას მსხვილი, ბავშვებისთვის უსაფრთხო ფანქრები და დიდი ზომის ქაღალდები. შეაქეთ მისი პირველი „შემოქმედებითი ნამუშევრები“ — ეს ხელოვნებისადმი ინტერესს გაუღვივებს.') WHERE id = '32044af7-f666-4ab4-a029-c8309f8e7a1b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „მიბაძვა“ უკვე უფრო რთულ სახეს იღებს. ბავშვმა შეიძლება მიბაძოს არა მხოლოდ თქვენ, არამედ სხვა ბავშვებსა და ტელევიზორში ნანახ პერსონაჟებსაც კი. როცა სახლს ალაგებთ, მასაც მოუნდება რამის გაწმენდა, ხოლო როცა საჭმელს ამზადებთ — რამის მორევა. მიეცით სათამაშო ცოცხი ან პლასტმასის ჭურჭელი და ჩართეთ „საოჯახო საქმეებში“. ეს მას პასუხისმგებლობის გრძნობას უყალიბებს.') WHERE id = '0d48495d-8dfc-4d4f-a65f-4e2b54b5955c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილის დროს შესაძლოა „ძილის რეგრესია“ (დარღვევა) გამოვლინდეს. ამის მიზეზი ხშირად ახალი ფიზიკური უნარებია (უფრო სწრაფად სიარული, ცოცვა) ან განშორების მზარდი შფოთვა. თუ ბავშვი ღამით იღვიძებს და გეძახით, მშვიდად მიდით მასთან, ხელში აყვანის გარეშე დაამშვიდეთ და კვლავ დაძინებაში დაეხმარეთ. სტაბილური რეჟიმის შენარჩუნება ამ გარდამავალი პერიოდის გადალახვას გაგიადვილებთ.') WHERE id = '15f626ab-5c76-4c8c-ba7f-675666d5bc7d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 400 დღე შესრულდა! ეს მართლაც წარმოუდგენელი რიცხვია. თქვენი ბავშვი უკვე უბრალოდ „ჩვილი“ აღარ არის — საკუთარი აზრებით, ხასიათითა და სიცილით ის თქვენი ოჯახის თანასწორი და ყველაზე აქტიური წევრია. დღეს გაისეირნეთ მასთან ერთად მის საყვარელ პარკში და დააკვირდით, როგორი დიდი ინტერესით შეიცნობს სამყაროს. ამ გზაზე თქვენ მისი ყველაზე ძლიერი საყრდენი და ყველაზე მზრუნველი მასწავლებელი ხართ. ყოჩაღ, დედა!') WHERE id = 'cc5a3ed7-bfca-476b-b299-2377ba4200f3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '400-დღიანი მნიშვნელოვანი ეტაპი უკვე გადალახეთ! ამ პერიოდში ბავშვმა შეიძლება საკუთარი ტანსაცმლის (მაგალითად, ქუდის ან წინდის) გახდა სცადოს. ეს თავის მოვლის უნარების განვითარების პირველი ნაბიჯია. თუ მას რაიმეს ჩაცმა ან გახდა სურს, მიეცით დრო და ნუ ააჩქარებთ. იმის დანახვა, რომ რაღაცის გაკეთება დამოუკიდებლად შეუძლია, მის თვითშეფასებას (self-esteem) ყველაზე მეტად აძლიერებს.') WHERE id = 'c405a38b-5463-4f2f-a8fe-555b36296982';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე „ფუნქციური თამაშის“ ეტაპიდან „სიმბოლური თამაშის“ პირველ ნიშნებზე გადადის. მან შეიძლება სათამაშო დათუნიას „აჭამოს“ ან თოჯინა დააძინოს. ეს მისი წარმოსახვისა და ემპათიის უნარის განვითარებაზე მიუთითებს. ჩაერთეთ ამ თამაშებში: „დათუნიას მოშივდა? მოდი, ცოტა პიურე ვაჭამოთ“. ასეთი თამაშები მის სოციალურ და შემეცნებით განვითარებას აჩქარებს.') WHERE id = 'a392702d-a437-4a73-9212-0aa4a4ef5685';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ღამის ძილის „რეგრესია“ ან შიშები: მე-14 თვეში ზოგიერთ ბავშვს შეიძლება სიბნელის ან მარტო დარჩენის შიში გაუჩნდეს. ეს მისი კოგნიტიური განვითარებისა და გარემოს უფრო ღრმად აღქმის შედეგია. ძილისწინა რიტუალი (ზღაპრის წაკითხვა, იავნანას სიმღერა) უცვლელად შეინარჩუნეთ. თქვენი მშვიდი და თავდაჯერებული ხმა მას გადასცემს გზავნილს: „ყველაფერი კარგადაა, შენ უსაფრთხოდ ხარ“.') WHERE id = 'eff64bbb-3777-4339-9e6a-476beebba20d';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'გილოცავთ, 410 დღე უკვე გავიარეთ! ბავშვი ახლა ყოველდღე ახალ სიურპრიზს გიმზადებთ — ხან ახალ სიტყვას ამბობს, ხანაც ახალ მოძრაობას სწავლობს. დღეს მასთან ერთად იატაკზე წამოწექით და უბრალოდ მის მიერ შერჩეული თამაშით გაერთეთ. მის სამყაროში თქვენი ჩართვა მისთვის უდიდესი ბედნიერებაა. თქვენ შესანიშნავი დედა ხართ, რომელიც ამ გზას მოთმინებითა და სიყვარულით მიუყვება!') WHERE id = '21628582-4016-4734-a5cc-d731fc576c16';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე მთლიანად ჩაერთო „ცხოველების ხმების“ სამყაროში. დაუსვით კითხვები, მაგალითად: „ძაღლი როგორ ყეფს?“ ან „კატა რას ამბობს?“ ამ ხმების მიბაძვა მეტყველების აპარატს (ენისა და ტუჩების კუნთებს) მომავალში რთული სიტყვების წარმოსათქმელად ამზადებს. ხშირად ესაუბრეთ ცხოველების ილუსტრაციებიანი წიგნების დათვალიერებისას; სთხოვეთ, იპოვოს სურათზე გამოსახული ცხოველი და მის ხმას მიბაძოს.') WHERE id = '1ba32438-5f06-49eb-a326-d4e6c5037f1b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლად სიარულისას ბავშვი უკვე უფრო თავდაჯერებულია. ახლა ის სწავლობს ადგილზე შემობრუნებას, უკან ნაბიჯის გადადგმას ან სიარულის დროს დახრას და იატაკიდან სათამაშოს აღებას. ეს წონასწორობის შესანარჩუნებლად საკმაოდ რთული ვარჯიშია. შესთავაზეთ დაბრკოლებების (ბალიშების, პატარა ყუთების) გადალახვა. ასეთი ფიზიკური დაბრკოლებები აძლიერებს როგორც მის მსხვილ მოტორიკას, ისე პრობლემების გადაჭრის უნარს.') WHERE id = '67533bf8-42c4-4684-8990-79465e5ffca9';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „დასახელების“ ეტაპი: ბავშვს უკვე შეუძლია სხეულის ნაწილებზე (ცხვირზე, თვალზე, პირზე) მითითება. ბანაობისას ან ჩაცმისას ყველაფერი სიტყვებით აღწერეთ: „ახლა მარჯვენა ხელს ჩავაცვამთ“, „ეს შენი პატარა ცხვირია“. ეს მას საკუთარი სხეულის სქემის გააზრებასა და ლექსიკურ მარაგში არსებული სიტყვების ვიზუალურ გამოსახულებებთან დაკავშირებაში ეხმარება.') WHERE id = '616b6164-3d66-4e8e-8eaa-1c418d285de7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უპირატესობა მიანიჭეთ თამაშებს, რომლებიც „მიზეზ-შედეგობრივ“ კავშირს აჩვენებს. მაგალითად, სათამაშოებს, რომლებიც ღილაკზე დაჭერისას ხმას გამოსცემს, ან ყუთებს, საიდანაც თავსახურის გახსნისას რაღაც ჩნდება. ბავშვი ხვდება, რომ მისი ერთი მოქმედება გარემოში ცვლილებას იწვევს. ეს აღმოჩენა მას უყალიბებს განცდას, რომ შეუძლია „სამყაროზე გავლენის მოხდენა“, და თავდაჯერებულობას მატებს.') WHERE id = '8d3ed7f3-9547-466c-ba26-2f33141101eb';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „მარცვლების გაერთიანება“: თქვენი ბავშვი უკვე სხვადასხვა მარცვალს აერთიანებს და თავის ენაზე გრძელ „წინადადებებს“ აწყობს. მიუხედავად იმისა, რომ მისი სიტყვები ბოლომდე არ გესმით, ის უფროსების საუბრის ინტონაციას შესანიშნავად ბაძავს. ყურადღებით მოუსმინეთ და უპასუხეთ: „მართლა? შემდეგ რა მოხდა?“ ასეთი „დიალოგი“ აძლიერებს საკუთარი აზრის გამოხატვის სურვილს და მის გონებაში სიტყვების მარაგს ამდიდრებს.') WHERE id = '71d396d7-4d37-40f4-a3f7-9c1e6ac427ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლობა კვების დროს: თქვენს ბავშვს უკვე სურს, თავად გამოიყენოს ჩანგალი (ბავშვებისთვის უსაფრთხო). რბილი ხილის ან ბოსტნეულის ნაჭრების ჩანგალზე წამოგების მცდელობა მნიშვნელოვნად ავითარებს მის ხელისა და თვალის კოორდინაციას. სუფრასთან მცირე არეულობის მიუხედავად, მიეცით ამის შესაძლებლობა. ეს ხელს უწყობს როგორც მოტორული უნარების განვითარებას, ისე საკვების მიმართ დადებითი დამოკიდებულების ჩამოყალიბებას.') WHERE id = '333db3d2-14f1-4e63-a2dd-abc9df47ccf2';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„კატეგორიები“ შემეცნებით განვითარებაში: თქვენი ბავშვი უკვე იწყებს ერთნაირი ფერის ან ერთი და იმავე სახეობის ნივთების გარჩევას. აჩვენეთ სხვადასხვა ბურთი ან მანქანა და ჰკითხეთ: „სად არის მეორე ბურთი?“ ის მსგავსებების პოვნას დაიწყებს. ეს მისი ლოგიკური აზროვნების საფუძველია. ითამაშეთ მასთან თამაში, რომელშიც სახლის ნივთებს ფერის ან ზომის მიხედვით დააჯგუფებთ.') WHERE id = 'e2b8df1f-c1e3-4ba1-a168-83dfc3901148';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„დახმარების სურვილი“ სოციალურ უნარებში: თუ თქვენს ბავშვს სურს, მოგბაძოთ და რამე გაწმინდოს ან მოგიტანოთ, მიეცით პატარა „დავალებები“. მაგალითად: „თუ შეიძლება, ეს საფენი მომაწოდე“. როცა გრძნობს, რომ გეხმარებათ, თავს დიდ და საჭირო ადამიანად აღიქვამს. ეს ძალიან მნიშვნელოვანია, რათა მომავალში პასუხისმგებლობის გრძნობა და თანამშრომლობის უნარი ჩამოუყალიბდეს.') WHERE id = 'dec6a9fe-e431-4948-b5e9-cde4811493c1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური განვითარება: თქვენი ბავშვი უკვე ცდილობს, ადგილზე იხტუნაოს ან მუსიკის რიტმზე მუხლების მოხრით იცეკვოს. ეს აძლიერებს როგორც წონასწორობის შეგრძნებას, ისე მსხვილ მოტორიკაში ჩართულ კუნთებს. იცეკვეთ მასთან ერთად და გაიმეორეთ მისი მოძრაობები. ეს ერთდროულად ფიზიკური ვარჯიშიცაა და ყველაზე სახალისო აქტივობაც, რომელიც თქვენს შორის ემოციურ კავშირს აძლიერებს.') WHERE id = 'f2ba7880-c8a0-44c4-9683-adcae62249c7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სივრცითი აღქმა“ და კონსტრუქტორები: თქვენი ბავშვი კუბებს უკვე მხოლოდ ერთმანეთზე კი არ აწყობს, არამედ მათგან „კედლების“ ან მარტივი ფორმების შექმნასაც ცდილობს. მიეცით სხვადასხვა ზომის კონსტრუქტორის ბლოკები. ასეთი თამაშები ავითარებს როგორც მის შემოქმედებით უნარებს, ისე პრობლემების გადაჭრის უნარს. როდესაც კოშკი დაინგრევა, გაიღიმეთ და უთხარით: „მოდი, კიდევ ერთხელ ვცადოთ!“ — ეს ასწავლის, რომ წარუმატებლობის არ შეეშინდეს.') WHERE id = '3bcda1a7-5185-49d5-9cff-a4657ec214ad';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვების მხრივ ბავშვს უკვე შეუძლია ოჯახის სუფრაზე არსებული თითქმის ყველაფრის ჭამა (ნაკლებმარილიანი და დანამატების გარეშე). მიეცით საშუალება, დამოუკიდებლად გამოიყენოს თავისი პატარა ჩანგალი და კოვზი. საკვების უშუალოდ ხელით შეხება (მისი ტექსტურის აღქმა) ამცირებს ბავშვის პრეტენზიულობას საკვების მიმართ. ირგვლივ დასვრა ნორმალურია — მთავარია, ბავშვმა დამოუკიდებლად ჭამის ჩვევა გამოიმუშაოს.') WHERE id = '724fdd08-1982-44c9-81ad-e2e9e494133c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილ მოტორიკაში "აცმის" უნარი: ბავშვი უკვე ცდილობს დიდი მძივების ძაფზე აცმას (მეთვალყურეობის ქვეშ!) ან რგოლების პირამიდაზე ჩამოცმას. ეს მოძრაობები მნიშვნელოვნად აუმჯობესებს თითების კუნთების კოორდინაციას. მიეცით სხვადასხვა ფერისა და ფორმის რგოლები და თან ხმამაღლა დაასახელეთ ფერები და ზომები (დიდი-პატარა).') WHERE id = '9a5df16b-402c-4293-a449-95f97975e102';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში "მიბაძვა" უკვე უფრო გაცნობიერებულია. როცა თქვენ ტელეფონით საუბრობთ, ბავშვიც იღებს რაიმე ნივთს და ყურთან მიაქვს; როცა თმას ივარცხნით, ისიც მსგავს მოძრაობას იმეორებს. ასე სწავლობს ბავშვი ყოველდღიური ცხოვრების რიტუალებს. მიეცით უსაფრთხო საყოფაცხოვრებო ნივთებით (პლასტმასის სავარცხელი, სათამაშო ტელეფონი) თამაშის უფლება და დაეხმარეთ სამყაროს შეცნობაში.') WHERE id = 'ffb2b034-66cc-4cea-967c-b8e6e4f363c4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წიგნის კითხვა უკვე ინტერაქტიულ აქტივობად იქცა. ბავშვს თავად სურს გვერდების გადაფურცვლა და სიხარულით რეაგირებს სურათზე დანახულ ნაცნობ საგნებზე. როცა ეკითხებით: "სად არის აქ მანქანა?" და ის თითით მიუთითებს, ეს აჩვენებს, რამდენად გაუძლიერდა ვიზუალური მეხსიერება და ყურადღება. ჩვევად აქციეთ ყოველ საღამოს რამდენიმე წუთის განმავლობაში წიგნის კითხვა.') WHERE id = 'c199a72c-c2fe-4afe-b5cc-41415b0a5808';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'უსაფრთხოების შეხსენება: ბავშვს უკვე ძალიან მოსწონს ყველგან აცოცება. მან შესაძლოა სკამები საფეხურებად გამოიყენოს და მაგიდაზე ავიდეს. დარწმუნდით, რომ სახლში ყველა მძიმე ავეჯი კედელზე საიმედოდ არის მიმაგრებული, ხოლო ბასრი კუთხეები — დაცული. ბავშვის თავისუფლად მოძრაობა უსაფრთხო გარემოში უნდა იყოს უზრუნველყოფილი, რათა თქვენც მშვიდად შეძლოთ მისთვის თვალყურის დევნება.') WHERE id = '4ee9c2b3-c8ac-4ff5-98d9-426713c0d86e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციურ განვითარებაში "ნებისყოფის გამოცდა": როცა ბავშვი სასურველს ვერ იღებს, შესაძლოა ტირილით ან იატაკზე გაწოლით გამოხატოს პროტესტი. ამ პერიოდში მასთან კამათის ნაცვლად უფრო ეფექტურია მისი ყურადღების სხვა საინტერესო რამეზე გადატანა. მშვიდი ტონით უთხარით: "ახლა გაბრაზებული ხარ, მაგრამ სათამაშო უნდა დააბრუნო" და ამგვარად დაარქვით სახელი მის გრძნობებს. თქვენი სიმშვიდე მისთვის საუკეთესო მაგალითია.') WHERE id = '3cd65486-2777-46ac-9963-b43596b260f8';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვის მეხსიერება უკვე უფრო დიდხანს ინახავს მოვლენებს. მას შეუძლია გაიხსენოს და იპოვოს სათამაშო, რომელიც რამდენიმე საათის (ან თუნდაც დღის) წინ დამალეთ. ეთამაშეთ თამაში „იპოვე დაკარგული ნივთი“. ეს ავითარებს როგორც მის მეხსიერებას, ისე ვიზუალური ძიების უნარს. როცა იპოვის, გულწრფელად შეაქეთ, რათა წარმატებით მიღებული სიამოვნება იგრძნოს.') WHERE id = '41a34496-6a48-46a1-9bab-58d653fd4147';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი სულ უფრო ხშირად ცდილობს დამოუკიდებლად ჩაცმას. ის უკვე ცდილობს ფეხსაცმლის ჩაცმას, ქუდის დახურვას ან შარვლის ტოტების მოქაჩვას. ხელს ნუ შეუშლით და ნუ ააჩქარებთ. თუნდაც ტანსაცმელი უკუღმა ჩაიცვას, უთხარით: „შენ თვითონ გააკეთე, ყოჩაღ!“ ეს მისი დამოუკიდებლობის პირველი საფუძვლებია.') WHERE id = '114533c6-2065-42b8-8349-baf02171f30b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „სიტყვათა შეთანხმებების“ საწყისი ეტაპი: ბავშვმა შეიძლება უკვე სცადოს ორი სიტყვის ერთმანეთთან დაკავშირება (მაგალითად, „მამა, გარეთ“ ან „მომეცი წყალი“). თუ ჯერ სიტყვებს არ აერთიანებს, თავად მიეცით მაგალითი. როცა ის ამბობს „მანქანა“, თქვენ უპასუხეთ: „დიახ, დიდი მანქანა“ და ამგვარად გააფართოეთ მისი ნათქვამი. ეს ბავშვის ტვინში გრამატიკული სტრუქტურების ჩამოყალიბებას უწყობს ხელს.') WHERE id = '66c20a78-018b-46e0-a413-b9d7d652fd0b';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური კოორდინაცია: ბავშვს უკვე უფრო თავდაჯერებულად შეუძლია სიარული, როცა ხელში რაიმე უჭირავს. მას შეუძლია ერთდროულად იაროს და სათამაშოც გაჩვენოთ. მოუწყეთ „დაბრკოლებების ზოლი“: იატაკზე დადებულ ბალიშებს შემოუაროს ან დაბალ ყუთს გადააბიჯოს. ეს აძლიერებს როგორც წონასწორობას, ისე საკუთარი სხეულის მართვის შეგრძნებას (პროპრიოცეფციას).') WHERE id = '9f5b4f9d-6c12-455d-adaa-8991ef34a4ef';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე თვითონ ვირჩევ!“ პერიოდი. ტანსაცმლის ან საკვების არჩევისას ბავშვს ორი უსაფრთხო ვარიანტი შესთავაზეთ. მაგალითად: „ლურჯი წინდების ჩაცმა გინდა თუ წითლის?“ ეს მეთოდი ბავშვს კონტროლის შეგრძნებას უჩენს და მომავალში შესაძლო „სიჯიუტის კრიზისების“ თავიდან აცილებას უწყობს ხელს. არჩევანის გაკეთება გადაწყვეტილების მიღების უნარის საფუძველია.') WHERE id = '3e2f13ff-1204-4de3-91f9-ba0a61eced52';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფი მოტორიკის გასავითარებელი „დახარისხების“ თამაშები. ბავშვმა შეიძლება უკვე დაიწყოს კუბების ფერის ან ზომის მიხედვით დახარისხება. მიეცით სხვადასხვა ფერის ჭურჭელი და აჩვენეთ, როგორ მოათავსოს მათში შესაბამისი ფერის სათამაშოები. ეს თამაში სწრაფად ავითარებს როგორც მის ლოგიკურ აზროვნებას, ისე ფერების აღქმას.') WHERE id = '1833bec9-62a3-4273-aaa3-6cb2d5b43918';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „ემპათია“ ძლიერდება. ბავშვი შეიძლება შეწუხდეს, როდესაც სხვა ბავშვის ტირილს ხედავს, ან თქვენთან მოვიდეს და ჩაგეხუტოთ. ეს აჩვენებს, რომ ის უკვე გრძნობს სხვების ემოციებს. დაარქვით მის ამ განცდებს სახელები ისეთი წინადადებებით, როგორიცაა: „დიახ, შენი მეგობარი ახლა ცოტათი მოწყენილია“. ემოციების ამოცნობა ემოციური ინტელექტის პირველი საფეხურია.') WHERE id = 'da7ee871-54fe-4caf-9b11-def1fe5482db';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებისას „სასარგებლო ნივთების გამოყენება“. ბავშვი უკვე უფრო ოსტატურად არჭობს საკვებში საბავშვო ჩანგალს (პლასტმასის/რბილს). მიეცით რბილი ბანანის ან მოხარშული სტაფილოს ნაჭრები, რომლებშიც ჩანგლის ჩარჭობას შეძლებს. ეს აქტივობა არა მხოლოდ ხელის კოორდინაციას აძლიერებს, არამედ კვების პროცესსაც მისთვის სახალისო „უნარების გამოცდად“ აქცევს.') WHERE id = '451ba512-8b9d-44f7-915a-a7f1ea152f7c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: „წარმოსახვითი თამაში“ (თითქოს მართლა ასე ხდება). ბავშვს უკვე შეუძლია თავი მოაჩვენოს, თითქოს ცარიელი ჭიქიდან „წყალს სვამს“, ან სათამაშო მანქანის „ვრ-ვრ“ ხმა გამოსცეს. შეუერთდით მას ამ თამაშებში: „მანქანა სად მიდის? მაღაზიაში?“. ეს აძლიერებს როგორც მის შემოქმედებით უნარებს, ისე მოვლენებს შორის ლოგიკური კავშირების დანახვის უნარს.') WHERE id = '58538226-5b39-4731-8bc6-1e9881002e44';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნებისყოფა და საზღვრები: ბავშვი უკვე რეაგირებს სიტყვაზე „არ შეიძლება“, თუმცა ზოგჯერ განზრახ იმეორებს აკრძალულ მოქმედებას და თან თქვენ გიყურებთ. ამით ის თქვენს მოთმინებასა და წესების უცვლელობას ამოწმებს. შეინარჩუნეთ სიმშვიდე, მაგრამ იყავით მტკიცე. ის, რაზეც ერთხელ თქვით „არ შეიძლება“, სხვა დროს არ დაუშვათ, რათა ბავშვისთვის წესები სრულიად მკაფიო იყოს.') WHERE id = 'ccb50bdf-5e11-4253-a1c0-79b7eb2fe4d0';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვმა უკვე აღმოაჩინა უკან-უკან სიარული ან ადგილზე შემობრუნება. ეს მოძრაობები მის წონასწორობის შეგრძნებასა და სხეულის კოორდინაციას ახალ დონეზე აჰყავს. შეუქმენით პირობები, რომ ეს ახალი უნარები დაბრკოლებებისგან თავისუფალ, ფართო სივრცეში გამოსცადოს. სხეულის მართვის უნარის ზრდასთან ერთად მისი თავდაჯერებულობაც ძლიერდება.') WHERE id = '527b5771-2c14-44f3-9a1f-7d0335d59d5a';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში განზრახვის გამომხატველი სიტყვები: ბავშვი უკვე არა მხოლოდ საგნებს ასახელებს, არამედ თავის სურვილებსაც ერთი სიტყვით გამოხატავს. მაგალითად, როდესაც ის თქვენ გიყურებთ და ამბობს „კარი“, ეს შეიძლება ნიშნავდეს: „გარეთ გასვლა მინდა“. უპასუხეთ მისი ნათქვამის გაფართოებით: „ჰო, შენ კარზე მიუთითებ? მოდი, ეზოში (ad-da) გავიდეთ“. ეს ზრდის მის სურვილს, დაამყაროს კომუნიკაცია.') WHERE id = '1b9f532e-6857-454f-9361-0a20bbd28a5f';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კიბეზე ასვლა უკვე მისი ერთ-ერთი ყველაზე დიდი გატაცებაა. მას შეუძლია კიბეზე ხოხვით ან თქვენი ხელის დახმარებით, ფეხზე მდგომი ავიდეს. ეს მოძრაობა ავითარებს როგორც მსხვილ მოტორიკას, ისე სიმაღლის აღქმას. კიბესთან ყოველთვის მის გვერდით იყავით და დარწმუნდით, რომ სახლში დამცავი ბარიერები დაკეტილია.') WHERE id = '74e3ddee-b891-4ccd-91d8-7ed95452703e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი ქაღალდზე "ჯღაბნისას" უკვე უფრო მკაფიო ხაზებს ავლებს. მან შეიძლება წრიული მოძრაობებით ან სწორი ხაზების გავლება სცადოს. მიეცით დიდი ზომის ქაღალდი და სქელი, არატოქსიკური ფანქრები, რომელთა ხელში დაჭერაც მისთვის მოსახერხებელი იქნება. ეს წერის მომავალი უნარებისა და ხელისა და თვალის კოორდინაციის უმნიშვნელოვანესი საფუძველია.') WHERE id = '4d091261-3f36-4fe5-bf63-cb391c17abb5';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '"მე თვითონ!" ეტაპი: ბავშვს უკვე ძალიან სურს ხელების დაბანა, კბილების გახეხვა (ჯერჯერობით მხოლოდ ჯაგრისის ღეჭვით) ან მაგიდის გაწმენდა. მხარი დაუჭირეთ მის ინტერესს ჰიგიენური ჩვევების მიმართ. დაუდგით პატარა საფეხური, რათა საჭირო ადგილებს მისწვდეს, და მიეცით თქვენი მოქმედებების გამეორების საშუალება. ეს მას თვითმოვლის უნარებს უყალიბებს.') WHERE id = '1d418a62-b096-44ed-98d7-1fbf38ca6e83';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ თამაშებში "მიბაძვა" უფრო რთული ხდება. როდესაც თქვენ სახლს გვით, მასაც სურს, რაიმე აიღოს და დაგეხმაროთ. მიეცით ბავშვის ზომაზე მორგებული პატარა "დასუფთავების ხელსაწყოები". საოჯახო საქმეებში ამგვარი "დახმარება" აგრძნობინებს, რომ ოჯახის საჭირო წევრია, და მასში პასუხისმგებლობის გრძნობას ავითარებს.') WHERE id = '9c0e73ce-723f-4070-afbc-322de1ae0633';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კოგნიტიური განვითარება — "კონსტრუქტორები": ბავშვს უკვე შეუძლია 3-4 კუბი (ბლოკი) ერთმანეთზე დააწყოს და "კოშკი" ააშენოს. ეს მოითხოვს როგორც ყურადღების კონცენტრაციას, ისე სიზუსტეს. როდესაც კოშკი დაინგრევა, ხალისიანად გამოხატეთ ემოცია, რათა ბავშვმა წარუმატებლობა თამაშის ნაწილად აღიქვას. ეს მას პრობლემების გადაჭრის უნარსა და ხელახლა ცდის სურვილს უძლიერებს.') WHERE id = '80068b19-aaa1-4996-ba9d-5b3777ebce0c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მუსიკა და რიტმი: ბავშვი სხვადასხვა რიტმს უკვე განსხვავებული მოძრაობებით პასუხობს. სწრაფი მუსიკის დროს უფრო აქტიურად მოძრაობს, მშვიდი მუსიკისას კი ირწევა. მასთან ერთად ითამაშეთ "რიტმის აყოლის" თამაშები — დაუკარით ტაში და ფეხები იატაკზე დააბაკუნეთ. ეს შესანიშნავად ავითარებს როგორც სმენით აღქმას, ისე სხეულის კოორდინაციას.') WHERE id = '83fcfed7-5b83-4a68-8d79-7654a496f70e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვების დროს ბავშვი უკვე მეტ დამოუკიდებლობას ითხოვს და კოვზით საკვების ამოღებაც უკეთ გამოსდის. შესთავაზეთ პატარა ნაჭრები, რომელთა ჩანგალზე წამოგებაც შეუძლია (fork-friendly). დამოუკიდებლად ჭამა ეხმარება, ამოიცნოს დანაყრების შეგრძნება და მეტი ინტერესი გამოიჩინოს სხვადასხვა ტექსტურის მქონე საკვების მიმართ.') WHERE id = '369e5ef8-dd84-4005-92a0-3547d1d81f03';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური საზღვრები: როცა ბავშვს "არას" ეუბნებით, მან შეიძლება განზრახ გაიმეოროს იგივე მოქმედება, რათა თქვენი რეაქცია შეამოწმოს. ამ პერიოდში ყველაზე მნიშვნელოვანია სიმშვიდისა და სიმტკიცის შენარჩუნება. თუ რამეზე უთხარით, რომ "არ შეიძლება", ყოველ ჯერზე იგივე ტონითა და ერთნაირად გაიმეორეთ. წესების უცვლელობა ბავშვს უსაფრთხოებისა და წესრიგის განცდას უყალიბებს.') WHERE id = '3b03f902-43dc-4352-9de9-99e2a04d004c';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვი უკვე იმდენად სწრაფად დადის, რომ ზოგჯერ სირბილსაც ცდილობს. თუმცა, რადგან წონასწორობის უნარი ჯერ სრულად არ აქვს ჩამოყალიბებული, შეიძლება ხშირად დაეცეს. გარემოს შესასწავლად შეუქმენით მეტი სწორი და რბილი სივრცე (ხალიჩა, ბალახიანი ადგილი). სირბილისას ხელების გვერდებზე გაშლით წონასწორობის შენარჩუნების მცდელობა მისი ფიზიკური განვითარების ბუნებრივი ნაწილია.') WHERE id = 'd5bd999f-15a8-4225-95dc-a3e29ec9bb65';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეხსიერების განვითარება: ბავშვს უკვე ახსოვს, სად ინახება სხვადასხვა ნივთი. მაგალითად, იცის, რომ ფეხსაცმელი დერეფანშია, სათამაშოები კი — ყუთში. როდესაც ეკითხებით: "სად არის შენი ფეხსაცმელი?", შესაბამისი ადგილისკენ გახედვა ან ხელით მინიშნება შემეცნებითი უნარების გაძლიერებაზე მიუთითებს. თამაშის დასრულების შემდეგ სათამაშოები ერთად დააბრუნეთ თავის ადგილას, რათა ბავშვს წესრიგის დაცვის ჩვევა ჩამოუყალიბდეს.') WHERE id = '821949a4-99c0-456c-ba4e-1768b6ba56ba';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში "ცხოველებისა და მათი ხმების გარჩევა". ბავშვი სურათზე ნანახ ცხოველს უკვე არა მხოლოდ ცნობს, არამედ შესაძლოა დაუკითხავადაც გამოსცეს მისი ხმა. წიგნის კითხვისას დიალოგი განაგრძეთ სიტყვებით: "შეხედე, ეს ძროხაა. ძროხა როგორ ამბობს?" ეს სწრაფად ამდიდრებს როგორც მის სმენით მეხსიერებას, ისე ლექსიკურ მარაგს.') WHERE id = 'ca9adb43-fa2c-4743-a4c9-e39c4eb29777';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ნატიფ მოტორიკაში "დაწყობა და ჩამოცმა". ბავშვს უკვე შეუძლია 5-6 კუბი ერთმანეთზე დააწყოს და უფრო მაღალი კოშკები ააგოს. ამასთან, რგოლების დიდიდან პატარამდე ჩამოცმის მცდელობები სივრცით აღქმას უვითარებს. ხედავთ, როგორ სიამოვნებს კოშკის დაშლა? ეს მისი განცდის — "მე შემიძლია სამყაროს შეცვლა" (მიზეზ-შედეგობრივი კავშირი) — ყველაზე მხიარული გამოვლინებაა.') WHERE id = 'c50f5774-0c5b-40a4-8f99-e817382c1b20';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებისას — „ჩემი ჭიქა“. ბავშვი უკვე თითქმის მზად არის, ღია ჭიქიდან წყალი ისე დალიოს, რომ თითქმის არაფერი დაღვაროს. მიეცით ბავშვის ზომის, გადაყირავებისადმი მდგრადი (მძიმე ძირიანი) პლასტმასის ჭიქები. წყლის დამოუკიდებლად დალევა მის ყბის კუნთებს მეტყველებისთვის ამზადებს და დამოუკიდებლობის განცდას უვითარებს.') WHERE id = 'cdcb59ac-ce34-4644-9101-dd165efadbd4';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„მე“-სა და „შენ“-ს შორის განსხვავების გაცნობიერება. როდესაც ბავშვი სარკეში საკუთარ თავს ხედავს, მას უკვე არა როგორც „სხვა ბავშვს“, არამედ როგორც საკუთარ თავს აღიქვამს. თუ ცხვირზე პატარა ფერად ლაქას დაახატავთ და სარკეში ჩაახედებთ, ის საკუთარ ცხვირზე ლაქის მოშორებას შეეცდება. ეს ერთ-ერთი ყველაზე მნიშვნელოვანი ტესტია, რომელიც მისი თვითცნობიერების (self-awareness) განვითარებაზე მიუთითებს.') WHERE id = 'e44171a6-fe71-458b-9f01-6422077e41b3';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„თანამშრომლობა“ სოციალურ ქცევაში: ბავშვს უკვე სიამოვნებს თქვენთვის რაიმეს მოტანა, სამზარეულოში თქვენ გვერდით ყოფნა და „დახმარება“. მიეცით პატარა და უსაფრთხო დავალებები: „შეგიძლია, ეს ქაღალდი ნაგვის ურნაში ჩააგდო?“. როდესაც გრძნობს, რომ გეხმარებათ, თავს უფრო მნიშვნელოვან და ღირებულ პიროვნებად აღიქვამს.') WHERE id = 'd9f30f7c-bdc1-4054-b9fc-312496a93a19';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური გამბედაობა: ბავშვს უკვე შეუძლია ისწავლოს დივნიდან იატაკზე დამოუკიდებლად ჩამოსვლა (უკან-უკან ჩამოსრიალებით). აჩვენეთ, როგორ გააკეთოს ეს უსაფრთხოდ. სიმაღლიდან დამოუკიდებლად ჩამოსვლის სწავლა აუმჯობესებს სხეულის კონტროლსა და რისკების შეფასების უნარს. ყოველთვის ახლოს იყავით და დაიცავით დაცემისგან.') WHERE id = '594432bd-57c7-413f-839d-cbac2143ecbe';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ემოციური კრიზისები და „ტანტრუმები“. როდესაც ბავშვს ყველაფრის დამოუკიდებლად გაკეთება სურს და არ გამოსდის, შეიძლება მოულოდნელად გაბრაზდეს. ეს დაძაბულობა იმითაა გამოწვეული, რომ მისი სურვილები და ფიზიკური შესაძლებლობები ჯერ სრულად არ ემთხვევა ერთმანეთს. ასეთ დროს ჩაეხუტეთ და მშვიდად დაარქვით მის ემოციას სახელი: „გაბრაზდი, რადგან სათამაშო ვერ ააწყვე, მესმის შენი“.') WHERE id = '52ab2a35-efc6-4dfa-ae8e-dd8d45265cbf';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, '„სიტყვების გამეორება“ მეტყველებაში. ბავშვი უკვე ცდილობს, თქვენ მიერ ნათქვამი ყოველი სიტყვის შემდეგ თავის ენაზე რაღაც თქვას. ეს ენის ათვისების ყველაზე აქტიური ეტაპია. მასთან მარტივი, მოკლე და გასაგები წინადადებებით ისაუბრეთ. თქვენ მისთვის მეტყველების მთავარი მაგალითი ხართ. დღეს ერთად წაიკითხეთ მისი საყვარელი ზღაპარი და ეცადეთ, სურათზე დამალული დეტალები იპოვოთ.') WHERE id = '36237c33-88c9-45f0-bb2f-74a99cfea0e7';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ბავშვმა შესაძლოა უკვე არა მხოლოდ შეაგროვოს ნივთები, არამედ მათი ფერის მიხედვით დაჯგუფებაც დაიწყოს. მიეცით მას ორი სხვადასხვა ფერის ჭურჭელი და აჩვენეთ, როგორ მოათავსოს იმავე ფერის კუბები შესაბამის ჭურჭელში. ეს თამაში სწრაფად ავითარებს მის ვიზუალურ აღქმასა და ლოგიკურ აზროვნებას. ყოველი სწორი არჩევანისას შეაქეთ და წაახალისეთ.') WHERE id = 'c99fbd76-3509-452c-bb85-8931e45ac6e6';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'დამოუკიდებლად ჩაცმის მცდელობები უფრო მიზანმიმართული ხდება. ბავშვმა შეიძლება წინდის გახდა შეძლოს ან ქუდის თავზე დახურვა სცადოს. დაუთმეთ დრო ამ „თვითმომსახურების“ სავარჯიშოებს. თუ არ დააჩქარებთ და შესაძლებლობას მისცემთ, რაღაც დამოუკიდებლად გააკეთოს, ეს ყველაზე მეტად განუმტკიცებს საკუთარი თავის რწმენას (თვითშეფასებას).') WHERE id = '2ee741f0-6ac8-462c-a88b-0f41a8cfe7f1';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წარმოსახვის განვითარება: იწყება „ვითომ“ თამაშები (Pretend play). ბავშვმა შეიძლება მოაჩვენოს, თითქოს ცარიელი სათამაშო ჭიქიდან წყალს სვამს, ან თოჯინა „დააძინოს“. ეს აბსტრაქტული აზროვნების პირველი ნიშნებია. ჩაერთეთ მის თამაშებში და ახალი კითხვებით (მაგალითად, „დათუნია მშიერია?“) წაახალისეთ მისი წარმოსახვა.') WHERE id = 'b84b66d1-b1ba-4c15-8fdd-579e274e0daa';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'ფიზიკური მოქნილობა: ბავშვი უკვე ცდილობს ადგილზე ახტომას (ხტომას). შესაძლოა, ჯერჯერობით ორივე ფეხი ერთდროულად ვერ მოსწყდეს იატაკს, თუმცა მუხლების მოხრა-გაშლით ამ მოძრაობას იმეორებს. ეს შესანიშნავი ვარჯიშია მსხვილი მოტორიკისთვის საჭირო კუნთებისა და წონასწორობის შეგრძნების გასაძლიერებლად. იცეკვეთ მასთან ერთად რიტმული მუსიკის თანხლებით.') WHERE id = 'd53255ec-c9a7-49ab-9a79-7b2313a09598';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'მეტყველებაში „კითხვა-პასუხის“ ეტაპი იწყება. ბავშვი უკვე მიუთითებს ნივთებზე და ამბობს: „ეს რა არის?“ (ან საკუთარ ენაზე მსგავს ბგერას წარმოთქვამს). თქვენ კი მოთმინებით დაასახელეთ ყველაფერი: „ეს წითელი მანქანაა“, „ეს დიდი ხეა“. თუ მის ცნობისმოყვარეობას უპასუხოდ არ დატოვებთ, ეს ლექსიკური მარაგის აქტიურად გამდიდრებაში დაეხმარება.') WHERE id = 'd7ddb1ff-3688-4df3-8111-1494d13b6470';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'წვრილი მოტორიკა — „ფანქრის დაჭერა“. ბავშვი თანდათან იწყებს ფანქრის არა ხელისგულით, არამედ თითებით დაჭერას. ქაღალდზე უფრო მკაფიო წრეებს ან ხაზებს ავლებს. მიეცით ბავშვებისთვის უსაფრთხო, სქელი ფერადი ფანქრები და გაუფართოეთ „შემოქმედებითი“ სივრცე. ეს მომავალში წერის უნარის საფუძველი გახდება.') WHERE id = '785f6c05-389d-4b59-bf24-09d238f78a91';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'სოციალურ ქცევაში „გაზიარების სირთულე“. ამ ასაკში „ჩემია“ განცდა ძალიან ძლიერია. თუ ბავშვს არ სურს თავისი სათამაშო სხვა ბავშვს მისცეს, ეს ეგოიზმი კი არა, განვითარების ეტაპია. ნუ აიძულებთ მას გაზიარებას; ამის ნაცვლად, აჩვენეთ „მორიგეობით თამაშის“ წესი. დროთა განმავლობაში ის ამ სოციალურ წესს აითვისებს.') WHERE id = '634d745d-5157-4467-b6ab-326f97a6818e';
UPDATE public.mommy_daily_messages SET message_ka = COALESCE(message_ka, 'კვებისას „საჭმელი ხელსაწყოების გამოყენება“. ბავშვს უკვე უფრო ზუსტად შეუძლია ბავშვის ჩანგალი საკვებს (მაგალითად, მოხარშულ სტაფილოს ან კარტოფილს) ჩაარჭოს და პირამდე მიიტანოს. ეს უნარი არა მხოლოდ ხელისა და თვალის კოორდინაციას აძლიერებს, არამედ ეხმარება, თავი დამოუკიდებელ პიროვნებად იგრძნოს.') WHERE id = '3cb1db52-5d88-4edb-a3ab-0984a9450809';